      sourceTextSnippet: "6 第1章 【创一 1】「起初，神创造天地。」 • 圣经以这句庄严、华美、简洁的话开始，首先宣告神是宇宙万物的 唯一创造者，祂的创造既是完整的、又是完美的。 • 「起初」就是时间的开始，神的创造开始了时间，没有创造就没有 时间。 • 「神 ELOHIM」原文是复数，可能像英国女王自称为复数的「朕 We」， 是表示尊贵。希伯来语的「神」在两河流域泛指各种神明，单数是 Eloah（申 三十二 15）或 El（创三十五 1），双数是 Eloahi，三个以上的众数是 Elohim。 圣经中的「ELOHIM」主要是用来称呼独一的真神，可能暗示祂是三位一体 的神。 • 「创造」原文是单数，表明虽然用众数「ELOHIM」来称呼真神，但 祂是独一的造物主。「神」原文在第一章出现了 31 次，祂是创造过程中唯 一的主角，不像异教神话中的造物者需要借助别的神。「创造」是指从无 到有的创造（1、21、27 节），而不是在已有材料基础上的「制造」（16、 25、26、31 节）。 • 「天」原文是复数，包括天空、太空。希伯来文没有 「宇宙」这个 词，而是使用「天地」这样的「两极化」修辞方式来表达「宇宙」的概念。 • 第 1 节的希伯来原文由 7 个词（中文也是 7 个字）、28 个字母组成， 看似简单，其实隐含了许多令人惊讶的数学特性。现代科学告诉我们，神 在创造中使用的表达方式正是数学，整个第一章都充满了数学规律。 上图：创世记第 1 章第 1 节的希伯来原文有 7 个词、28 个字母，除了 第 4 个词是虚词，共有 6 个词是有实际意义的，并且所有字母所代表的数 码之和是 2701。",
