      sourceTextSource: "pdftotext",
      sourceTextSnippet: "7 1、7 在圣经里代表完整，神在第 7 日进入安息。 2、6 在圣经里代表完美，神用 6 日创造了完美的世界。6 在数学上是 第 1 个完美数（Perfect Number，即 6 是其真因子 1、2、3 之和：6=1+2+3。 目前只发现 48 个完美数，都以 6 或 28 结尾）。 3、6 在数学上又是第 3 个三角数（Triangular Number，即 6=1+2+3）。 圣经里的重要数字大都与 3 和三角数有关，3 是属神的数字（十八 2、9-10）。 4、6 由两个三角数 3 组成：神 6 日的创造过程分成两个 3 日来对比， 第 1 至 3 日对比第 4 至 6 日，前 3 日是分开，后 3 日是充满；神把所创造 的星体、植物、动物都简单地分成 3 类。 5、28 在数学上是第 2 个完美数（即 28 是其真因子 1、2、4、7、14 之和：28=1+2+4+7+14），第 7 个三 角数（即 28=1+2+3+4+5+6+7）。 6、2701=73*37，这对镜像数 隐含了 3（三位一体）和 7（七日创 造），而且是第 73 个三角数。 上图：3 是第 2 个三角数 （Triangular Number），6 是第 3 个 三角数，28 是第 7 个三角数。 上图：2701 是第 73 个 三 角 数 （Triangular Number）， 即 2701=1+2+3+4+ … … +73，可以排成以上三 角形。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：3 是第 2 个三角数 （Triangular Number），6 是第 3 个 三角数，28 是第 7 个三角数。",
