      sourceTextSource: "pdftotext",
      sourceTextSnippet: "10 保护。可能此时大量彗星、太空冰块撞击原始地球，地面被水覆盖，在浓 厚的灰尘、云雾遮蔽下，一片黑暗。 上图：原始地球的艺术想象图。碳（Carbon）、氢（Hydrogen）、氧（Oxygen） 与氮（Nitrogen）这四种元素是地球生命 96%的物质组成部分： 1、碳可以组成精密的大型有机化合物，构成复杂的生命机制。 2、氢与氧可以合成水，提供生命运行、生存的环境。 3、分解碳水化合物可以释放出大量化学能量，提供生命的燃料。 4、这四种元素组成了氨基酸，是维持生命必须的蛋白质的基本成分。 但这四种元素中，只有氧大量存在于地壳中，其他在常温时以气体形 式存在，如氢气、氮气、二氧化碳、甲烷、氨与水。在靠近太阳的区域， 因为温度高，这些气体很难在原始地球中存在。虽然少量气体可能存在于 地壳之下，经火山喷发进入大气层，但科学家们认为，地球上大量的水、 碳、氮主要来自远离太阳热力的地方，包括彗星、木星与土星间的冰块、 木星与火星之间小行星带的冰块。这些彗星和冰块被木星、土星的引力影 响而撞击原始地球，为地球带来足够的水分和生命所需的碳、氮。 【创一 3】「神说：『要有光』，就有了光。」 • 神没有使用科学术语，只说「要有光，就有了光」，否则连科学家 也很难看懂创造的过程。《创世记》第一章的遣词用句十分简单，其中的",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：原始地球的艺术想象图。碳（Carbon）、氢（Hydrogen）、氧（Oxygen） 与氮（Nitrogen）这四种元素是地球生命 96%的物质组成部分： 1、碳可以组成精密的大型有机化合物，构成复杂的生命机制。 2、氢与氧可以合成水，提供生命运行、生存的环境。 3、分解碳水化合物可以释放出大量化学能量，提供生命的燃料。 4、这四种元素组成了氨基酸，是维持生命必须的蛋白质的基本成分。 但这四种元素中，只有氧大量存在于地壳中，其他在常温时以气体形 式存在，如氢气、氮气、二氧化碳、甲烷、氨与水。在靠近太阳的区域， 因为温度高，这些气体很难在原始地球中存在。虽然少量气体可能存在于",
