      imageNum: 10,
      objectId: "246 0",
      storedFilename: "p020_img010_725x335.png",
      storedRelativePath: "CMC-01_副本/p020_img010_725x335.png",
      storedAbsolutePath: "/Users/simon/OHB/Resources/01_创世记/文档图片内容提取_20260515_121143/CMC-01_副本/p020_img010_725x335.png",
      sourceTextSource: "pdftotext",
      sourceTextSnippet: "12 能是希伯来的修辞方法，表示每一个有开始、有结束的工作阶段。第七日 神歇了一切创造的工，所以就不再提「有晚上，有早晨」（二 1-3）。 • 「有晚上，有早晨，这是头一日」的希伯来原文是 7 个词，神在前 六日都是用 7 个词宣告结束当日的创造之工（5、8、13、19、23、31 节）， 而第七日则是先用 7 个词宣告神完成了造物大工，又用 7 个词宣告神进入 安息（二 2）。 • 这里的「日」原文可以指 24 小时的一天，也可以指一个阶段（赛六 十一 2）。 • 分出「昼、夜」并不是一件简单的事情，地球必须保持合适的自转 周期和日地距离，使太阳光照变化的规律适合生命的生存。如果地球离太 阳太远或太近、自转太快或太慢，就不能维持合适「昼、夜」气温变化， 也不能维持植物的光合作用。 上图：绿色部分是天文学家在太阳系圈定的「恒星宜居带（Circumstellar Habitable Zone）」，范围是 0.99-1.7 天文单位（即日地距离，约 1.5 亿公里）。 在这个范围内，行星的表面温度能使水维持液态。金星、地球、火星都处 在太阳系宜居带里，但并非在宜居带里的行星都适合生命居住，还需要合 适的体积、自转周期、公转周期。 1、如果地球离太阳太近（如金星），水会蒸发。 2、如果地球离太阳太远（如火星），水会结冰。 3、如果地球的体积太小，就会像水星一样没有足够的引力留住大气层； 也会像火星一样铁核过早冷却，停止火山、地震与板块活动等地质活动， 地表会非常崎岖，到处是高山和深谷。大气层中就不能出现维持温度的二 氧化碳，也不能形成能调节气候的大面积海洋。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：绿色部分是天文学家在太阳系圈定的「恒星宜居带（Circumstellar Habitable Zone）」，范围是 0.99-1.7 天文单位（即日地距离，约 1.5 亿公里）。 在这个范围内，行星的表面温度能使水维持液态。金星、地球、火星都处 在太阳系宜居带里，但并非在宜居带里的行星都适合生命居住，还需要合 适的体积、自转周期、公转周期。 1、如果地球离太阳太近（如金星），水会蒸发。 2、如果地球离太阳太远（如火星），水会结冰。 3、如果地球的体积太小，就会像水星一样没有足够的引力留住大气层； 也会像火星一样铁核过早冷却，停止火山、地震与板块活动等地质活动，",
      sourceEvidencePage: 20,
