      sourceTextSource: "pdftotext",
      sourceTextSnippet: "16 7），这是神在创造过程中最后一次为受造物命名，其他的命名工作都交给 了人。 上图：1968 年 12 月 24 日圣诞夜，阿波罗 8 号宇航员 William Anders 从环月轨道 上拍摄的地球照片。阿波罗 8 号是人类首次环绕月球轨道的载人航天任务。1968 年 12 月 24 日，阿波罗 8 号向地球进行了实况电视转播，全世界有四分之一人口观看。阿波 罗 8 号上的三位宇航员朗读了 KJV 版创世记第一章 1-10 节，令全世界震惊。以下是三 位宇航员的电视转播全文： William Anders: 阿波罗 8 号有一个给地球上所有人的消息。起初神创造天地。地 是空虚混沌。渊面黑暗。神的灵运行在水面上。神说，要有光，就有了光。神看光是 好的，就把光暗分开了。 James Lovell：神称光为昼，称暗为夜。有晚上，有早晨，这是头一日。神说， 诸水之间要有空气，将水分为上下。神就造出空气，将空气以下的水，空气以上的水 分开了。事就这样成了。 神称空气为天。有晚上， 有早晨，是第二日。 Frank Borman：神 说，天下的水要聚在一 处，使旱地露出来。事 就这样成了。神称旱地 为地，称水的聚处为海。 神看是好的。这里是阿 波罗 8 号，在结束时， 我们想说晚安，好运， 圣诞快乐，上帝保佑你 们，在地球上的每一个 人。 上图：1969 年，美 国邮政局发行了邮票 （Scott # 1371）纪念阿",
