      sourceTextSource: "pdftotext",
      sourceTextSnippet: "创世记 9:12 30 “这就是我与地上一切有血肉之物立约的记号 不再被洪水灭绝，也不再有洪水毁坏地了。“上 帝说：°“我与你们并你们这里的各样活物所 了。” 立的永约是有记号的。“我把°虹放在云彩中， 这就可作我与地立约的记号了。19我使云彩盖 挪亚和他的儿子们 地的时候，必有虹现在云彩中，15/我便记念我 18 出方舟挪亚的儿子就是”闪、含、雅弗。含 与你们和各样有血肉的活物所立的约，水就 是迦南的父亲。”9这是挪亚的三个儿子 再不泛滥毁坏一切有血肉的物了。16虹必现在 后裔分散在全地。 云彩中，我看见，就要记念我与地上各样有 20挪亚作起农夫来，栽了一个葡萄园。2他喝 血肉的活物所立的永约。”1上帝对挪亚说：了园中的酒便醉了，在帐棚里赤着身子。22.迦南 9:120本书17:119:13e结1：.28：［启 4:3. 10:1］ 9:15 利26:42，45；王上8:23；结16:60］9:169本书17:7,13，19 9:18h本书5:32,10:1 9:19 本书10:32 各族列国分布图 约主前2200年 创10 章所载许多族群的身份相对明确。一般来说，含的后代住在北非和地中海东岸，闪的后代住在美索不达米亚和 阿拉伯半岛，雅弗的后代则住在欧洲和小亚细亚的广大地区。",
