      storedAbsolutePath: "/Users/simon/OHB/Resources/01_创世记/文档图片内容提取_20260515_121143/CMC-01_副本/p025_img015_400x346.png",
      sourceTextSource: "pdftotext",
      sourceTextSnippet: "17 波罗 8 号任务和朗读创世记。 【创一 11】「神说：『地要发生青草和结种子的菜蔬，并结果子的树 木，各从其类，果子都包着核。』事就这样成了。」 • 「各从其类」这四个字在本章内共提了 10 次，表明各种生物并非是 进化来的，而是神按照「各从其类」的原则造出来的，互不混淆，并且一 造出来就是成熟的个体，不存在「先有鸡还是先有蛋」的问题。 • 神的创造是有秩序的，混乱、混淆从来不是神的心意，祂通过不断 的「分开」来显明祂的心意。没有「分开」就没有生命，生命的出现，就 是分别光暗、上下、海地的结果；属灵生命的开端，也在于人照着神的心 意分别为圣。 • 圣经根据植物和人类的关系，只把植物分成三类：「青草」、「菜 蔬」和「树木」，这样简单的分类，使每个人都能理解。 • 「果子都包着核」直译是「果子里有种子」，强调「各从其类」， 可以代代相传。 【创一 12】「于是地发生了青草和结种子的菜蔬，各从其类；并结果 子的树木，各从其类；果子都包着核。神看着是好的。」 生命不是毫 无目的地进化 出来的，而是根 据神的心意设 计而成的，所以 「神看着是好 的」。现代分子 生物学已经发 现，生命的复杂 性远远超过了 19-20 世纪进化 论者的想象，即 使是进化论者 认为最简单的",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：ATP 合酶机是所有的生命活动所依赖的蛋白复合体。我们若了解 ATP 合酶机令人难以置信的运行机制，就很难相信这样精密的纳米机器是自 然进化出来的。 1、ATP（三磷酸腺苷）为细胞内几乎所有的活动提供能量，包括：制 造 DNA（脱氧核糖核酸）、RNA（核糖核酸）和蛋白质，清理废物，运输化 学物质进出细胞，以及细胞内运输。 2、ATP 由一种被称为 ATP 合成酶的蛋白复合体合成，它是世界上最小 的旋转马达，存在于细菌细胞内膜、线粒体和叶绿体的内膜，负责制造 ATP。 3、ATP 合成酶制造 ATP 的原料是 ADP（二磷酸腺苷）和磷酸分子。ATP",
