      sourceTextSource: "pdftotext",
      sourceTextSnippet: "19 把「第三日」当作适合举行婚礼的双福日（Double Blessings / ）， 迦拿的婚筵就是在「第三日」举行的（约二 1）。 【创一 14】「神说：『天上要有光体，可以分昼夜，作记号，定节令、 日子、年岁，」 • 「作记号」包括东西南北和时刻。「定节令」包括春、夏、秋、冬 和祭祀的节期。「日子」指地球自转一周为一日。「年岁」指地球绕日公 转一周为一年。 • 神是启动时间、设立气候的那位，祂安排宇宙万物的一切规律。日 月星辰是神用来为人「作记号」的，而不是异教神话中决定、预测人命运 的（耶十 2）。 • 用天上的星体来「分昼夜，作记号，定节令、日子、年岁」，并不 是一件简单的事情，除了地球要有稳定的自转和公转周期，还需要有透明 的大气层，可以看到日月星辰。地球是太阳系中唯一一个有透明大气层的 行星，不但是生命最好的家园，也是最好的宇宙观测站。这不是偶然的， 而是神有意让我们能观测、认识祂伟大的创造（诗十九 1-4），发展出现代 科学。 上图：火星的天空照片。这样的天空是无法进行天文观测的。事实上， 太阳系的各大行星中只有地球有透明的大气层，适合观测宇宙： 1、火星的大气层充满着尘埃、天空黄褐色，不适合观测宇宙。 2、金星的大气层有硫酸形成的不透明云，不适合观测宇宙。 3、太阳系正好位于银河系中恒星和星云密度稀薄的区域，否则再好 的天文望远镜也看不清宇宙。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：火星的天空照片。这样的天空是无法进行天文观测的。事实上， 太阳系的各大行星中只有地球有透明的大气层，适合观测宇宙： 1、火星的大气层充满着尘埃、天空黄褐色，不适合观测宇宙。 2、金星的大气层有硫酸形成的不透明云，不适合观测宇宙。 3、太阳系正好位于银河系中恒星和星云密度稀薄的区域，否则再好 的天文望远镜也看不清宇宙。",
