      sourceTextSource: "pdftotext",
      sourceTextSnippet: "20 【创一 15】「并要发光在天空，普照在地上。』事就这样成了。」 异教神话认为太阳是生命之源，光照是太阳最重要的作用。但圣经却 把「发光在天空，普照在地上」的作用放在最后，提醒我们不要崇拜天上 的日月星辰。 【创一 16】「于是神造了两个大光，大的管昼，小的管夜，又造众星，」 • 「两个大光」就是太阳和月亮。古代埃及敬拜日神，两河流域敬拜 月神，他们又认为星星会左右人的命运，在他们的语言中，日、月、星的 名字就是日神、月神和各种星神的名字。因此圣经故意不用希伯来文通用 的「日、月、星」来称呼它们，只是称之为「两个大光、众星」，强调它 们都是神所「造」的，目的是为神的计划服务（14 节）。它们的「管」只 是光照，并不带着异教神话中的神奇能力。神甚至都没给它们命名。 • 本章里的「造」原文有两种：1、21、27 节的「造」原文意思是「创 造」；16、25、26、31 节的「造」原文意思是「制造」。 • 科学家认为地球的原始大气成分和土星卫星泰坦相似，泰坦星大气 层里的甲烷经太阳光照射，形成了不透明的气胶霾层，所以原始地球的大 气层很可能也是不透明的。此时在植物的光合作用下，地球的氧气浓度逐 渐升高、甲烷浓度降低，空气渐渐清晰，可以看见日月星辰。 • 圣经根 据星体 和人类 的关系， 只把星 体分成 三类： 「大的 管昼」、 「小的 管夜」和 「众星」，",
