      sourceTextSnippet: "22 有铁可以构成生命所需要的血红素。 3、如果太阳系位于银河系的球状星团和螺旋星系的螺旋臂，恒星密度 太高，离附近的恒星太近，由于附近恒星的引力干扰和其他影响，地球的 轨道变化、受小行星撞击、超新星爆发、脉冲星的影响也越大。 4、太阳系相对孤立，围绕银心运转的轨道接近圆形，公转周期和银河 系的自转周期接近，避免了频繁穿越球状星团和螺旋臂的危险。 5、生命需要复杂的化学成分，而这些化学成分必须包含氢、氦和锂之 外的金属元素。目前唯一所知的能制造金属并使其散之于宇宙中的机制是 超新星的爆炸，大部分的恒星都缺乏金属，金属量充足、能维持复杂生命 生存的主恒星位于太阳系所在的大螺旋星系的边沿区域。 6、如果太阳系的金属元素含量太高，就可能产生巨大的行星，引发的 重力潮汐力会导致地球改变轨道和表面的形状，最终摧毁地球。 上图：太阳与各大行星的比例。科学家认为，太阳如果太大、太小、 太年轻或太古老，都会对地球上的生命有致命影响。在银河系中，只有 9% 的类似太阳的恒星。",
