      sourceTextSource: "pdftotext",
      sourceTextSnippet: "24 上图：日全食的形成示意图。太阳的直径是月球的 400 倍，太阳离地 球的距离也是月球离地球距离的 400 倍，所以才能在地球上观测到日全食。 如果没有日全食，人类就不可能研究太阳、验证相对论，也不可能发现恒 星的能源来自核聚变，今天的科技水平就会面目全非。 【创一 18】「管理昼夜，分别明暗。神看着是好的。」 【创一 19】「有晚上，有早晨，是第四日。」 【创一 20】「神说：『水要多多滋生有生命的物；要有雀鸟飞在地面 以上，天空之中。』」 【创一 21】「神就造出大鱼和水中所滋生各样有生命的动物，各从其 类；又造出各样飞鸟，各从其类。神看着是好的。」 「造」原文是单数，是「创造」（1、21、27 节）。「大鱼」原文是「大 的海洋生物」，古代中东神话中有很多巨大可怕的海怪，可以与诸神对抗， 比如利维坦（伯四十一 1 译为鳄鱼）、拉哈伯（伯九 13）或比蒙（伯四十 15-24 译为河马）。但圣经却启示，即使是最可怕的生物，也是出于神美善 之手，共享神的祝福（22 节）。 上图：澄江寒武纪岩层里的化石照片，证明当时有大量简单和复杂的 生物突然同时出现在海洋里，而不是从简单到复杂逐渐进化而成的。这一 现象被称为寒武纪生命大爆发（Cambrian Explosion），至今进化论者无法",
