      sourceTextSource: "pdftotext",
      sourceTextSnippet: "25 合理解释。中国云南省澄江化石地和加拿大 BC 省洛矶山脉的伯吉斯页岩 （Burgess Shale Formation）都发现了这种化石群，由于化石埋藏地质条件 特殊，不但保存了生物硬体化石，而且保存了清晰的软体组织印痕化石。 【创一 22】「神就赐福给这一切，说：『滋生繁多，充满海中的水； 雀鸟也要多生在地上。』」 • 神在前三日的创造是「分开」（4、7、9 节），在后三日的创造是「充 满」（17、22、28 节），显明祂是有秩序、有计划的神。 • 神用命令和赐福来保证动物的繁殖，并不需要异教神话中的魔法或 生殖的仪式去达成。动物和人同受神的赐福（22、28 节），为要成就神所 定的旨意，因此人不可滥杀动物，而要与动物一起分享神所赐的环境。 • 「雀鸟」原文是「飞行动物」，包括鸟类和能飞行的昆虫。 【创一 23】「有晚上，有早晨，是第五日。」 【创一 24】「神说：『地要生出活物来，各从其类；牲畜、昆虫、野 兽，各从其类。』事就这样成了。」 • 「牲畜」指人所能驯养的动物。「昆虫」指能爬行的生物。「野兽」 指人不能驯养的动物。 • 圣经根据动物和人类的关系，只把动物分成三类：「牲畜」、「昆 虫」和「野兽」，这样简单的分类，使每个人都能理解。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：产于热带美洲的「水桶兰」（Bucket Orchid）有非常独特的花粉 传播和授精机制。水桶兰复杂而精细的结构包括至少五项独立功能，并且 必须按正确的次序运作：1、吸引蜜蜂；2、使蜜蜂掉进水桶；3、植物腺分 泌液体注满水桶；4、提供隧道出口；5、在隧道内黏贴或除去花粉囊。缺 少任何一个装置，或者装置运作不正常，都不能完成花粉授精、传种接代。 而 Euglossa meriana 和 Euglossa cordata 这两个品种的雄蜂，也是为这项任务 而特别设计的，它们互相依存，缺一不可。进化论无法解释这些现象的起 源，创世记却告诉我们，这些花朵和蜜蜂在起初被创造和设计时，就已经 按这个方式去运作，「各从其类」，永不改变。",
      sourceEvidencePage: 34,
