      sourceTextSource: "pdftotext",
      sourceTextSnippet: "28 【创一 30】「至于地上的走兽和空中的飞鸟，并各样爬在地上有生命 的物，我将青草赐给他们作食物。』事就这样成了。」 本节并不表明动物原来都是素食的，可能是指植物是食物链的最低端， 所有的动物都直接、间接地以植物作食物，从神的圣手中得到喂养。 上图：三种形式的食物链，起点都是植物。 【创一 31】「神看着一切所造的都甚好。有晚上，有早晨，是第六日。」 • 神之前只说「好」，因为前五日的工作是为人类预备一个家。造了 人之后才说「甚好」，因为人是神创造计划中的焦点，是神创造的高峰， 具备神形象的人满足了神创造的心意。人应当好好守住自己在神计划中尊 贵的地位，不可把自己降到没有灵性的动物的地步。 • 我们相信《创世记》第一章，就不能相信无神论（没有神）、不可 知论（人没有办法知道有没有神）、泛神论（相信山川、草木、动物、石 头、人类、万物都有互相影响的灵魂）、多神论（相信世上有很多神）、 二神论（好神负责好事、坏神负责坏事；或者高层次的神造灵界，低层次 的神造物质界）、自然神论（神创造了宇宙，但不能或不愿掌控这个宇宙）， 就不应该参与新纪元运动（New Age Movement）的一切有关活动。",
