      sourceTextSource: "pdftotext",
      sourceTextSnippet: "29 第2章 【创二 1】「天地万物都造齐了。」 【创二 2】「到第七日，神造物的工已经完毕，就在第七日歇了祂一切 的工，安息了。」 • 世人需要「安息」，是因为疲倦。神「并不疲乏，也不困倦」（赛 四十 28），祂的安息是因为完成了创造的旨意和工作，因此心满意足、「安 息舒畅」（出三十一 17）。神在第七日「歇了」的是创造之工，祂从此不 再从无到有创造新的东西，直到第八日让祂的儿子基督从死里复活（可十 六 9），并带出了基督里「新造的人」（林后五 17）和「新天新地」（赛 六十五 17；六十六 22；启二十一 1）。但神从未停止护理之工，祂「做事 直到如今」（约五 17）。 • 「七」在圣经中表示完全。在创造的过程中，神 7 次宣告「好」（一 4、10、12、18、21、25、31），7 次宣告「事就这样成了」（一 7、9、11、 15、24、30，一 20 七十士译本），在「第七日」安息，并「赐福给第七日」 （3 节）。 • 在希伯来原文中，神在前六日都是用 7 个词宣告结束当日的创造之 工（一 5、8、13、19、23、31），而「第七日」则是先用 7 个词宣告「到 第七日，神造物的工已经完毕」，又用 7 个词宣告「就在第七日歇了祂一 切的工，安息了」，庄严而完全。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：1980 年爆发的圣海伦火山（Mount St. Helens），位于美国西雅 图附近。创造过程中的一「日」是一天还是一亿年，对于不受时间、空间 限制的造物主来说，并没有两样。但许多科学证据都表明，地球、太阳系 和宇宙的年龄并没有进化论者所假设的那么长，地质学家所倚赖的放射性 测年法建立在许多假设的基础上，所以并不绝对可靠。1992 年，有人从圣 海伦火山口采集了一块英安岩（Dacite），分成 5 个样品送到波士顿地质年 代（Geochron）实验室做钾氩分析。钾-氩测年法普遍适用于地质领域，其 原理是钾-40 会自发地衰变成氩-40，半衰期是 13 亿年。该测定法需要假设 钾-40 的半衰期恒定不变，起初岩石里没有任何氩-40，而且岩石形成后也没",
