      sourceTextSnippet: "32 创造时要万物进入「安息」的旨意。 • 前六日都以「有晚上，有早晨」作结束（一 31），但第七日却没有， 表明这「安息」是不受时间限制的。 上图：法国共和历（French Republican Calendar）是 1793 年法国大革命 期间启用的革命历法，目的是割断历法与基督教的联系。共和历规定每周 10 天，废除星期日，第 10 天才能休息。但人民始终无法习惯，1805 年被 拿破仑废除。当时的法国历史事件都是用这种历法记载的，如热月政变、 雾月政变等。每七日休息一日是神所定的规律，人无论如何试图摆脱，最 后都是注定失败的。",
