      sourceTextSnippet: "34 上图：1933 年一周 6 天的苏维埃历法。无论是 5 天、6 天还是 10 天一 周，无论是法国大革命还是十月革命，最后都抵挡不住神所定 7 天一周的 规律。 【创二 4】「创造天地的来历，在耶和华神造天地的日子，乃是这样，」 • 「造天地的日子」原文是「造地天的日子」（诗一百四十八 13）， 侧重在「地」的被造。 • 「耶和华」的希伯来原文是「 ，YHWH」，意思是「我是」或「自 有永有」（出三 14），也就是说：神是自己存在的，祂是永恒的存在，既 不是被造的，也不依靠任何别的存在而存在。「我是」和「自有永有」原 文是同一个词（ ）。神使用「耶和华」这个名字，向人启示祂是「自有 永有的」（出三 14），表明神与人的立约关系。 圣经从来不去证明神是存在的，因为那是在浪费时间，神一直在那里、 永远在那里，需要被证明的是各种被造物的存在。这与现代人的思路完全 相反，现代人认为各种被造物一直都存在，需要被证明的是神。但在摩西 写创世记的时代，以色列人都知道神是确实存在的，因为他们经历了神在 埃及降下十灾、分开红海、赐下吗哪。想要证明神的，都是没有经历过神 的人，凡是经历过神的人，是不需要证明神存在的：「到神面前来的人， 必须信有神，且信祂赏赐那寻求祂的人」（来十一 6）。",
