      sourceTextSource: "pdftotext",
      sourceTextSnippet: "35 「神」的希伯来原文是「 ，Elohim」，是对神的普遍性称呼，强 调神的伟大和能力，显明神是创造宇宙的全能者。古代巴比伦、埃及、荷 马史诗都有用多个名字称呼同一位神的习惯。 一 1 至二 3 是创造的概述，二 4-25 则是人受造的详述，为第三章人的 堕落作铺垫。这种平行故事是希伯来文学中刻意使用的手法，古代中东的 碑文展示了类似的文学风格：首先简扼地称扬统治者的英勇行为，继而详 细记述特别的胜利。 上图： 「耶和华」读音的由来。四字神名（Tetragrammaton）原文是「 ， YHWH」。古代希伯来文没有元音字母，只有 22 个辅音，因此不能根据字 母直接发音，和中文一样，每个字的读法都必须由老师教。四字神名只有 大祭司每年赎罪日进入至圣所祷告时，才能直接读出来。平时犹太人在说 话中用「主」（ ，音 Adonai）来代替。主后 70 年圣殿被毁，犹太祭司 传统中断，四字神名的正确读法就渐渐失传。 希 伯 来 文 的 元 音 符 号 通 用 之 后 ， 主 后 11 世 纪 的 犹 太 马 所 拉 文 本 （Masoretic Text）将「 ，Adonai」的元音符号标注在「 ，YHWH」上， 变成「 ，YaHoWaH」，提示应读为「主 Adonai」。文艺复兴时代，欧洲 人将「YaHoWaH」的辅音、元音结合起来，读成了「耶和华 Yehowah」。 近代圣经学者对照标示元音的古代希腊文的旧约译本，以及当时一些非犹",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图： 「耶和华」读音的由来。四字神名（Tetragrammaton）原文是「 ， YHWH」。古代希伯来文没有元音字母，只有 22 个辅音，因此不能根据字 母直接发音，和中文一样，每个字的读法都必须由老师教。四字神名只有 大祭司每年赎罪日进入至圣所祷告时，才能直接读出来。平时犹太人在说 话中用「主」（ ，音 Adonai）来代替。主后 70 年圣殿被毁，犹太祭司 传统中断，四字神名的正确读法就渐渐失传。 希 伯 来 文 的 元 音 符 号 通 用 之 后 ， 主 后 11 世 纪 的 犹 太 马 所 拉 文 本 （Masoretic Text）将「 ，Adonai」的元音符号标注在「 ，YHWH」上，",
