      sourceTextSnippet: "36 太人对该词读音的描述，认为发音可能是「雅威 YaHWeH」。 【创二 5】「野地还没有草木，田间的菜蔬还没有长起来；因为耶和华 神还没有降雨在地上，也没有人耕地，」 【创二 6】「但有雾气从地上腾，滋润遍地。」 【创二 7】「耶和华神用地上的尘土造人，将生气吹在他鼻孔里，他就 成了有灵的活人，名叫亚当。」 • 本节详述一 26 神造人的情形。组成人体的所有元素，都是从土中来 的，人的身体死后被分解，又重新归于土，与动物并没有不同。只有神的 生命气息，才能使人与动物区分出来，成为「有灵」的活人，有道德的观 念、灵性的需要和永生的渴望（传三 11），生来就有敬拜神的倾向。人与 动物的不同乃是「灵」，死后「尘土仍归于地，灵仍归于赐灵的神」（传 十二 7），要接受神的审判（来九 27），所以我们应该注重灵命的长进， 而不是只关心满足身体的需要。 •「亚当（ ，Adam）」字义是「人」，与「红土（ ，Adama）」 发音相近，只有元音不同。 • 神的创造不像各种异教神话中那样复杂而离奇，而是非常简洁：「祂 从一本造出万族的人」（徒十七 26），所有的人类都有共同的祖先；而撒 但对神计划的破坏，是「因一人的悖逆，众人成为罪人」（罗五 19）；照 样，神的救法是「因一人的顺从，众人也成为义了」（罗五 19）。 上图：这幅漫画讽刺进化论者不必为污染环境负责任，只要自己能生 存就行。创造论和进化论是两种完全不同的思想，都需要凭信心来接受，",
