      sourceTextSnippet: "38 妥善地「安置」人。今天每个重生信徒所面临的环境，也都是神按着祂的 美意所安排的（罗八 28）。伊甸园是快乐的地方，人的受苦并不是神的本 意，相反地，神要人「靠主常常喜乐」（腓四 4）。 【创二 9】「耶和华神使各样的树从地里长出来，可以悦人的眼目，其 上的果子好作食物。园子当中又有生命树和分别善恶的树。」 神在伊甸园中所预备的一切，目的都是为了让人得着供应和满足。神 创造了人的「灵与魂与身子」（帖前五 23），祂也同时预备了「悦人的眼 目」的大自然来满足人的「魂」，预备了「果子」来满足人的「身子」， 预备了「生命树」来满足人的「灵」。神不但让人享用祂的所是和所作， 也预备了「生命树和分别善恶的树」，让人有机会运用自由意志，做出正 确的选择。这两棵树代表人与神的关系中只有两种拣选，带出两条道路， 导致两样结局： 1. 吃「生命树」的果子代表拣选神，接受神的生命，一生与神联合、 根据神的生命而活，结局是永远与神同活（三 22；启二十一 3-4）。人堕落 以后，与神隔绝，一心靠自己满足「魂」和「身子」，「灵」却永远得不 着满足。人若与神恢复了准确的关系，「先求祂的国和祂的义」（太六 33）， 神起初的预备就会恢复在人的身上，「这些东西都要加给你们了」（太六 33），并且能在新耶路撒冷重享生命树（启二十二 2），得着「灵与魂与身 子」的完全满足，完全活出神的形象，恢复神造人的目的。 2. 吃「分别善恶的树」的果子代表拣选自己，拒绝神的生命，一生凭 着人自己的知识和标准来决定善恶、解决问题，结局是「必定死」（17 节）。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：苏美尔（Sumerian）生命树的壁画。「生命树」的记忆存在于各 个古代文明之中，以不同的形式出现在古代苏美尔人、埃及人、巴比伦人、 亚述人、中国人、印度人和乌拉尔图人等许多古代文明的文献和遗址里。 这从侧面佐证人类的祖先都来自伊甸园。",
