      sourceTextSource: "pdftotext",
      sourceTextSnippet: "40 原文是「伯拉」，是西亚最大、最长的河流，发源于亚美尼亚山区，流入 波斯湾，在旧约中通称「大河」。「底格里斯」和「幼发拉底」河所流过 的地方就是两河流域，即美索不达米亚。 上图：古代美索不达米亚平原。美索不达米亚（Mesopotamia）是古希腊人对 两河流域的称呼，两条河指幼发拉底河（Euphrates）和底格里斯河（Tigris），这 两条河发源于今天土耳其境内的安纳托利亚（Anatolia）山区，流经美索不达米亚 平原，在下游逐渐汇聚成阿拉伯河，流入波斯湾。两河之间的美索不达米亚是由 沙漠、山峦和大海环绕而成的平原，周围缺少天然屏障，历史上有许多民族在此 接触、入侵、融合，产生了人类最早的古文明，称为两河文明或美索不达米亚文 明。这两条河每年氾滥，所以下游土壤肥沃，富含有机物和矿物质，同时该地气 候干旱，需要用大规模的人力协作来进行灌溉，从事农业丰产。因此这里很早就 形成了成熟的文字、众多的城市及周围的农业社会，相继出现了欧贝德（Ubaid）、 乌鲁克（Uruk）、吾珥（Ur）、苏美尔（Sumer）、阿卡德（ Akkadian）、巴比伦 （Babylon）、亚述（Assyria）等古代文明，最终被波斯和希腊帝国所征服，渐渐 被人遗忘。从美索不达米亚到尼罗河（Nile）流域的新月形地带，被称为肥沃新月 （Fertile Crescent）。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：古代美索不达米亚平原。美索不达米亚（Mesopotamia）是古希腊人对 两河流域的称呼，两条河指幼发拉底河（Euphrates）和底格里斯河（Tigris），这 两条河发源于今天土耳其境内的安纳托利亚（Anatolia）山区，流经美索不达米亚 平原，在下游逐渐汇聚成阿拉伯河，流入波斯湾。两河之间的美索不达米亚是由 沙漠、山峦和大海环绕而成的平原，周围缺少天然屏障，历史上有许多民族在此 接触、入侵、融合，产生了人类最早的古文明，称为两河文明或美索不达米亚文 明。这两条河每年氾滥，所以下游土壤肥沃，富含有机物和矿物质，同时该地气 候干旱，需要用大规模的人力协作来进行灌溉，从事农业丰产。因此这里很早就 形成了成熟的文字、众多的城市及周围的农业社会，相继出现了欧贝德（Ubaid）、",
