      sourceTextSource: "pdftotext",
      sourceTextSnippet: "45 人长成神儿子的成熟身量，并表明基督和教会的关系（弗五 31-32），而不 是用婚姻、家庭来捆绑人。多配偶（利十八 18；申十七 17）、同性恋（利 十八 22；罗一 26-27）、离婚（太十九 5）和婚外恋都是神所不喜悦的。 【创二 25】「当时夫妻二人赤身露体，并不羞耻。」 在人堕落之前，里面是纯净的，所以「并不羞耻」。「羞耻」感是因 着犯罪而来的，里面不对了，外面就不对，人就产生了「羞耻」感。男女 在神所设立的婚姻之内「二人成为一体」（24 节），彼此同心、坦诚以待， 没有任何隐瞒掩藏，「并不羞耻」。 上图：主前 7 世纪的巴比伦创世史诗《埃努玛·埃利什 Enuma Elish》 的泥版残片，于 1848 年至 1876 年出土于尼尼微亚斯那巴图书馆（Library of Ashurbanipal）的遗址。整篇史诗大约有一千行，以阿卡德语分别写于七块 泥板上。巴比伦创世史诗可能是主前 15-14 世纪成形的，其中创造的先后次 序与创世记有一些共通之处，表明创造的历史存在于人类文明的记忆中。 但与创世记相比，两者的不同之处更多：创世记中独一真神的创造过程简 洁、庄严、圣洁、超越，万有的被造都是为了给人准备环境；而巴比伦史 诗中众神的创造过程复杂、离奇、恐怖，充满了淫乱、争吵、仇恨、自私、 暴力、杀戮和不孝，毫无道德观念，造人的目的只是为了代替众神从事繁 重的体力劳动，地位下贱。巴比伦创世史诗，只是堕落之后的人类按着自 己的形象来造神的结果，与创世记完全不能同日而语。",
      sourceEvidenceType: "figure_caption",
