      sourceTextSnippet: "创世记 31:47 64 家便在旁边吃喝。”拉班称那石堆为伊迦尔撒哈 在山上住宿。“拉班清早起来，与”他 杜他，雅各却称那石堆为迦累（都是“以石堆为 亲嘴，给他们祝福，回往自己的地方去了。 证”的意思）。48拉班说：““今日这石堆作你我中 间的证据。”因此这地方名叫迦累得，486又叫 雅各准备见以扫 米斯巴，意思说：“我们彼此离别以后，愿耶和 雅各仍旧行路，上帝的使者遇见他。 32：鐘备看见他们就说一这是 华在你我中间鉴察。50你若苦待我的女儿，又在 于是给那地方起名叫‘玛哈念（就是“二军兵”的意 我的女儿以外另娶妻，虽没有人知道，却有'上 帝在你我中间作见证。 思）。“雅各打发人先往”西珥地去，就是 ”拉班又说：“你看我在你我中间所立的这石 见他哥哥以扫，“吩咐他们说：“你们对我主 扫说：“你的仆人雅各这样说：我在拉班那里寄 堆和柱子。『29这石堆作证据，这柱子也作证据。 我必不过这石堆去害你，你也不可过这石堆和柱 直到如今。“我有牛、驴、羊群 子来害我。“但愿亚伯拉罕的上帝和拿鹤的上帝， 发人来报告我主，力要”在你眼前蒙恩。 6所打发的人回到雅各那里，说：“我 就是他们父亲的上帝，在你我中间判断。”雅各 就指着”他父亲以撒所敬畏的上帝起誓， 54又在 你哥哥以扫那里，他带着四百人，°正迎着你 山上献祭，请“众弟兄来吃饭。他们吃了饭，便来。”？雅各就”甚惧怕，而且愁烦，便把那 31:48C44 节 31:49€士11:29， 34 31:50/士11:10：撒上12:5； 耶 42:5；弥1:2；",
