      sourceTextSource: "pdftotext",
      sourceTextSnippet: "51 上图：无花果树的叶子，可宽达 20 厘米、长达 30 厘米。无花果树是 迦南地叶子最大的树，美索不达米亚没有无花果树，但伊甸园中有无花果 树。 【创三 8】「天起了凉风，耶和华神在园中行走，那人和他妻子听见神 的声音，就藏在园里的树木中，躲避耶和华神的面。」 • 「天起了凉风」可能不是指气温，而是指傍晚。 • 罪人不可能主动寻求神的赦免，在神面前总是「藏」和「躲避」， 不但在伊甸园如此，将来末日大灾难时也是如此（启六 16）。只有主耶稣 宝血的功效，才能使彼得三次不认主后，也能立刻痛哭悔改（路二十二 61-62），并且一听见「是主」，就立刻「束上一件外衣，跳在海里」，游 到岸上去见主（约二十一 7），而不是「躲避耶和华神的面」。 • 罪在人身上带出的第 3 个连锁反应，就是「藏在园里的树木中，躲 避耶和华神的面」。罪使人「良心」有亏（徒二十三 1；二十四 16），因 此在神面前感到「害怕」（10 节）；但罪又使人与神隔绝，宁愿靠自己遮 掩（7 节），也不愿向神认罪，所以只能自欺欺人地「藏」和「躲避」。 【创三 9】「耶和华神呼唤那人，对他说：『你在哪里？』」 • 人犯罪以后是「躲避耶和华神的面」（9 节），但神所做的却是主动 来寻找人，显明祂主动的救赎恩典，用「你在哪里」这个充满恩典、慈爱 的呼唤把人从隐藏的地方吸引出来，而不是用「雷轰、闪电和密云」（出 十九 16）把他们赶出来。「你在哪里」这个伟大的呼唤，一直响彻至今。",
