      sourceTextSource: "pdftotext",
      sourceTextSnippet: "55 上图：巴西发现的古代 Tetrapodophis 四足蛇化石。从解剖学上看，现代蛇以 前应该是长腿的，少数蟒蛇中依然可以找到髋骨和后腿的痕迹。有研究者认为， 蛇的很多骨头形成很晚，当胚胎发育完成时，有些骨头还未长好或根本没有形成， 因此现代蛇没有腿。 上图：蛇口腔顶部的犁鼻器（Jacobson’s Organ）。这是蛇除了鼻子以外的另 一个嗅觉器官，蛇以分叉舌头在空气中收集气味分子或少许土的样本，然后再送 回犁鼻器，用这种方法「嗅」出味道，看起来像是在吃土（创三）或舔土（弥七 17）",
