      sourceTextSource: "pdftotext",
      sourceTextSnippet: "58 就失去了享用神恩典的能力，凡事都是出于自己、依靠自己，为要满足自 己；但也失去了自由，被肉体的需要所捆绑，结果自然是「终身劳苦」。 • 男人终身的「劳苦」与女人怀胎的「苦楚」（16 节）原文是同一个 词，罪使男人和女人同样陷入「劳苦」和「苦楚」中。 • 巴比伦创世史诗《埃努玛·埃利什》认为，人类的被造是为了给神 明当奴隶，替神明做他们厌倦了的耕种工作，解除神明的「劳苦」。但圣 经启示我们，这「劳苦」的重担不是工作带来的，而是罪的结果，工作本 身并不是咒诅，「凡劳苦担重担的人」，若肯到主耶稣那里，必可在「劳 苦」中得着「安息」（太十一 28）。 【创三 18】「地必给你长出荆棘和蒺藜来；你也要吃田间的菜蔬。」 • 「荆棘和蒺藜」并非毫无用处，在神的创造里本来是好的（一 12）。 但「地必给你长出荆棘和蒺藜来」，表明「荆棘和蒺藜」已经不受控制， 人与自然失去了和谐，遭遇种种障碍、难处和失败（士二 3；赛三十四 13）； 也表明人以自己为神以后，靠着自己的善恶标准，已经不能胜任「治理这 地」的工作（一 28）。主耶稣在十字架上戴着「荆棘冠冕」（约十九 5）， 担当了我们的咒诅，将来我们在基督里将重新叫万物服在脚下（来二 8）。 • 本来人可以白白地吃「园中各样树上的果子」（二 15），工作是发 挥创造力的娱乐享受；现在却要「吃田间的菜蔬」，工作成了维持生计的 谋生手段。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：东非马赛人的村庄用荆棘做篱笆，非洲人也用荆棘围成羊圈、牛圈， 可以阻挡狮子等猛兽侵害。可见「荆棘和蒺藜」本来对人是有用的，只是人堕落 以后，「荆棘和蒺藜」的生长失控了，造成了人和自然的不和谐。",
