      sourceTextSource: "pdftotext",
      sourceTextSnippet: "创世记 37:5 72 『约瑟作了一梦，告诉他哥哥们，他们就越发 吗？你来，我要打发你往他们那里去。”约瑟 恨他。『约瑟对他们说：“请听我所作的梦：？我 说：“我在这里。”1以色列说：“你去看看你哥 们在田里捆禾稼，“我的捆起来站着，你们的捆 哥们平安不平安，群羊平安不平安，就回来报 来围着我的捆“下拜。”8他的哥哥们回答说：“难 信给我。”于是打发他出'希伯仑谷，他就往示 道你真要作我们的王吗？难道你真要管辖我们剑去了。15有人遇见他在田野走迷了路，就问他 吗？”他们就因为他的梦和他的话，越发恨他。 说：“你找什么？”16他说：“我找我的哥哥们， ”后来他又作了一梦，也告诉他的哥哥们说：“看 求你告诉我他们在何处放羊。”1那人说：“他 哪，我又作了一梦，梦见太阳、月亮与十一个 们已经走了，我听见他们说要往/多坍去。” 星向我下拜。”10约瑟将这梦告诉他父亲和他哥 瑟就去追赶他哥哥们，遇见他们在“多坍。18他 们远远地看见他，趁他还没有走到跟前， 哥们，他父亲就责备他说：“你作的这是什么梦！ 难道我和“你母亲、你弟兄果然要来俯伏在地， 就同谋要害死他。19彼此说：“你看！那作梦的 来了。20来吧！“我们将他杀了，丢在一个坑里， 向你“下拜吗？”\"「他哥哥们都嫉妒他，“他父亲 却把这话存在心里。 就说有恶兽把他吃了，我们且看他的梦将来怎 么样。”217流便听见了，要救他脱离他们的手， 约瑟被卖到埃及 说：“我们不可害他的性命。”22又说：“不可流 12约瑟的哥哥们往”示剑去，放他们父亲的羊。",
