      sourceTextSnippet: "63 可以得到更好的生活，结果却发现还是落入那个古老的陷阱。 上图：新亚述时代（Neo-Assyrian）的生命树浮雕。出土于伊拉克北部 尼姆鲁德（Nimrud，即宁录）阿淑尔纳西尔帕二世（Ashurnasirpal II，主前 883–859 年在位）的宫殿。 【创三 23】「耶和华神便打发他出伊甸园去，耕种他所自出之土。」 • 「自出之土」意思是「来源的土地」。人既与神断绝了属灵的关系， 拒绝与神相交（约壹一 3），只能回到属土的范围生活行动。 • 本来人的工作是修理看守伊甸园（二 15-16），但他们「如神能知道 善恶」（5 节），自己成为神之后的结果，没有给他们带来任何好处，反而 是失去了乐园，「耕种他所自出之土」：「他们的结局就是沉沦，他们的 神就是自己的肚腹，他们以自己的羞辱为荣耀，专以地上的事为念」（腓 三 19）。 【创三 24】「于是把他赶出去了；又在伊甸园的东边安设基路伯和四 面转动发火焰的剑，要把守生命树的道路。」 • 罪人若「永远活着」，是人无法承受的咒诅和刑罚。因此，逐出乐 园是神救赎大工的开始，也是「神爱世人」的表现（约三 16）。 •「基路伯」原文复数，是神贴身的天使（出二十五 18-21；二十六 31-33； 诗十八 10；九十九 1），象征神的荣耀（来九 5；结九 3）。「火焰」象征 神的圣洁，「剑」象征神的公义。「四面转动发火焰的剑」表明人无论从 那个方向来，都会被发现而拦阻，因此人无法靠自己自救，正如主耶稣所",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：新亚述时代（Neo-Assyrian）的生命树浮雕。出土于伊拉克北部 尼姆鲁德（Nimrud，即宁录）阿淑尔纳西尔帕二世（Ashurnasirpal II，主前 883–859 年在位）的宫殿。",
