      sourceTextSource: "pdftotext",
      sourceTextSnippet: "64 说：「我就是道路、真理、生命；若不借着我，没有人能到父那里去」（约 十四 6）。 • 「基路伯」的形象绣在挡住至圣所的幔子上（出三十六 35），当主 耶稣在十字架上断气时，「殿里的幔子从上到下裂为两半」（太二十七 51）， 「借着祂给我们开了一条又新又活的路，从幔子经过，这幔子就是祂的身 体」（来十 20），从此「基路伯」不再「把守生命树的道路」，我们「得 以坦然进入至圣所」（来十 19-22）。 上图：亚述强敌乌拉尔图（Urarṭu）人的生命树，来自阿尔吉什提一世（Argishti I，主前 786-764 年在位）时代的铜盔残片，出土于亚美尼亚首都附近的特什拜尼 （Teishebaini）。乌拉尔图位于黑海东南部和里海西南部的亚美尼亚高原。「生命 树」的记忆存在于各个古代文明之中，以不同的形式出现在古代苏美尔人、埃及 人、巴比伦人、亚述人、中国人、印度人和乌拉尔图人等许多古代文明的文献和 遗址里。这从侧面佐证人类的祖先都来自伊甸园。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：亚述强敌乌拉尔图（Urarṭu）人的生命树，来自阿尔吉什提一世（Argishti I，主前 786-764 年在位）时代的铜盔残片，出土于亚美尼亚首都附近的特什拜尼 （Teishebaini）。乌拉尔图位于黑海东南部和里海西南部的亚美尼亚高原。「生命 树」的记忆存在于各个古代文明之中，以不同的形式出现在古代苏美尔人、埃及 人、巴比伦人、亚述人、中国人、印度人和乌拉尔图人等许多古代文明的文献和 遗址里。这从侧面佐证人类的祖先都来自伊甸园。",
