      sourceTextSource: "pdftotext",
      sourceTextSnippet: "69 • 「七倍」象征「严重的报应」。 • 「记号」原文与大洪水之后彩虹之约「记号」（九 12-13）和割礼的 立约「证据」（十七 11）相同，神的保证几乎就像是立约，虽然神不再与 该隐同在，却并未丢弃他，显明「神爱世人」的恩典（约三 16），是神对 不肯悔改的世人所能做到的极限。 【创四 16】「于是该隐离开耶和华的面，去住在伊甸东边挪得之地。」 • 人第一次堕落，亚当只是离开伊甸园（三 23）；人第二次堕落，该 隐却要「离开耶和华的面」。该隐因献祭而嫉妒、杀人，最后离开了神； 凡随己意事奉神的人，不但不能讨神喜悦，反而会得罪神，更加远离神。 • 「挪得」字义是「漫游」，地点已无法考据。 【创四 17】「该隐与妻子同房，他妻子就怀孕，生了以诺。该隐建造 了一座城，就按着他儿子的名将那城叫作以诺。」 • 该隐在离开之前，可能已经结婚，他的「妻子」是他的近亲。大洪水 之前，还没有出现致病的基因突变，所以近亲结婚不会导致遗传疾病。大 洪水之后，可能地球失去了天篷对紫外线和宇宙射线的屏蔽作用，人类的 致病基因突变越来越多，近亲结婚会带来许多遗传疾病，摩西律法才禁止",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：主前 5400 年的埃利都（Eridu）遗址。埃利都是目前发现的美索 不达米亚最早的城市，也是世界上最早的城市，以泥砖和芦苇建房，覆盖 范围约为 8-10 公顷，大约有 4 千人口。埃利都原来位于波斯湾沿岸，数千 年时间的泥沙积累使现在的埃利都遗址已经离海岸线很远了。古代城市的 创建与国家、民族的建立有十分密切的关系。城市大都建在河流、水泉旁 边，作为附近贸易、文化、宗教活动的中心，后来成为城邦或政治中心。 兴建城市和定期维修泥砖城墙所需的组织能力，促进了统治城市的议会或 君主体制的形成。",
