      sourceTextSource: "pdftotext",
      sourceTextSnippet: "72 上图：主前 2600 年的「王后的里拉琴 Queen’s Lyre」，出于于亚伯拉 罕的老家吾珥，现藏于大英博物馆。主前 4000-3000 年，古代埃及和吾珥就 出现了箫、琴、瑟、笛等乐器。古代中东古墓和庙宇、王宫的壁画表明， 古代最常用的乐器是琴和瑟。 【创四 22】「洗拉又生了土八·该隐；他是打造各样铜铁利器的（或 译：是铜匠铁匠的祖师）。土八·该隐的妹子是拿玛。」 「土八·该隐」字义是「你将由该隐而生」，他是冶金行业的祖师。 「拿玛」字义是「可爱」。 上图：从主前 14 世纪埃及法老图坦卡蒙（Tutankhamun）墓中出土的 陨石铁短剑。历史学家认为，人类于主前 5000 年进入铜石混用的红铜时代 （Chalcolithic），主前 3200 年进入青铜时代（Bronze Age），主前 1400 年 进入铁器时代（Iron Age）。摩西写创世记的年代大约在主前 15 世纪，照理 说他应该不知道「铁」的存在，因此许多人认为这个「铁」显然是后人修 订的结果。但最近的考古发现，古埃及人从主前 4000 年就开始使用陨石铁 做首饰，证明圣经的准确性。 【创四 23】「拉麦对他两个妻子说：亚大、洗拉，听我的声音；拉麦 的妻子，细听我的话语；壮年人伤我，我把他杀了；少年人损我，我把他",
      sourceEvidenceType: "figure_caption",
