      sourceTextSnippet: "79 津大学阿什莫林博物馆艺术 与 考 古 博 物 馆 （ Ashmolean Museum of Art and Archaeology）。《苏美尔王 表》是一份古代文献，发现 于美索不达米亚各地，使用 苏美尔语书写，目前发现总 共有 16 份，内容基本相同。 上面所列的洪水之前的每个 王都统治了 2-4 万年，洪水 之后的每个王统治的时间从 1200 年逐渐降到几年。虽然 《苏美尔王表》中有许多夸 大的地方，但洪水之前和洪 水之后的年龄的相差比例， 与创世记的家谱接近。 【创五 28】「拉麦活到 一百八十二岁，生了一个儿 子，」 【创五 29】「给他起名叫挪亚，说：『这个儿子必为我们的操作和手 中的劳苦安慰我们；这操作劳苦是因为耶和华咒诅地。』」 • 「挪亚」字义是「休息」。 • 「挪亚」是这份家谱中的第十个人，如果这份家谱是连续的，挪亚 是塞特死后第 14 年生的，拉麦亲身经历了亚当的死、以诺的被提和塞特的 死，人的「劳苦」和神的「安慰」交替出现，因此预言「这个儿子必为我 们的操作和手中的劳苦安慰我们」，不但应验在洪水的审判和方舟上，更 是应验在基督身上。神将用洪水的审判向塞特一族显明祂的应许必将成就， 使等候祂的人得着「安慰」。 • 该隐族的拉麦口出狂言（四 23-24），塞特族的拉麦却预言了救恩和 盼望。神要让挪亚带出一个见证。就是在神的方法里，人就有了出路，可",
