      sourceTextSnippet: "80 以免去罪的刑罚。 【创五 30】「拉麦生挪亚之后，又活了五百九十五年，并且生儿养女。」 【创五 31】「拉麦共活了七百七十七岁就死了。」 • 该隐族的拉麦高喊「若杀该隐，遭报七倍；杀拉麦，必遭报七十七 倍」（四 24），而塞特族的拉麦则是安静地「活了七百七十七岁」；一个 是完全地报复，一个是完全地活。 • 虽然「七百七十七岁」是一个非常完全的数字，但拉麦还是「死了」， 「亚当的后代」（1 节）无论如何完全，至终逃不了一死。「就死了」这句 话在本章出现了 8 次，就像人类历史中的丧钟长鸣，宣告「死就作了王」 （罗五 14）。第五章的历史，一面证明「因一人的过犯，死就因这一人作 了王」（罗五 17），一面又指向「那些受洪恩又蒙所赐之义的，岂不更要 因耶稣基督一人在生命中作王吗」（罗五 17）的救恩计划： 1. 第一个「一人」亚当有神的「形象」（一 27），却没有拣选神的生 命，结果「与神所赐的生命隔绝了」（弗四 18），「亏缺了神的荣耀」（罗 三 23），把他的后裔都带到绝望里。 2. 第二个「一人」基督「是神本体的真像」（来一 3），祂自己就是「生 命」（约十四 6），也成为我们的「生命」（西三 4），神要用恩典「叫人",
