      sourceTextSource: "pdftotext",
      sourceTextSnippet: "85 上图：乔治亚州松树节，纪念当地悠久的海军防水漆、松香和树脂工业。有 人认为创六 14 的「松香」就是沥青，挪亚像后来的美索不达米亚人一样，必须用 沥青来密封方舟。但沥青来自于石油，大洪水之前不应该有石油，所以挪亚方舟 的记载是矛盾的。实际上，挪亚并不需要「沥青」，因为「松香」就是很好的防 水漆。20 世纪之前欧美国家用来建造和维修木制军舰的海军防水漆（Naval Stores） ， 就是从松树中提取出来的油性树脂制成的。美国乔治亚州有大量松树林，从 19 世 纪末到 20 世纪初，乔治亚州是全世界最大的海军防水漆产地。 【创六 15】「方舟的造法乃是这样：要长三百肘，宽五十肘，高三十 肘。」 「肘」是从胳膊肘到中指指尖的距离，约 45 厘米。根据现代造船专家 的分析，神所指示的方舟的尺寸和比例，使它几乎不可能被倾覆。方舟的 容积是 45,000 立方肘，而 45 正是「亚当 」的希伯来字母数值（Gematria Value），也就是「人 」的数值。奥古斯丁指出，300x50x30 正好是人体 的比例，并称之为「棺材的比例」。 • 方舟可以装 500 个 40 尺集装箱。如此庞然大物，很可能经过一百二 十年才建成（3 节），其间看不见丝毫洪水的迹象，又面临世人的讥讽诋毁，",
