      sourceTextSource: "pdftotext",
      sourceTextSnippet: "86 挪亚若没有不看环境、只顺服神的真信心，绝不可能完工。 上图：停泊的布里斯托港的大不列颠号。布鲁内尔（Isambard Kingdom Brunel） （1806-1859 年）是一位伟大的英国工程师，在 2002 年英国广播公司举办的「最 伟大的 100 名英国人」评选中名列第二。他于 1845 年主持建成的第一艘横跨大西 洋的蒸汽船大不列颠号（SS Great Britain），被誉为英国航海史上的一个奇迹，圆 了无数欧洲人的移民梦，仅用 14 天就能从英国到达纽约，6 周就能从英国到达澳 洲。大不列颠号的长、宽、高（98×15.5×10 米）比例与挪亚方舟（300x50x30 肘） 的比例几乎完全相同。无数的造船专家经过多次失败，才知道按照方舟的比例造 船最能抵御风浪。方舟并不是为高速行驶而设计的，神所指示的尺寸是保证稳定、 防止颠簸和滚动的最佳比例。 【创六 16】「方舟上边要留透光处，高一肘。方舟的门要开在旁边。 方舟要分上、中、下三层。」 「透光处」可能是在方舟侧面靠近顶部的一个窗口。这样，人在方舟 里就看不见四围汹涌的波涛，只能专一仰望天上的神。挪亚方舟没有舵和 帆，船和人的安危都在神的掌握之中。",
      sourceEvidenceType: "figure_caption",
