      sourceTextSource: "pdftotext",
      sourceTextSnippet: "87 上图：挪亚方舟艺术想象图。「方舟」原文和摩西在婴孩时所藏身的「箱子」 是同一个词（出二 5），其实就是个巨型的大木箱，里面有房间，侧面有一道门， 方舟的上方靠近船顶的位置可能有窗口，用来透光和让空气流通。方舟的排水量 与泰坦尼克号差不多，但长、宽、高的比例却比泰坦尼克号稳定得多。但早期教 父们普遍用「数字预表法」来理解方舟的尺寸，比如： 耶柔米（Jerome，主后 340-420 年）认为：方舟长 300 肘象征十字架，因为 罗马人用希腊字母「T」来代表十字架，「T」的希腊字母数值（Isopsephy）就是 300；宽 50 肘象征忏悔，因为七十士译本诗篇第五十篇（诗五十一）是大卫的悔 罪诗；高 30 肘象征基督的工作，因为基督开始传道时「约有三十岁」（路三 23）。 奥古斯丁（Augustine of Hippo，主后 354-430 年）认为：方舟象征基督和祂 的教会，方舟的木头象征十字架；300x50x30 是人体的比例，并称之为「棺材的比 例」。「方舟的门要开在旁边」，象征基督肋旁被扎的伤口（约十九 34）。 【创六 17】「看哪，我要使洪水泛滥在地上，毁灭天下；凡地上有血 肉、有气息的活物，无一不死。」 • 「洪水」象征神的审判（太二十四 39），是创造过程（一 6、9）的 逆转；也象征受洗的水（彼前三 20-21），信徒「借着洗礼归入死」（罗六 4），「使罪身灭绝，叫我们不再作罪的奴仆」（罗六 6），因此「我们若 是与基督同死，就信必与祂同活」（罗六 8）。 • 「凡地上有血肉、有气息的活物，无一不死」，表明水中的生物并",
