      sourceTextSnippet: "90 同一种传染病感染，一种致死病毒足以杀死所有猎豹；4、有弯弯的尾巴。 【创七 3】「空中的飞鸟也要带七公七母，可以留种，活在全地上；」 【创七 4】「因为再过七天，我要降雨在地上四十昼夜，把我所造的各 种活物都从地上除灭。』」 「再过七天」表明神再三给世人悔改的机会（六 3），但他们终究不肯 悔改。末日大灾难时神也是再三警告（启八 13；十四 6-7；十八 3），但世 人也是拒不悔改（启六 16；九 20）。 【创七 5】「挪亚就遵着耶和华所吩咐的行了。」 挪亚「遵着耶和华所吩咐的行了」，表明他的信心是真实的。信徒有 了神的话却不肯遵行，表明他的得救只是自欺欺人，因为「没有行为的信 心是死的」（雅二 20）。 【创七 6】「当洪水泛滥在地上的时候，挪亚整六百岁。」 拉麦在 5 年前就去世了（五 31），他的死好像伸出 5 个手指来进行倒 计时。而到玛土撒拉去世的那一年（五 27），洪水的审判就临到了。 【创七 7】「挪亚就同他的妻和儿子儿妇都进入方舟，躲避洪水。」 挪亚全家若不「进入方舟」，仍然不能「躲避洪水」。今天神也为世 人预备了基督作救恩的「方舟」，但人若不接受基督、「进入方舟」，就",
