      sourceTextSource: "pdftotext",
      sourceTextSnippet: "92 （出二十四 18；申九 18）；以利亚曾「走了四十昼夜」到西奈山（王上十 九 8）；主耶稣曾在旷野「禁食四十昼夜」（太四 2）。 【创七 13】「正当那日，挪亚和他三个儿子，闪、含、雅弗，并挪亚 的妻子和三个儿妇，都进入方舟。」 本节表明挪亚的家庭仍然是一夫一妻制。 【创七 14】「他们和百兽，各从其类，一切牲畜，各从其类，爬在地 上的昆虫，各从其类，一切禽鸟，各从其类，都进入方舟。」 挪亚全家和各样的动物「各从其类」，有次序地进入方舟，各居其所、 和平共处，显明一切都在神大能的掌控之下。 【创七 15】「凡有血肉、有气息的活物，都一对一对地到挪亚那里， 进入方舟。」 目前已发现的动物大约有 150 万种，大部分是昆虫和水生动物。水生 动物、两栖动物都可以在水中生存，昆虫也可以通过虫卵的形式生存下来， 只有 3000 多种爬行类，9000 多种鸟类和 4500 多种兽类需要进入方舟，总 共约 1 万 7 千多种。成年动物的平均体型只有兔子大小，方舟可以容纳 12 万个长 0.6 米 、宽 0.4 米、高 0.5 米的兔笼，并留出 1 米宽的通道，因此完 全装得下 1 万 7 千多种动物和它们所需的食物，以及挪亚全家。 上图：秀丽迷惑龙（Apatosaurus Excelsus，即雷龙 Brontosaurus）与大象的对 比。成年秀丽迷惑龙重达 28.1-34.5 吨，这样大型的恐龙是怎样带进方舟的呢？",
