      sourceTextSnippet: "93 上图：6 种不同大小恐龙的快速成长周期。古生物学家研究恐龙骨头里的生长 轮后发现，恐龙的成长过程中，有一个快速生长的青春期。比如：巨大的秀丽迷 惑龙（Apatosaurus Excelsus，即雷龙）的快速生长期大约从 5 岁开始，此时的迷惑 龙不到 1 吨重，但在快速生长期里，每年体重会增加 5 吨多，直到 12–13 岁时才 渐趋平缓，重达 25 吨左右。大型恐龙在进入快速生长期之前都很小，带进方舟完 全没有问题。它们出方舟后之所以能长得如此巨大，是因为爬行动物的身体可以 持续生长，直到死亡为止，而哺乳动物到达成年期就停止生长了。 【创七 16】「凡有血肉进入方舟的，都是有公有母，正如神所吩咐挪 亚的。耶和华就把他关在方舟里头。」 • 「耶和华就把他关在方舟里头」一面向挪亚表明神亲自的保守，另 一面向世人表明恩典的大门已关，世人悔改的机会过去了（太二十五 10-13）。 • 吩咐挪亚的是「神」，而把他关在方舟里的是「耶和华」，圣经用",
