      sourceTextSnippet: "96 【创八 2】「渊源和天上的窗户都闭塞了，天上的大雨也止住了。」 【创八 3】「水从地上渐退。过了一百五十天，水就渐消。」 这「一百五十天」是从下雨的时候开始算的（七 24）。 【创八 4】「七月十七日，方舟停在亚拉腊山上。」 • 「七月十七日」是阴历，与后来以色列的宗教历相差 6 个月。以色列 宗教历的正月十五日是逾越节（出十二 2、6），主耶稣于正月十五日逾越",
