      sourceEvidenceSnippet: "上图：希伯来历法（Hebrew Calendar），源于苏美尔尼普尔历法（Calendar of Nippur），亚伯拉罕的老家就是苏美尔文明的吾珥（创十一 31）。苏美 尔人使用阴历，一年分为 12 个月，每月以刚露出月牙的这天为初一，一年 有 6 个月每月 30 天，另 6 个月每月 29 天，全年 354 天，第二年或第三年 需要加一个闰月。在尼普尔历法中，每年夏至（现代公历 6 月 21 日前后） 之后的那个新月被称为大麦播种月（Še-numun），是一年的第 4 个月。 以色列人在亚笔月（即尼散月）出埃及（出十三 4），因此神吩咐以色 （出十二 2），被称为宗教历（Religious 列人以这个月「为正月，为一年之首」",
