      sourceTextSource: "pdftotext",
      sourceTextSnippet: "98 上图：地球板块构造。大洪水之后，地球的板块构造可能发生了极大的变化， 非洲板块、欧亚板块和印度洋板块互相挤压的地方隆起了亚拉腊山脉。 【创八 5】「水又渐消，到十月初一日，山顶都现出来了。」 「山顶都现出来了」表明得救的盼望有了确实的证据。「山顶」原文 是复数，表示众山。 【创八 6】「过了四十天，挪亚开了方舟的窗户，」 （五十 3）； 「四十天」代表彻底的察验：埃及人「薰尸的常例是四十天」 以色列十二探子曾窥探迦南地「四十天」（民十三 25）；主耶稣曾在旷野 「四十天受魔鬼的试探」（路四 2），复活后「四十天之久」向使徒显现， 讲说神国的事（徒一 3）。 【创八 7】 「放出一只乌鸦去；那乌鸦飞来飞去，直到地上的水都干了。」 挪亚放出不会自动归巢的「乌鸦」，是为了观察它所选择的飞行方向， 判断陆地的所在。乌鸦是不洁净的鸟类，食腐肉是乌鸦的习性，因此必然 能找到足够的食物，它也不介意在泥泞的地上或动物浮尸上栖身。 【创八 8】「他又放出一只鸽子去，要看看水从地上退了没有。」 【创八 9】「但遍地上都是水，鸽子找不着落脚之地，就回到方舟挪亚 那里，挪亚伸手把鸽子接进方舟来。」",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：地球板块构造。大洪水之后，地球的板块构造可能发生了极大的变化， 非洲板块、欧亚板块和印度洋板块互相挤压的地方隆起了亚拉腊山脉。",
