      sourceTextSource: "pdftotext",
      sourceTextSnippet: "100 • 在神的旨意中，动物是为人造的，人是动物的管理者（一 26）。因 此，人败坏，动物也跟着遭殃（六 7）；人得保存，动物也跟着得保存（六 18-19）；人蒙神记念，动物也跟着蒙记念（1 节）；现在人得救，动物也 跟着得祝福。「滋生」原文与神在创造时祝福的「滋生」相同（一 20）， 「兴旺」原文与神在创造时祝福的「滋生」相同（一 22）。 • 方舟只需要装载每个种类带有丰富基因多样性（Genetic Diversity）的 一对动物幼崽，就可以在洪水之后繁衍出许多不同的品种。这并不是进化， 而是动物在不同环境和遗传条件下基因多样性的表现。 上图：狗和狼是同一种动物，挪亚带进方舟的可能是狼的祖先。人驯化狼的 后代，经过育种，至今已经繁衍出 700 个品种的狗。神在创造时，为每个物种都 预备好了许多种基因，可供不同环境的选择，称为基因多样性（Genetic Diversity） 。 物种在不同的环境和遗传条件下，可以表现出不同的基因特性，繁衍出不同的品 种。狗的祖先有足够的基因多样性，经过人工育种，至今已经培育出 700 多个品 种的狗，虽然外表相差很大，但还是「各从其类」，始终属于犬科、犬属、狼种、 犬亚种。鸽子、小鼠的基因多样性也足够大，可以培养出许多品种。 【创八 18】「于是挪亚和他的妻子、儿子、儿妇都出来了。」 【创八 19】「一切走兽、昆虫、飞鸟，和地上所有的动物，各从其类， 也都出了方舟。」 【创八 20】「挪亚为耶和华筑了一座坛，拿各类洁净的牲畜、飞鸟献 在坛上为燔祭。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：狗和狼是同一种动物，挪亚带进方舟的可能是狼的祖先。人驯化狼的 后代，经过育种，至今已经繁衍出 700 个品种的狗。神在创造时，为每个物种都 预备好了许多种基因，可供不同环境的选择，称为基因多样性（Genetic Diversity） 。 物种在不同的环境和遗传条件下，可以表现出不同的基因特性，繁衍出不同的品 种。狗的祖先有足够的基因多样性，经过人工育种，至今已经培育出 700 多个品 种的狗，虽然外表相差很大，但还是「各从其类」，始终属于犬科、犬属、狼种、 犬亚种。鸽子、小鼠的基因多样性也足够大，可以培养出许多品种。",
