      sourceTextSnippet: "101 • 「各类洁净的牲畜、飞鸟」原文都是阳性单数，表示每样只献上一 只公的。「燔祭」是指将祭物放在坛上完全焚烧而献给神（利一 4）。本节 是圣经中第一次提到「筑坛」。 【创八 21】「耶和华闻那馨香之气，就心里说：『我不再因人的缘故 咒诅地（人从小时心里怀着恶念），也不再按着我才行的灭各种的活物了。」 • 「闻那馨香之气」是用拟人的方法表示神悦纳对祂的敬拜（弗五 2； 腓四 18）。「心里说」表明这是神亲自启示人。 • 「人从小时心里怀着恶念」这句之前有个连接词，可以翻译为「虽 然」，表示神虽然知道人的本性就是邪恶，但还是选择不再用洪水灭世。 因为神将召出祂的选民，使用一个民族来带出「女人的后裔」（三 15）， 成就祂救赎的计划。神不是应允不再「灭世」，而是应允「不用洪水灭世」。 【创八 22】「地还存留的时候，稼穑、寒暑、冬夏、昼夜就永不停息 了。』」 • 神恢复了自然的秩序，一直持续到新天新地（启二十一 1）。「稼」 原文是种子，指播种；「穑」原文是「庄稼、收割」；「寒暑」原文是「冷 热」。「地」将有一天不再存留，那时会被「新地」所取代（彼后三 10、 13)。 • 本节原文的形式是诗歌。 上图：主 前 7 世纪苏 美尔《吉尔伽 美 什 史 诗 Epic of Gilgamesh 》 的泥板残片， 于 1848 年至 1876 年 出 土 于尼尼微亚 斯那巴图书馆（Library of Ashurbanipal）的遗址。整篇史诗大约有三千多行， 以楔形文字刻在泥版上。苏美尔史诗可能是主前 21 世纪成形的，史诗的第",
