      sourceTextSource: "pdftotext",
      sourceTextSnippet: "103 【创九 3】 「凡活着的动物都可以作你们的食物，这一切我都赐给你们， 如同菜蔬一样。」 虽然人在洪水之前就可能已经开始吃肉（四 4），但此时是神正式允许 人以动物为食物，「如同菜蔬一样」（一 29）。实际上，古人很少吃肉， 豢养牲畜的目的主要是为了获得奶和毛，通常只有在动物死亡或献祭后， 才有肉食可吃。 【创九 4】「惟独肉带着血，那就是它的生命，你们不可吃。」 人可以吃动物的肉，因为肉都是神「用土所造成的」（二 19）。但动 物的血却代表「生命」，不吃血表示尊重生命、敬畏赐生命的神。「血」 代表「生命」，预表基督的宝血为我们赎罪：「活物的生命在血中。我把 这血赐给你们，可以在坛上为你们的生命赎罪。因血里有生命，所以能赎 罪」（利十七 11）。 上图：描绘犹太人屠宰的中世纪绘画。犹太人的肉食必须把血放干净。 【创九 5】「流你们血、害你们命的，无论是兽是人，我必讨他的罪， 就是向各人的弟兄也是如此。」 • 本节原文的开头是「当然」，强调这个命令是很严肃的。神重视祂 所赐的人的「生命」，敬畏神的人不但不可杀人，连恨人也不可以（太五",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：描绘犹太人屠宰的中世纪绘画。犹太人的肉食必须把血放干净。",
