      sourceTextSnippet: "106 再不泛滥、毁坏一切有血肉的物了。」 【创九 16】「虹必现在云彩中，我看见，就要记念我与地上各样有血 肉的活物所立的永约。』」 当「云彩盖地时候」（14 节），地上的人只看见阴天，看不见彩虹， 只有神在天上能看见。这表明挪亚之约完全是恩典，是神为了成就自己的 救赎计划，愿意自己限制自己，不「记念」人的罪愆，而是「记念」祂用 恩典单方面与「地上一切有血肉之物」（17 节）所立的「永约」。 【创九 17】「神对挪亚说：『这就是我与地上一切有血肉之物立约的 记号了。』」 【创九 18】「出方舟挪亚的儿子，就是闪、含、雅弗。含是迦南的父 亲。」 【创九 19】「这是挪亚的三个儿子，他们的后裔分散在全地。」 【创九 20】「挪亚作起农夫来，栽了一个葡萄园。」 「葡萄园」的目的是酿酒（歌八 11；太二十 1），适度的饮酒是神所 允许的享受（约二 2）。葡萄酒的历史与农业有非常紧密的连结，在美索不 达米亚、以色列、腓尼基、埃及、希腊、罗马等古文明中，葡萄和葡萄汁 所发酵的饮品占据了生活中很重要的一部分。洪水以前，人类可能已经会 酿酒（太二十四 38）。 上图：发现新石器时代、红铜时代和青铜时代早期酿酒和橄榄种植遗迹的考 古地点。葡萄酒的历史与农业有非常紧密的连结，在美索不达米亚、以色列、腓",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：发现新石器时代、红铜时代和青铜时代早期酿酒和橄榄种植遗迹的考 古地点。葡萄酒的历史与农业有非常紧密的连结，在美索不达米亚、以色列、腓",
      sourceEvidencePage: 114,
      sourceEvidenceOrigin: "same-page",
