      sourceTextSource: "pdftotext",
      sourceTextSnippet: "107 尼基、埃及、希腊、罗马等古 文明中，葡萄和葡萄汁所发酵 的饮品占据了生活中很重要 的一部分。 【创九 21】「他喝了园 中的酒便醉了，在帐棚里赤 着身子。」 挪 亚 的 醉 酒 并不 表 明 他酗酒了，可能因为他第一 次喝酒，缺乏经验才醉倒， 因此圣经对他并无批评。 「在帐棚里赤着身子」表明 挪亚并不是当众出丑，因为 帐棚是他私人的地方。 上图：2017 年于格鲁吉亚 Khramis Didi-Gora 出土的主前 6000 年的陶罐，是目前发现的最早的制作葡萄酒的 证据。陶罐中发现了葡萄酒的残渣。 【创 9:22】 「迦南的父亲含看见他父亲赤身,就到外边告诉他两个弟兄。」 含出于未知原因进入父亲的帐棚，看见父亲在自己的帐棚里「赤身」， 本来不应该声张，而应该照顾父亲。但他却「到外边告诉他两个弟兄」， 使父亲蒙羞，表明他的态度有问题。洪水并没有除去挪亚一家生命中的罪 性，他们的生命仍旧是亚当的生命，自然就会活出不讨神喜悦的事物。 【创九 23】「于是闪和雅弗拿件衣服搭在肩上，倒退着进去，给他父 亲盖上，他们背着脸就看不见父亲的赤身。」 遮掩、担待别人的过错，不使对方蒙羞（加六 1），表明闪和雅弗是真 正爱父亲、孝敬父亲的。「衣服」指「外套、长袍」，可以遮掩，也可以 保暖。 【创九 24】「挪亚醒了酒，知道小儿子向他所作的事，」 「儿子」原文可以指儿子、孙子或后裔。因此，这个词可能指「小儿 子」含，也可能指「小孙子」迦南（25 节）。",
