      sourceTextSource: "pdftotext",
      sourceTextSnippet: "110 【创十 3】「歌篾的儿子是亚 实基拿、利法、陀迦玛。」 • 「亚实基拿」可能是土耳其 利基尼亚人（Rheginians）的始祖 （《犹太古史记》卷 1 第 6 章 126 节）。 • 「利法」可能住在黑海南岸。 • 「陀迦玛」是弗吕家人的始 祖（徒十六 6；《犹太古史记》卷 1 第 6 章 127 节）。 【创十 4】「雅完的儿子是以 利沙、他施、基提、多单。」 • 「以利沙」可能是希腊伊奥 利亚人（Aeolians）的始祖。 • 「他施」可能是西班牙人的 始祖。 • 「基提」是塞浦路斯人的始 祖。「基提」是复数，表示民族。 • 「多单」可能是罗德岛人的 始祖。「多单」是复数，表示民族。 【创十 5】「这些人的后裔将 各国的地土、海岛分开居住，各随 各的方言、宗族立国。」 • 雅弗的后裔一共有 14 个宗 族。 • 「海岛」原文是「海岸」， 是希伯来文形容远方的一个名词， 希伯来人称海那边的土地为岛，特 指西方的遥远之处。在以赛亚书四 十章之后尤其常用（赛四十 5）。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：雅弗的后裔大致分布位置。雅弗的后裔从亚拉腊山向北迁移，定居在 西至西班牙、东至伊朗的地区，包括黑海、里海、高加索一带地方。",
      sourceEvidencePage: 119,
      sourceEvidenceOrigin: "next-page",
      captionRiskFlags: ["caption-boundary-truncated","caption-from-next-page"],
