      sourceTextSource: "pdftotext",
      sourceTextSnippet: "113 上图：宁录所建之城的位置。 【创十 11】「他从那地出来往亚述去，建造尼尼微、利河伯、迦拉，」 【创十 12】「和尼尼微、迦拉中间的利鲜，这就是那大城。」 • 「他从那地出来往亚述去」（11 节）意思是把势力扩张到北方的亚 述地。「大城」可能指四座城合并起来的大区域，后来的「尼尼微大城」 （拿一 2）可能就是由尼尼微、利河伯、迦拉、利鲜这四座城联合而成的。 • 「亚述」位于两河流域中游的平原地带，原来是闪的后裔亚述居住 的地方（22 节），被宁录所侵占。 • 「尼尼微」字义是「Ninus 女神的住处」，位于巴比伦北方 400 公里、 底格里斯河东岸，离河口 880 公里，后来成为亚述帝国的首都（拿三 33）。 许多学者认为，宁录是人类偶像崇拜的始作俑者，他死后很可能被人神化 为苏美尔的尼尔努塔神（Ninurta），最终演化为巴比伦的马尔杜克神 （Marduk）。马尔杜克神被认为是中东、埃及、希腊、罗马所有偶像崇拜 的根源，流传到各地后，演化出不同的名字和剧情，比如巴力（Baal）、俄 西里斯（Osiris）、阿波罗（Apollo）等等。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：宁录所建之城的位置。",
