      sourceTextSource: "pdftotext",
      sourceTextSnippet: "114 • 「利河伯」位于尼尼微城附近，即今日伊拉克的摩苏尔（Mosul）。 • 「迦拉」位于尼尼微城南方，底格里斯河与 Zab 河汇流处，即今日 伊拉克的宁录，曾被亚述纳西拔二世（Ashurnasirpal II，主前 883-859 年） 作为亚述帝国首都。 • 「利鲜」位于尼尼微和迦拉的中间，底格里斯河东岸。 上图：亚述纳西拔二世（Ashurnasirpal II，主前 883-859 年）王宫入口 的半人半兽怪物拉玛苏（Lamassu），位于当时的亚述首都宁录（Nimrud）， 即宁录所建的「迦拉」（创十 12），2015 年被 ISIS 恐怖组织炸毁。 【创十 13】「麦西生路低人、亚拿米人、利哈比人、拿弗土希人、」 【创十 14】「帕斯鲁细人、迦斯路希人、迦斐托人；从迦斐托出来的 有非利士人。」 • 源于麦西的 7 族（13-14 节）大都住在北非的埃及和利比亚。 • 「迦斐托人」可能后来移居到地中海的克里特岛。「非利士人」字 义是「移民」，他们是「迦斐托人」，后来移居到地中海东岸靠近西乃半 岛的平原，后来与以色列人争夺迦南地。神领以色列人出埃及之前，先领 非利士人从迦斐托来到迦南地 （摩九 7），用以试炼以色列人。希腊人称 「非利士 Philistim」为「巴勒斯坦 Palestine」。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：亚述纳西拔二世（Ashurnasirpal II，主前 883-859 年）王宫入口 的半人半兽怪物拉玛苏（Lamassu），位于当时的亚述首都宁录（Nimrud）， 即宁录所建的「迦拉」（创十 12），2015 年被 ISIS 恐怖组织炸毁。",
