      sourceTextSnippet: "116 上图：迦南诸族的大致分布。迦南地的境界西北至腓尼基海岸的西顿， 南至埃及边境（基拉耳、迦萨）；西至地中海，东至约旦河谷（所多玛、 蛾摩拉、押玛、洗扁、拉沙）。 【创十 20】「这就是含的后裔，各随他们的宗族、方言，所住的地土、 邦国。」 含的后裔一共有 30 个宗族。 上图：含的后裔大致分布位置。含的后裔从亚拉腊山向南迁移，定居在美索 不达米亚、阿拉伯和埃及南部、地中海东岸，并沿着北非的地中海岸向西扩散。 【创十 21】「雅弗的哥哥闪，是希伯子孙之祖，他也生了儿子。」 • 闪的后裔从亚拉腊山向东南迁移，定居在美索不达米亚及周边地区 和阿拉伯半岛。 「希伯」字义是「远方的地区、那一边的地方」，是希伯来人的直系 祖先，「希伯来人 」（十四 13）的民族名字源于「希伯 」。 • 「雅弗的哥哥闪」原文是「闪是大的雅弗的兄弟」，「大的」如果 修饰「雅弗」，雅弗就是哥哥；如果修饰「兄弟」，闪就是哥哥。挪亚三 个儿子的大小顺序很可能是雅弗、闪、含，因为挪亚 500 岁时做了父亲（五 32），而闪是挪亚 502 岁时生的（十一 10），含则是小儿子（九 24）。希 腊文七十士译本、英文 KJV 和 NIV 版都把雅弗作为哥哥。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：迦南诸族的大致分布。迦南地的境界西北至腓尼基海岸的西顿， 南至埃及边境（基拉耳、迦萨）；西至地中海，东至约旦河谷（所多玛、 蛾摩拉、押玛、洗扁、拉沙）。",
