      sourceTextSource: "pdftotext",
      sourceTextSnippet: "121 【创十一 3】「他们彼此商量说：『来吧！我们要做砖，把砖烧透了。』 他们就拿砖当石头，又拿石漆当灰泥。」 • 神的工作是改变人的生命，「就像活石，被建造成为灵宫」（彼前 二 5），成为「圣城新耶路撒冷」（启二十一 2），使人和神能亲密相交； 但人却「彼此商量」，定意要用自己的工作代替神的工作，「拿砖当石头」， 建造高举人的「一座城和一座塔」（4 节）。整个人类的历史，都是这两种 「建造」的争战，撒但则在背后推波助澜。 • 巴比伦平原缺少石头，必须用以窑烧的砖头取代石块。巴比伦一带 窑烧砖头的技术大约出现在主前 4000 年，以沥青作为胶合料，不但防水， 更坚硬如石头，但由于制造过程昂贵，只有重要的公共建筑物才会使用。 经过几千年的风吹雨打，如今这些「砖」所造的建筑早已成为土堆。「石 漆」就是沥青。 上图：这些镶嵌珍 珠的陶瓷碎片附在沥 青上。这是巴别塔时代 人类使用沥青技术的 证据。出土于美索不达 米亚，现藏于卢浮宫。 【创十一 4】「他们说：『来吧！我们要建造一座城和一座塔，塔顶通 天，为要传扬我们的名，免得我们分散在全地上。』」 • 犹太史学家约瑟夫和早期教父都指出，是宁录教唆人们建造「一座 城和一座塔」（《犹太古史记》卷 1 第 4 章 113 节）。当年人们在示拿地 「彼此商量」（3 节）的，正是历世历代人们不断提出的宏伟计划和远大理 想，结果都是事与愿违、归于无有。人里面亚当的生命若不改变，罪人的 本性就不会改变，高举人所带来的结局也不会改变。 • 「来吧，我们要」表明世人决定根据自己、依靠自己，而不是根据 神、依靠神。",
