      sourceTextSource: "pdftotext",
      sourceTextSnippet: "125 【创十一 6】「耶和华说：『看哪，他们成为一样的人民，都是一样的 言语，如今既做起这事来，以后他们所要做的事就没有不成就的了。」 • 「成为一样的人民」原文是「同属一个民族」。人若里面没有基督 的生命，都凭着各自的标准「如神能知道善恶」（三 5），又「成为一样的 人民，都是一样的言语」，必然会先联合起来反对神，然后人与人之间互 相斗争。历史不断地告诉我们，每一次人本主义者、无神论者团结起来搞 什么革命，都不会在成功之后继续团结一致、彼此相爱，而会从「高举人」 变成「高举我」，每个人都成为唯我独尊的假神，以致互相斗争、践踏、 杀戮。 • 「如今既做起这事来」原文是「这是他们所开始做的事」，「没有不 成就的了」原文是「不能被拦阻」。一旦人开始以自我为中心，决定建造 巴别塔、抵挡神的旨意，就没有任何人能拦阻人类变本加厉地走向败坏， 最终奔向灭亡。只要看看现代人滥用科技、制造大规模杀伤性武器，就可 以理解神为什么 必须进行干预，预 防人类在「女人的 后裔」（三 15） 出现之前集体灭 亡。 • 神 的 旨意 是要「使天上地上 一切所有的，都在 基督里面同归于 一」（弗一 10）， 在基督之外的合 一，结果都是建造 巴别塔。 上图：1992 年 欧洲议会大厦开工 时的海报，右下方",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：1992 年 欧洲议会大厦开工 时的海报，右下方",
