      sourceTextSnippet: "127 伊甸园到巴别塔时期使用的共同语言（创十一 1）。洪水之前人类的长寿， 有助于希伯来语稳定地传递到巴别时代。而旧约也揭示了希伯来语非常特 别的特征：虽然旧约的写作时间长达一千多年，但这一千多年来的希伯来 语法与词汇竟然相差无几！这是世界上任何一种语言都无法做到的，比较 一下摩西五经同时期的殷商甲骨文和玛拉基书同时期的《春秋》之间的巨 大差别，我们就能体会到这一点。 4. 在巴别塔之前，世上只有一种言语，所有人类可以互相通婚，因此 任何的基因差异都会减到最小，深肤色的人可以与浅肤色的人结婚，使人 口的普遍肤色维持不变。随着言语的变乱，原本的大群体分散成许多小群 体，不是每个小群体都包括所有肤色的人，有的小群体的普遍肤色会偏向 较深的一端，有的小群体的普遍肤色会偏向较浅的一端，头发、眼型等其 他身体特征也会因生活环境的不同而有差异，这就是种族的起源。种族的 起源是根据人类本身已存在的基因的遗传组合，如果现代各种族之间的人 自由通婚，若干代以后就会恢复挪亚家族的肤色和身体特征。 上图：世界主要语系（Language Family）的分布。根据 Ethnologue 2015 年的 资料，目前全世界已知 7472 种语言。语言学家们根据这些语言之间的关系，把它 们分为数百种语系，但他们至今无法在语系的划分上取得统一意见，更无法合理 解释这些语系的「祖语 Proto-language」来源于何处，只有圣经能提供答案。 【创十一 8】「于是，耶和华使他们从那里分散在全地上；他们就停工， 不造那城了。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：世界主要语系（Language Family）的分布。根据 Ethnologue 2015 年的 资料，目前全世界已知 7472 种语言。语言学家们根据这些语言之间的关系，把它 们分为数百种语系，但他们至今无法在语系的划分上取得统一意见，更无法合理 解释这些语系的「祖语 Proto-language」来源于何处，只有圣经能提供答案。",
      sourceEvidencePage: 135,
      sourceEvidenceOrigin: "same-page",
