      sourceTextSource: "pdftotext",
      sourceTextSnippet: "128 期教父认为，这些人语言变乱后彼此争吵，爆发了战争。要恢复人与人之 间的关系，不是依靠语言或国家的统一，而是要先恢复人与神之间的关系。 【创十一 9】「因为耶和华在那里变乱天下人的言语，使众人分散在全 地上，所以那城名叫巴别（就是变乱的意思）。」 • 如果 10-16 节的家谱是连续的，此时可能正是「法勒」（16 节）出 生的时候，洪水之后才过了 101 年，挪亚、闪都还活着。考古发现，在主 前 4000 年左右的乌鲁克时期（Uruk period），美索不达米亚南部居民固有 的都市化、塔庙、窑砖等文化和技术突然在中东各个定居地点出现，表明 此时正是「耶和华使他们从那里分散在全地上」的时候。 • 巴比伦城原址现在只能挖掘到主前 2000 年左右的遗迹，因为幼发拉 底河水位的变迁已经破坏了更低层的遗迹。 上图：主前 610 年新巴比伦帝国的巴比伦塔庙（Ziggurat）示意图。每个美索 不达米亚早期城市都有一个塔庙，作为城市守护神从天而降的阶梯。塔庙于主前 4000 年由苏美尔人的高台演化而来，苏美尔人、巴比伦人、埃兰人、阿卡德人和 亚述人都曾建造塔庙，高度从两层到七层不等。塔庙的造法基本相同，内部用晒 制砖填充，每隔一定高度就铺上一层芦苇席，外壳以沥青作胶泥，用烤制砖砌成， 国王的名字有时会刻在这些砖头上。希腊史学家希罗多德（主前 484-425 年）所描",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：主前 610 年新巴比伦帝国的巴比伦塔庙（Ziggurat）示意图。每个美索 不达米亚早期城市都有一个塔庙，作为城市守护神从天而降的阶梯。塔庙于主前 4000 年由苏美尔人的高台演化而来，苏美尔人、巴比伦人、埃兰人、阿卡德人和 亚述人都曾建造塔庙，高度从两层到七层不等。塔庙的造法基本相同，内部用晒 制砖填充，每隔一定高度就铺上一层芦苇席，外壳以沥青作胶泥，用烤制砖砌成， 国王的名字有时会刻在这些砖头上。希腊史学家希罗多德（主前 484-425 年）所描",
