      sourceTextSource: "pdftotext",
      sourceTextSnippet: "131 上图：吾珥第三王朝时期的吾珥城示意图。吾珥最早的建筑始于主前 5500 年 左右的欧贝德文化（Ubaid Period），主前 27 世纪吾珥重新繁荣，成为苏美尔人敬 拜月神的圣地。主前 2112 年，乌鲁克（Uruk ）人乌尔纳姆（Ur-Namma，主前 2112 年-2095 年在位）占领吾珥，建立了吾珥第三王朝（Ur III dynasty，主前 2112-2004 年），统一整个美索不达米亚，建立起了强大的中央集权制王朝，被称为复兴的 苏美尔帝国（Neo-Sumerian Empire）。 【创十一 29】「亚伯兰、拿鹤各娶了妻：亚伯兰的妻子名叫撒莱；拿 鹤的妻子名叫密迦，是哈兰的女儿，哈兰是密迦和亦迦的父亲。」 • 「亚伯兰」的字义是「尊贵的父」，但实际上他却没有孩子。 • 「撒莱 Sarai」的字义是「公主」，可能源于苏美尔月神的配偶月亮 女神的头衔「撒拉杜 Sarratu」。「密迦 Milcah」的字义是「皇后」，可能 源于苏美尔天后伊丝塔（Ishtar）的头衔「密迦杜 Malkatu」。这些名字表 明，他拉「住在大河那边事奉别神」（书二十四 2），敬拜苏美尔人的月神 和天后。 • 撒莱是亚伯兰同父异母的妹妹（二十 12），密迦是拿鹤的侄女，近 亲结婚是当时的习俗（二十四 4；二十八 2）。",
