      sourceEvidenceSnippet: "上图：吾珥第三王朝时期的吾珥城示意图。吾珥最早的建筑始于主前 5500 年 左右的欧贝德文化（Ubaid Period），主前 27 世纪吾珥重新繁荣，成为苏美尔人敬 拜月神的圣地。主前 2112 年，乌鲁克（Uruk ）人乌尔纳姆（Ur-Namma，主前 2112 年-2095 年在位）占领吾珥，建立了吾珥第三王朝（Ur III dynasty，主前 2112-2004 年），统一整个美索不达米亚，建立起了强大的中央集权制王朝，被称为复兴的 苏美尔帝国（Neo-Sumerian Empire）。",
