      sourceTextSource: "pdftotext",
      sourceTextSnippet: "134 • 主前 2006 年，吾珥被以拦人毁灭，如果亚伯兰没有顺从神的呼召离 开，结局必然是与吾珥一起灭亡。 上图：「吾珥军旗 The Standard of Ur」两侧的图案。吾珥出土的「吾珥军旗」 是一个木盒，盒子两侧镶嵌了极为精致的马赛克，一侧是战争和胜利的场面，另 一侧是和平和宴会的场面，可以看出在亚伯拉罕出生前 400 多年，吾珥已经具有 相当高的物质文明和艺术水平。但神却要他抛下这一切，前往当时的蛮荒之地迦 南。原件制作于主前 2600 年，现存于大英博物馆。 下图：吾珥城遗址，废墟遗址上最显眼的是供奉月神的塔神，还有许多住房 的遗迹。主前 2006 年，以拦人攻入吾珥，吾珥第三王朝灭亡。今天，大部分从吾 珥挖掘出来的文物都保存在大英博物馆和宾夕法尼亚大学的考古与人类学博物 馆。",
