      sourceTextSnippet: "135 【创十一 32】「他拉共活了二百零五岁，就死在哈兰。」 • 「就死在哈兰」这句话与 10-26 节一贯的「又活了」截然相反，表明 这是旧时代的结束、新时代的开始。 • 此时大约是主前 2092 年，亚伯兰 75 岁（十二 4），从此亚伯兰全心 全意地顺从神的呼召离开哈兰（徒七 4），神选民的历史正式开始了。 下图：亚伯拉罕从吾珥到迦南的路线，全程约 1900 公里。他们可能是沿着幼 发拉底河西岸的商业大道前往迦南，沿途经过巴比伦、利马、哈兰和大马士革等 城市，从吾珥到哈兰大约 1100 公里，从哈兰到迦南地大约 800 公里。亚伯拉罕信 靠神，凭信心走完了这段漫长的路程，所以圣经说：「亚伯兰信耶和华，耶和华 就以此为他的义」（创十五 6）。",
