      sourceEvidenceSnippet: "下图：亚伯拉罕从吾珥到迦南的路线，全程约 1900 公里。他们可能是沿着幼 发拉底河西岸的商业大道前往迦南，沿途经过巴比伦、利马、哈兰和大马士革等 城市，从吾珥到哈兰大约 1100 公里，从哈兰到迦南地大约 800 公里。亚伯拉罕信 靠神，凭信心走完了这段漫长的路程，所以圣经说：「亚伯兰信耶和华，耶和华 就以此为他的义」（创十五 6）。",
