      sourceTextSnippet: "136 第 12 章 【创十二 1】「耶和华对亚伯兰说：『你要离开本地、本族、父家，往 我所要指示你的地去。」 神第一次在吾珥呼召亚伯兰，要他「离开本地和亲族」（徒七 2-4）。 现在神第二次在哈兰呼召亚伯兰，不但要「离开本地、本族」，还要离开 「父家」。亚伯兰所放弃的「本地、本族、父家」，神将用「土地、后裔、 祝福」来代替。圣经并没有责备亚伯兰在哈兰停留，因为他并非因为信心 的软弱，而是在那里等候神的指示。《犹太古史记》记载，亚伯兰在哈兰 公开宣称只有一位真神，当地拜偶像的人起来反对他，他就知道是应该离 开那地的时候了（卷 1 第 7 章 155-157 节）。「 亚伯拉罕因着信，蒙召的 时候，就遵命出去，往将来要得为业的地方去；出去的时候，还不知往哪 里去」（来十一 8），因为神两次呼召都只说「往我所要指示你的地去」， 并没有具体说明什么地方，需要亚伯兰凭信心一步一步地跟上神的呼召，",
