      sourceTextSource: "pdftotext",
      sourceTextSnippet: "137 不根据眼见，而单单根据神的话。亚当在伊甸园是怎样失落的，神就要怎 样恢复回来。从第十二到五十章，神借着亚伯拉罕、以撒和雅各的一生， 让我们看见神将在人身上怎样进行恢复的工作，看见神救赎的旨意是怎样 成就在人身上的： 1. 亚当拣选了分别善恶树，神就安排环境让亚伯拉罕操练因信拣选神。 2. 亚当失去了享用神在伊甸园的一切安排，神就用以撒的经历来显明 享用神。 3. 亚当活在自己的肉体里，神就安排环境来对付雅各，使他能脱离自 己、与神联合，最终让神的心意能从他里面完全地流露出来。 上图：主前 24-22 世纪的埃勃拉泥版（Ebla tablets），包括 1800 块完整的粘 土版，1974 年出土于叙利亚的 Ebla。埃勃拉泥版提到有一位至高神从无到有创造 了天、太阳、月亮、星星及地球，证明主前 24 世纪就已经存在一神信仰，并非是 从多神演化到一神。埃勃拉泥版所记录的法律，也证明《申命记》中记录的律例 并非后来才有的发明。 【创十二 2】「我必叫你成为大国。我必赐福给你，叫你的名为大；你 也要叫别人得福。」 神的呼召是要把人带进祂荣耀、光明的国度里，神所应许「必叫你成 为大国」，就是神「祭司的国度」（出十九 6）。「亚伯兰」的字义是「尊 贵的父」，后来神把他的名字改为「亚伯拉罕」（十七 5），意思是「多国 的父」，又赐给祂「先知」（二十 7）、「尊大的王子」（二十三 6）、「神",
