      sourceTextSource: "pdftotext",
      sourceTextSnippet: "140 上图：示剑在迦南地的位置。亚伯兰可能是从约旦河东进入迦南地，第一站 到了「示剑」。「示剑」位于迦南地中央、以巴路和基利心山之间，是迦南地南 北道路和东西道路的十字路口。 【创十二 7】 「耶和华向亚伯兰显现，说： 『我要把这地赐给你的后裔。』 亚伯兰就在那里为向他显现的耶和华筑了一座坛。」 神「要把这地赐给你的后裔」，表明年迈无子的亚伯兰必得着「后裔」， 也表明亚伯兰的「后裔」才能实际得着这地为业，他自己必须凭着信心「在 所应许之地作客，好像在异地居住帐棚」（来十一 9）。「这地」和「后裔」 的应许，不但贯串了摩西五经，也贯串了整本圣经。亚伯兰眼见的是「迦 南人住在那地」（6 节），但在信心里看见的是神的「显现」和应许，他的 拣选是凭信心，而不是凭眼见。因此，世人建造巴别塔，为了「传扬我们 的名」（十一 4），是活在属地的满足里；而亚伯兰「筑了一座坛」，为了 「求告耶和华的名」（8 节），是活在属天的旨意里。世人「建造一座城」 （十一 4），是为了过定居、安逸的生活；而亚伯兰则「支搭帐棚」（8 节）， 不在地上生根，是为了「等候那座有根基的城，就是神所经营、所建造的」 （来十一 10）。虽然他「并没有得着所应许的，却从远处望见，且欢喜迎 接，又承认自己在世上是客旅，是寄居的」（来十一 13）。",
      sourceEvidenceType: "figure_caption",
