      sourceTextSource: "pdftotext",
      sourceTextSnippet: "141 上图：应许之地位于「世界的十字路口」。「迦南地」位于各大文明古国的 中间，周围陆续崛起的帝国包括东方的亚述、巴比伦、波斯，南方的埃及，北方 的亚兰、赫人，西方的希腊、罗马。「迦南地」既是世界各国文化、商业、交通 的枢纽，也是各大帝国争霸的必经之地。神把这样一个「世界的十字路口」赐给 亚伯兰作应许之地，实在是有非常特别的意义。亚伯拉罕的后裔需要在此向全世 界作祭司国度的见证，也需要在此完全仰望神的保守和供应，否则完全不可能在 列强的夹缝中得以保存至今。 【创十二 8】「从那里他又迁到伯特利东边的山，支搭帐棚；西边是伯 特利，东边是艾。他在那里又为耶和华筑了一座坛，求告耶和华的名。」 「帐棚」和「坛」表明了信徒在地上的身分和生活：「帐棚」代表我 们在地上「是客旅，是寄居的」（彼前二 11）；「坛」代表我们「是被拣 选的族类，是有君尊的祭司，是圣洁的国度，是属神的子民」（彼前二 9）。 「支搭」帐棚是为自己，「筑」坛是为神；信徒离开世界之后留下唯一的 东西应该是神的「坛」，而不是自己的「帐棚」。「伯特利」位于示剑的 南方，亚伯兰的时代叫「路斯」，后来被雅各改名叫「伯特利」，意思是 神的殿（二十八 19）。「艾」位于伯特利东面 2 公里，字义是「荒场、废 墟」，这个名字可能艾城被毁之后（书八 28）才起的。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：应许之地位于「世界的十字路口」。「迦南地」位于各大文明古国的 中间，周围陆续崛起的帝国包括东方的亚述、巴比伦、波斯，南方的埃及，北方 的亚兰、赫人，西方的希腊、罗马。「迦南地」既是世界各国文化、商业、交通 的枢纽，也是各大帝国争霸的必经之地。神把这样一个「世界的十字路口」赐给 亚伯兰作应许之地，实在是有非常特别的意义。亚伯拉罕的后裔需要在此向全世 界作祭司国度的见证，也需要在此完全仰望神的保守和供应，否则完全不可能在 列强的夹缝中得以保存至今。",
