      sourceTextSource: "pdftotext",
      sourceTextSnippet: "142 【创十二 9】「后来亚伯兰又渐渐迁往南地去。」 亚伯兰渐渐迁往环境越来越差的「南地」，可能是被当地迦南人排挤 出了肥沃的地带，「连立足之地也没有给他」（徒七 5）。「南地」是迦南 地的南部边界，现在已经成为一片荒漠，但考古证据表明当时有人居住。 南地再往南就是埃及。亚伯兰既没有在南地筑坛，也没有在埃及筑坛，表 明他在难处中陷入了信心的低谷，忽略了「求告耶和华的名」（8 节；十三 4）。 上图：南地（Negev）的 Ein-Avdat 谷。南地气候炎热，已发现许多古人居住 的遗址。现代的南地是以色列南部的一片荒漠，占了以色列国土面积一半以上， 与埃及接壤。 【创十二 10】「那地遭遇饥荒。因饥荒甚大，亚伯兰就下埃及去，要 在那里暂居。」 神向亚伯兰显现之后（7 节），亚伯兰发现他面临重重困难：妻子不能 生育（十一 30），远离父家、举目无亲（1 节），又「遭遇饥荒」。神呼 召他的结果难道就是这样吗？亚伯兰的信心遇到巨大挑战，忧虑、惧怕也 接踵而来（12 节），人的心思也就冒出来代替了求问神（11-13 节）。亚伯 兰前往埃及「暂居」躲避饥荒，并没有事先求问神，但也是神造就他的计 划的一部分。因为「那地遭遇饥荒」，正是神所允许、所兴起的环境，为 要暴露亚伯兰肉体生命中的软弱、炼净他的信心。迦南地没有灌溉的河流， 完全倚靠冬春两季的雨水，雨水过多、过少或不准时，都会影响收成。「埃",
