      sourceTextSource: "pdftotext",
      sourceTextSnippet: "143 及」因为有尼罗河水定期泛滥，土地肥沃，收成比较稳定（四十一 54）。 埃及的海拔比迦南地要低，所以说「下埃及」。「埃及」在圣经里象征世 俗的世界。 上图：左塞尔金字塔（Pyramid of Djoser），约建于主前 2667-2648 年的古埃 及第三王朝时期。左塞尔金字塔是埃及的第一座金字塔，高 62 米，底边为 109 米 ×125 米，外部是白色抛光石灰石。这样一个庞大而精心雕琢的石造建筑，需要巨 大的人力、物力和国家对资源的控制、管理能力。这表明亚伯兰到达埃及之前约 600 年，埃及的文明已经相当繁荣。 下图：主前 20 世纪古埃及贵族克努姆霍特普二世（Khnumhotep II）的墓穴壁 画，画着 37 个亚伯拉罕同时代的闪族人在其首领 Absha 的带领下进入埃及。这些 闪族人涂着当时流行的黑眼圈，男人留着闪族独特的胡子，穿着彩色条子的长衣， 足履便鞋。他们携带茅、标枪、弓箭作为武器，还有一个人跟在驴子后面弹着七 弦琴。各种其他记录也表明，当没有河流的迦南地发生饥荒的时候，他们就可能 进入可以被尼罗河润泽的埃及东部躲避饥荒。",
