      sourceEvidenceSnippet: "上图：左塞尔金字塔（Pyramid of Djoser），约建于主前 2667-2648 年的古埃 及第三王朝时期。左塞尔金字塔是埃及的第一座金字塔，高 62 米，底边为 109 米 ×125 米，外部是白色抛光石灰石。这样一个庞大而精心雕琢的石造建筑，需要巨 大的人力、物力和国家对资源的控制、管理能力。这表明亚伯兰到达埃及之前约 600 年，埃及的文明已经相当繁荣。",
