      sourceTextSource: "pdftotext",
      sourceTextSnippet: "144 【创十二 11】「将近埃及，就对他妻子撒莱说：『我知道你是容貌俊 美的妇人，」 【创十二 12】「埃及人看见你必说：“这是他的妻子”，他们就要杀 我，却叫你存活。」 当时人的寿命大约是现代人的两倍，撒莱当时已经六十五岁，但容貌 可能相当于现代人的三十多岁。埃及人尊重婚姻，如果他们看上亚伯兰的 妻子，就会先把亚伯兰杀死。 【创十二 13】「求你说，你是我的妹子，使我因你得平安，我的命也 因你存活。』」 撒莱原是亚伯兰同父异母的妹妹（二十 12），所以「你是我的妹子」 并非是谎言，而是半真半假的「白谎」，企图以一半事实来遮掩另一半事 实。当人注目于环境里的难处，不注目于神的时候，就会用人的筹划来代 替信心的求告，结果正好落入魔鬼的网罗，叫我们软弱失败：「惧怕人的， 陷入网罗；惟有倚靠耶和华的，必得安稳」（箴二十九 25）。 【创十二 14】「及至亚伯兰到了埃及，埃及人看见那妇人极其美貌。」 14-16 节不提撒莱的名字，而只说「妇人」，表示尊重撒莱的名节。 【创十二 15】「法老的臣宰看见了她，就在法老面前夸奖她。那妇人 就被带进法老的宫去。」",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：因提夫二世像。古埃及第十一王朝的因提夫二世（Intef II，主前 2112 –2063 年），很可能就是亚伯兰所见到的法老。此时古埃及经过「第一中间时期」 （First Intermediate Period of Egypt，主前 2181-2055 年）的分裂，被第十一王朝重 新统一，首都位于埃及中部、尼罗河畔的底比斯。",
