      sourceTextSource: "pdftotext",
      sourceTextSnippet: "145 亚伯兰千算万算，也没有算到抢他的妻子是法老王。「法老」字义是 「伟大的房子」，本来是指埃及王的王宫，后来成为古埃及王的尊号。 上图：因提夫二世像。古埃及第十一王朝的因提夫二世（Intef II，主前 2112 –2063 年），很可能就是亚伯兰所见到的法老。此时古埃及经过「第一中间时期」 （First Intermediate Period of Egypt，主前 2181-2055 年）的分裂，被第十一王朝重 新统一，首都位于埃及中部、尼罗河畔的底比斯。 【创十二 16】「法老因这妇人就厚待亚伯兰，亚伯兰得了许多牛、羊、 骆驼、公驴、母驴、仆婢。」 亚伯兰陷入了他自己筹划的网罗，所以无法拒绝这些来路不正的财富。",
