      sourceTextSource: "pdftotext",
      sourceTextSnippet: "149 第 13 章 【创十三 1】「亚伯兰带着他的妻子与罗得，并一切所有的，都从埃及 上南地去。」 亚伯兰是跟随神走到迦南，罗得却是跟随人走到迦南，只有亚伯兰是 承受神应许的。南地的海拔比埃及高，所以说「上南地去」。在属灵的实 际里也是如此：回到神的应许里，就是把我们带往高处、带到神面前。 【创十三 2】「亚伯兰的金、银、牲畜极多。」 【创十三 3】「他从南地渐渐往伯特利去，到了伯特利和艾的中间，就 是从前支搭帐棚的地方，」 【创十三 4】「也是他起先筑坛的地方；他又在那里求告耶和华的名。」 亚伯兰「渐渐往伯特利去」（3 节），他的信心也「渐渐」复苏。「又 在那里求告耶和华的名」，标志着亚伯兰重新开始凭信心根据神来生活。 借着埃及的失败，神让亚伯兰学到了第一个功课（十二 10-20），就是凡事 不可根据自己和环境，而要单单根据信实的神。 上图：亚拉得（Tel Arad）遗址的祭坛。亚伯拉罕所筑的坛类似这种样式。 【创十三 5】「与亚伯兰同行的罗得也有牛群、羊群、帐棚。」 【创十三 6】「那地容不下他们；因为他们的财物甚多，使他们不能同",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：亚拉得（Tel Arad）遗址的祭坛。亚伯拉罕所筑的坛类似这种样式。",
