      sourceTextSource: "pdftotext",
      sourceTextSnippet: "151 耶和华的园子，也像埃及地」表明当时约旦河谷有充足的河水供应和完善 的灌溉系统。伯特利海拔 900 米左右，从伯特利的山地可以俯瞰约旦河谷， 罗得显然认真考察过了，确认自己所选择的是比较肥沃的土地。 上图：现代约旦河谷全景，靠近约旦河的地方还是滋润的。 【创十三 11】「于是罗得选择约旦河的全平原，往东迁移；他们就彼 此分离了。」 【创十三 12】「亚伯兰住在迦南地，罗得住在平原的城邑，渐渐挪移 帐棚，直到所多玛。」 【创十三 13】「所多玛人在耶和华面前罪大恶极。」 「耶和华不像人看人」(撒上十六 7），罗得所看见的是约旦河平原水 土滋润，神所看见的却是那地的所多玛人「罪大恶极」。罗得先是选择肥 沃的约旦河平原，接着又放弃游牧生活，与「在耶和华面前罪大恶极」的 所多玛人同居，最终受到极大的亏损，不但没有得到想要的，连原有的也 失去了（十四 12；十九 15-38）。生活在「罪大恶极」的环境中的信徒，并 不能发挥「光和盐」（太五 13-14）的功效，所以神呼召「我的民哪，你们 要从那城出来，免得与她一同有罪，受她所受的灾殃」（启十八 4）。所多 玛人的罪在于放纵同性恋行为（十九 4-5；罗一 26-27；利十八 22），因此 英文称同性恋者为「所多玛人 Sodomite」。 【创十三 14】「罗得离别亚伯兰以后，耶和华对亚伯兰说：『从你所 在的地方，你举目向东西南北观看；」 【创十三 15】「凡你所看见的一切地，我都要赐给你和你的后裔，直 到永远。」 【创十三 16】「我也要使你的后裔如同地上的尘沙那样多，人若能数 算地上的尘沙才能数算你的后裔。",
