      sourceTextSource: "pdftotext",
      sourceTextSnippet: "152 来作选择，而是凭信心拣选神，神就立刻让亚伯兰「举目向东西南北观看」 （14 节）应许之地，把「这地」（十二 7）变成了「凡你所看见的一切地」， 给了亚伯兰安慰和进一步的启示： • 应许之地预表基督，亚伯兰肉眼「所看见的一切地」（15 节）是应 许之地，灵里看见的却是基督。亚伯兰因着信心失去的约旦河平原，神用 整个应许之地来补偿；凡我们为着神所失去的东西，神也必用基督自己来 补偿。 • 神起初应许的「后裔」（十二 7），亚伯兰可能还以为是罗得。现在 罗得离开了，神反而进一步应许「我也要使你的后裔如同地上的尘沙那样 多」，表明这「后裔」将是出于神的作为。亚伯拉罕的后裔不但包括肉身 的犹太人，也包括每个因信称义的信徒：「你们既属乎基督，就是亚伯拉 罕的后裔，是照着应许承受产业的了」（加三 29）。 • 神进一步应许要把这地「赐给你和你的后裔」（15 节），而不只是 「赐给你的后裔」（十二 7），表明将把这地永远放在亚伯拉罕的名下，并 且「直到永远」（15 节）。实际上，神不只是应许这块地，而是用这块地 来表明「那座有根基的城，就是神所经营、所建造的」（来十一 10），每",
