      sourceEvidenceSnippet: "152 来作选择，而是凭信心拣选神，神就立刻让亚伯兰「举目向东西南北观看」 （14 节）应许之地，把「这地」（十二 7）变成了「凡你所看见的一切地」， 给了亚伯兰安慰和进一步的启示： • 应许之地预表基督，亚伯兰肉眼「所看见的一切地」（15 节）是应 许之地，灵里看见的却是基督。亚伯兰因着信心失去的约旦河平原，神用 整个应许之地来补偿；凡我们为着神所失去的东西，神也必用基督自己来 补偿。",
