      sourceTextSnippet: "153 个亚伯拉罕的属灵后裔也都能承受「那座有根基的城」。 【创十三 17】「你起来，纵横走遍这地，因为我必把这地赐给你。』」 「纵横走遍这地」就是宣告对应许之地的主权。应许之地此时有许多 迦南人居住，「纵横走遍这地」会面临许多难处，亚伯兰需要凭信心跟上 神的应许，这是承受神产业的秘诀。 上图：希伯仑山的南面。 【创十三 18】「亚伯兰就搬了帐棚，来到希伯仑、幔利的橡树那里居",
