      sourceTextSnippet: "155 上图：死海岸边的盐。死海位于以色列、西岸地区和约旦之间的大裂谷约旦 裂谷，低于海平面 424 米，是世界上最低的湖泊，死海的湖岸是地球陆地的最低 点。汇入死海的主要河流是约旦河，因没有出口，所以含盐量高达 34%，是一半 海水盐度的 9.6 倍，鱼类无法生存于水中，但有细菌及浮游生物。 【创十四 4】「他们已经事奉基大老玛十二年，到十三年就背叛了。」 【创十四 5】「十四年，基大老玛和同盟的王都来在亚特律·加宁，杀 败了利乏音人，在哈麦杀败了苏西人，在沙微·基列亭杀败了以米人，」 【创十四 6】「在何利人的西珥山杀败了何利人，一直杀到靠近旷野的 伊勒·巴兰。」 【创十四 7】「他们回到安密巴，就是加底斯，杀败了亚玛力全地的人， 以及住在哈洗逊·他玛的亚摩利人。」 四王的军队劳师远征 1000 多公里，却轻易地打败了以逸待劳的这 6 族 （5-7 节），其中「利乏音人」（申二 11）、「苏西人」还是身材高大的民 族，可见四王的战斗力很强。这 6 族可能是死海五王的盟军，四王的策略 是先清扫外围。",
