      sourceTextSource: "pdftotext",
      sourceTextSnippet: "156 【创十四 8】「于是所多玛王、蛾摩拉王、押玛王、洗扁王，和比拉王 （比拉就是琐珥）都出来，在西订谷摆阵，与他们交战，」 【创十四 9】「就是以拦王基大老玛、戈印王提达、示拿王暗拉非、以 拉撒王亚略交战；乃是四王与五王交战。」 【创十四 10】「西订谷有许多石漆坑。所多玛王和蛾摩拉王逃跑，有 掉在坑里的，其余的人都往山上逃跑。」 五王「在西订谷摆阵」（8 节），是因为那里「有许多石漆坑」，他们 想利用地理上的天然障碍，结果却自己「掉在坑里」。人所依仗的，往往 成了人的陷阱。「石漆坑」指开采沥青的矿井。死海盐度高、浮力大，南 部常有大块沥青漂浮，古埃及人在制作木乃伊的过程中使用死海的沥青， 古人 也用死海沥青作为天然 杀虫剂，古希腊人称死海为 沥青湖（Lake Asphaltites）。 上图：死海东西两岸都是山地。 【创十四 11】「四王就把所多玛和蛾摩拉所有的财物，并一切的粮食 都掳掠去了；」 【创十四 12】「又把亚伯兰的侄儿罗得和罗得的财物掳掠去了。当时",
