      sourceTextSource: "pdftotext",
      sourceTextSnippet: "157 罗得正住在所多玛。」 罗得因为「财物甚多」（十三 6）而离开亚伯兰，定居在繁荣的所多玛， 结果连人带「财物」都被「掳掠去了」。仇敌不只掳掠不信的世人，也掳 掠像「罗得」一样与世界为伍的信徒。信徒若在世界随波逐流，寻求地上 的名利地位，结局必然是连人带钱财一起被魔鬼掳去，不能得着安息。神 借着罗得的遭遇让我们看见，人眼中看为美的，结果往往是不美的，拣选 神才是最美的。 【创十四 13】「有一个逃出来的人告诉希伯来人亚伯兰；亚伯兰正住 在亚摩利人幔利的橡树那里。幔利和以实各并亚乃都是弟兄，曾与亚伯兰 联盟。」 「希伯来」字义是「过来，渡过河，属于希伯的」。亚伯兰是希伯的 后代（十一 14），原来住在幼发拉底河的东边，所以「希伯来人」可能是 双关语。本节是圣经里第一次出现「希伯来人」名字，后来也用「希伯来 人」来称呼以色列人（三十九 14、17)。「幔利」、「以实各」和「亚乃」 都是当地部落的首领。 【创十四 14】「亚伯兰听见他侄儿（原文是弟兄）被掳去，就率领他 家里生养的精练壮丁三百一十八人，直追到但，」 「三百一十八」正是亚伯兰的管家大马士革人「以利以谢 」（十 五 2）的希伯来文数值（1+30+10+70+7+200=318），而「以利以谢」的字义 是「神是帮助」，表明亚伯兰是依靠神的帮助。「家里生养的」表明这些 仆人不是从埃及获得的仆婢（十二 16），比较忠诚。「精练壮丁」表明还 有其他老弱妇幼，整个部落可能有 1000 人左右，这在当时是一支不小的势 力。古代文献表明，当时的战争常常只有几百人参战。",
