      sourceTextSource: "pdftotext",
      sourceTextSnippet: "161 上图：美索不达米亚古城努斯（Nuzi）出土的努斯石版，已发现 5000 多块， 大都是主前 14-15 世纪的法律和商业文件，印证了创世记中许多民俗和法律背景。 例如： 1、没有儿女的人可以设立一个朋友或仆人作为继承人，这个继承人以好好处 理主人的安葬事宜作为回报。（创十五 3） 2、父亲替女儿安排婚约，不必征求女儿的同意；但哥哥替妹妹安排婚约，必 须征求妹妹的同意（创二十四 50-51）。 3、新娘嫁人时应随身携带婢女，若本人未能生育，要把婢女送给丈夫作妾， 并将婢女生育的子女视为己出（创二十九 21、29；三十 3、9）。 4、婚约中可以要求丈夫不可再娶其他的妻子（创三十一 50）。 6、父亲有权把长子的权利转给小一点的儿子（创三十七 3）。 6、弟弟有责任娶寡嫂为妻，给哥哥留后（创三十八 8）。 【创十五 4】「耶和华又有话对他说：『这人必不成为你的后嗣；你本 身所生的才成为你的后嗣。』」 人的信心很容易受环境和时间的影响，因此忍不住用人的东西来代替 神所要赐下的。但人的东西不管看上去有多好，都无分于神的产业；只有 神自己在人身上的工作，才能使人承受神的国：「人若不重生，就不能见",
