      sourceTextSource: "pdftotext",
      sourceTextSnippet: "164 的功课。 【创十五 15】「但你要享大寿数，平平安安地归到你列祖那里，被人 埋葬。」 亚伯拉罕死时是一百七十五岁（二十五 7）。「归到你列祖那里」不是 指他被埋葬在列祖的坟墓里，而是说他的灵魂归到神那里，与列祖在一起 （二十五 8-9）。 【创十五 16】「到了第四代，他们必回到此地，因为亚摩利人的罪孽 还没有满盈。』」 从利未随雅各下埃及，到摩西率以色列人出埃及，正好是「第四代」 （出六 16-20）。「亚摩利人」代表所有的迦南民族，他们敬拜诸多偶像， 焚烧儿女为祭，行各种邪术，是神所憎恶的（申十八 9-12）。神是公义的， 必要审判人的罪孽；但神也是恩慈的，祂容忍等待世人悔改回转，直至日 期满足，才对不肯悔改的人施行审判。 上图：亚伯拉罕时代的迦南人敬拜各种偶像。上图是主前 19-17 世纪各种迦南 偶像。现藏于耶路撒冷的以色列博物馆（The Israel Museum, Jerusalem）。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：亚伯拉罕时代的迦南人敬拜各种偶像。上图是主前 19-17 世纪各种迦南 偶像。现藏于耶路撒冷的以色列博物馆（The Israel Museum, Jerusalem）。",
