      sourceTextSource: "pdftotext",
      sourceTextSnippet: "166 拉赫石版（Alalakh Tables）都描述了类似的立约仪式，立约的双方都要经过 劈开的动物（耶三十四 18），表示背约会面临和这些动物同样的命运。但 此时却是神独自经过肉块中间，象征神独自完成立约，单方面承诺履约。 因此，这约完全是神主动的恩典和赏赐，并非人与人之间交易式的立约（三 十一 44）。 上图：主前 18 世纪的马里文献（Mari Letters），出土于幼发拉底河中 部的马里，现存于卢浮宫。马里文献包括用阿卡德楔形文字写成的两万块 泥板文书，对研究亚伯拉罕、以撒、雅各时代的美索不达米亚历史、文化 和日常生活非常有价值。马里文献证明： 1、拿鹤城（创二十四 10）和哈兰城（创十一 31）的存在。 2、当时的人使用挪亚、亚伯兰、拉班、雅各这样的名字。 3、创世记提到的收养、继承习俗。 4、立约时在切开的牲畜之间走过。 【创十五 18】「当那日，耶和华与亚伯兰立约，说：『我已赐给你的",
