      sourceTextSource: "pdftotext",
      sourceTextSnippet: "167 后裔，从埃及河直到幼发拉底河之地。」 「我已赐给」表示此约已经成立，到了所罗门时代，这个应许终于应 验了（王上四 21、24），那时「所罗门统管诸王，从大河到非利士地直到 埃及的边界」（代下九 26）。「埃及河」指作为埃及和以色列边界线的「埃 （民三十四 5），一般认为就是西奈半岛东北部的阿里什旱溪（Wadi 及小河」 el Arish）。 【创十五 19】「就是基尼人、基尼洗人、甲摩尼人、」 【创十 五 20】「赫 人、比利洗 人、利乏音 人、」 【创十 五 21】「亚 摩利人、迦 南人、革迦 撒人、耶布 斯 人 之 地。』」 19-21 节列出十个 民族，实际 上居住在迦 南的不止十 个民族， 「十」是代 表「完全」。 上图：神将在四百多年后从应许之地驱逐的迦南民族。",
