      sourceTextSnippet: "168 第 16 章 【创十六 1】「亚伯兰的妻子撒莱不给他生儿女。撒莱有一个使女，名 叫夏甲，是埃及人。」 【创十六 2】「撒莱对亚伯兰说：『耶和华使我不能生育，求你和我的 使女同房，或者我可以因她得孩子（得孩子：原文是被建立）。』亚伯兰 听从了撒莱的话。」 【创十六 3】 「于是亚伯兰的妻子撒莱将使女埃及人夏甲给了丈夫为妾； 那时亚伯兰在迦南已经住了十年。」 神曾应许赐给亚伯兰后裔（十二 7），并指明必须是他本身所生的才算 他的后嗣（十五 4）。但 现在等了十年，亚伯兰 已经八十五岁，撒莱已 经七十五岁，仍未看见 神的应许成就。因此信 心的伟人也难免伸出肉 体的手，试图用人的方 法来代替神的作为，似 是而非地「成就」神的 应许。神特意让亚伯兰 等候多年，也允许他此 时再次使用人的方法； 人以为可以因此「被建 立」（2 节），但神却要 因此彻底「拆毁」亚伯 兰的肉体，使他真正成 为「一个将亡的亚兰人」 （申二十六 5），也让所 有亚伯拉罕的后裔学到 信心的功课。夏甲的儿",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：汉谟拉比法典（Code of Hammurabi），是古巴比伦国王汉谟拉 比（Hammurabi）约于主前 1754 年颁布的一部法律，是现存最早的一部比 较系统的法典，用阿卡德楔形文字刻在一根黑色的玄武岩圆柱上，上端有 汉谟拉比从太阳神沙玛什（Shamash）手中接过权杖的浮雕，现存于卢浮宫。",
