      sourceTextSource: "pdftotext",
      sourceTextSnippet: "171 而说：『在这里我也看见那看顾我的吗？』」【14】「所以这井名叫庇耳·拉 海·莱。这井正在加低斯和巴列中间。」 「耶和华的使者」（9 节）是代表神说话的天使，在圣经中常常被看为 「耶和华」自己（9、13 节；十八 10、13；出三 2、4；士六 12、14）。这 是一位愿意被人看见的神，而不只是看顾人的神。「庇耳·拉海·莱」的",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：书珥的旷野、加低斯和庇耳·拉海·莱。书珥路是一条古代商业大道， 以埃及的安城为起点，经以坦城进入书珥旷野的中部，再经加低斯、别是巴，可 前往大马士革及示拿等地。加低斯是一个具有四处大水泉的绿洲，位于别是巴西 南约 80 公里处，是西乃、南地和以东的交界点，由东南向西北有 Ain Qudeis，Ain Qudeirat，Ain Qoseimeh 和 Ain el-Muweilah 等四大水泉。庇耳·拉海·莱可能就是 Ain Muweileh，在加低斯西北方约 19 公里处。",
