      storedAbsolutePath: "/Users/simon/OHB/Resources/01_创世记/文档图片内容提取_20260515_121143/CMC-01_副本/p182_img106_632x429.png",
      sourceTextSource: "pdftotext",
      sourceTextSnippet: "174 作他们的神」（启二十一 3）。这个应许意味着神毫无保留地将自己赐给亚 伯拉罕和他的后裔（7-8 节），因此人也应当毫无保留地把神当作自己的神。 【创十七 9】「神又对亚伯拉罕说：『你和你的后裔必世世代代遵守我 的约。」【10】「你们所有的男子都要受割礼；这就是我与你并你的后裔 所立的约，是你们所当遵守的。」 实际上，除了「割礼」，神并没有指出其他具体要「遵守」的条款， 也没有详细规定哪些生活方式才是「作完全人」（1 节）的条件，唯一的要 求是用「割礼」表明向神的委身，毫无保留地把神当作自己的神。 【创十七 11】「你们都要受割礼（原文是割阳皮；14、23、24、25 节 同）；这是我与你们立约的证据。」 「割礼」即切割男性生殖器的包皮，是一些中东古代民族原来就有的习 俗。「受割礼」本身并不是约，而是被神用来作为神与人「立约的证据」， 表明人与犯罪的旧生命隔绝，单单信靠神、「不靠着肉体」（腓三 3）。在 挪亚之约中，挪亚不需要做任何事情；但在亚伯拉罕之约中，亚伯拉罕却 有责任「受割礼」，「作他未受割礼的时候因信称义的印证」（罗四 11）。 这进一步启示了神救赎计划的心意：新约的信徒在基督里也将受「不是人 手所行的割礼，乃是基督使你们脱去肉体情欲的割礼」（西 11）；因此， 我们不是以身体上的记号作「证据」，而是领受了圣灵的「印记」（弗四 30），「真受割礼的，乃是我们这以神的灵敬拜、在基督耶稣里夸口、不 靠 着肉 体 的」 （ 腓三 3）。 上 图：一位 纽约的犹 太拉比正 在给婴儿 行割礼。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "图：一位 纽约的犹 太拉比正 在给婴儿 行割礼。",
