      sourceTextSource: "pdftotext",
      sourceTextSnippet: "176 应许生的」才能承受应许，新约的信徒是「凭着应许作儿女，如同以撒一 样」（加四 28）。「以撒」字义是「他喜笑」。亚伯拉罕此时的「喜笑」 （17 节）掺杂了喜出望外和难以置信的复杂感情，他可能觉得合理的后裔 应该是以实玛利（18 节）。只有当应许成就之后，他才真正明白「耶和华 岂有难成的事」（十八 14），才有真实的「喜笑」（二十一 6）。 【创十七 20】「至于以实玛利，我也应允你：我必赐福给他，使他昌 盛，极其繁多。他必生十二个族长；我也要使他成为大国。」 神「应允」亚伯拉罕为以实玛利的求福，也「赐福」给以实玛利（二 十五 12-16）。虽然以实玛利后代的「昌盛」日后却成了以色列人的难处（诗 八十三 5-6），但这也是出于神。神在历史上不断使用以实玛利的后裔作为 祂管教、带领和保守亚伯拉罕后裔的器皿，用奇妙的方式将历史推向祂旨 意中的结局。 上图：1526 年 8 月 29 日，奥斯曼土耳其帝国在摩哈赤战役（Battle of Mohacs）中获胜，得到匈牙利西南部作为在东欧的稳固基地，进攻中欧整 整一个世纪，并于 1529 年围攻神圣罗马帝国首都维也纳（Siege of Vienna）。 面对奥斯曼威胁的空前增强，本来准备镇压新教的神圣罗马帝国被迫与新 教暂时妥协，宗教改革得以继续发展。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：1526 年 8 月 29 日，奥斯曼土耳其帝国在摩哈赤战役（Battle of Mohacs）中获胜，得到匈牙利西南部作为在东欧的稳固基地，进攻中欧整 整一个世纪，并于 1529 年围攻神圣罗马帝国首都维也纳（Siege of Vienna）。 面对奥斯曼威胁的空前增强，本来准备镇压新教的神圣罗马帝国被迫与新 教暂时妥协，宗教改革得以继续发展。",
