      sourceTextSnippet: "178 「九十九岁」本来是亚伯拉罕「想到自己的身体如同已死的时候」（罗 四 19），但却因着割礼所表明的对肉体的对付，成了他生命新的开始。 【创十七 25】「他儿子以实玛利受割礼的时候年十三岁。」 古代阿拉伯人「十三岁」接受割礼。 【创十七 26】 「正当那日，亚伯拉罕和他儿子以实玛利一同受了割礼。」 【创十七 27】「家里所有的人，无论是在家里生的，是用银子从外人 买的，也都一同受了割礼。」 第 18 章 【创十八 1】 「耶和华在幔利橡树那里向亚伯拉罕显现出来。那时正热， 亚伯拉罕坐在帐棚门口，」 上图：以实玛利的后代贝都因人（Bedouin）的帐棚。亚伯拉罕时代的帐棚可 能与此相似。 【创十八 2】「举目观看，见有三个人在对面站着。他一见，就从帐棚 门口跑去迎接他们，俯伏在地，」 「那时正热」指炎热的中午，是当地人午休的时间。亚伯拉罕可能正",
