      sourceTextSource: "pdftotext",
      sourceTextSnippet: "180 天使是神的代表（13 节）。 【创十八 11】「亚伯拉罕和撒拉年纪老迈，撒拉的月经已断绝了。」 【创十八 12】「撒拉心里暗笑，说：『我既已衰败，我主也老迈，岂 能有这喜事呢？』」 撒拉所看到的是「我」和「我主」，看到的都是难处，因此毫无生子 的指望。但神的应许并不需要人力的配合，祂常常要等到人对自己完全绝 望的时候才开始做事。我们天然的「我」减少了多少，神的作为就显出多 少。 【创十八 13】「耶和华对亚伯拉罕说：『撒拉为什么暗笑，说：“我 既已年老，果真能生养 吗？”」 圣经中常常把代 表神说话的天使看为 「耶和华」自己（10、 13 节；十六 9、13；出 三 2、4；士六 12、14）。 【创十八 14】「耶 和华岂有难成的事 吗？到了日期，明年这 时候，我必回到你这 里，撒拉必生一个儿 子。』」 撒拉对神的认识 还很肤浅，但神却没有 责怪人的小信，反而借 此做出了最伟大的宣 告：「耶和华岂有难成 的事吗」。这句宣告在 圣经中不断回响（耶三 十二 17、27；亚八 6；",
