      sourceTextSource: "pdftotext",
      sourceTextSnippet: "183 是在讨价还价，而是谦卑地（27 节）探求神的旨意，要进一步认识神。他 并不是在与神争辩，好像自己比神更公义、更慈爱，而是在寻求神赦免的 恩典。罗得虽然也被称为「义人」（彼后二 7），但他的行为证明他并不完 全（十九 8），实际上，所多玛城中「没有义人，连一个也没有」（罗三 10），正如神对先知耶利米说：「你们当在耶路撒冷的街上跑来跑去，在 宽阔处寻找，看看有一人行公义、求诚实没有？若有，我就赦免这城」（耶 五 1）。 【创十八 33】「耶和华与亚伯拉罕说完了话就走了；亚伯拉罕也回到 自己的地方去了。」 第 19 章 【创十九 1】 「那两个天使晚上到了所多玛；罗得正坐在所多玛城门口， 看见他们，就起来迎接，脸伏于地下拜，」 「城门口」指城门洞两侧的小房间，是人们处理交易和诉讼的公共会所 （得四 1）。罗得「坐在所多玛城门口」，表明他在所多玛城已经有一定的 社会地位（9 节）。我们若和罗得一样贪恋世界，当主再来的时候，也会被 主发现正坐在「所多玛城门口」。从希伯仑到所多玛大约 90 公里，通常要 走两天半，但天使半天就到了。 下图：拉吉 （Lachish）城门口 的遗址及复原示 意图。从城门进 来，两侧各有 3 个 房间，平时作为交 易、诉讼、公告的 公共会所，战时作 为防御工事。基 色、米吉多、夏琐、 撒玛利亚和但的",
