      sourceTextSource: "pdftotext",
      sourceTextSnippet: "184 遗址都有相同的城门结构。 【创十九 2】「说：『我主啊，请你们到仆人家里洗洗脚，住一夜，清 早起来再走。』他们说：『不！我们要在街上过夜。』」 「街上」原文是「广场、宽阔处」，指城门口的宽阔处。天使可能是 考验罗得的诚意。 上图：别是巴遗址（Tel Be’er Sheva）城门口的宽阔处，是一个小广场，客旅 如果找不到住处，可以「在街上过夜」（创十九 2）。 【创十九 3】「罗得切切地请他们，他们这才进去，到他屋里。罗得为 他们预备筵席，烤无酵饼，他们就吃了。」 「无酵饼」很快就可以做好，表示这不像亚伯拉罕招待天使的悠闲的 筵席，而是比较匆忙（出十二 39）。 【创十九 4】「他们还没有躺下，所多玛城里各处的人，连老带少，都 来围住那房子，」 「所多玛城里各处的人」表明全城都充满了罪恶。「连老带少」原文 指男性。 【创十九 5】「呼叫罗得说：『今日晚上到你这里来的人在哪里呢？把 他们带出来，任我们所为。』」 「任我们所为」原文是「任我们亲近」。所多玛人「一味地行淫，随 从逆性的情欲」（犹 7），又「心骄气傲」（结十六 49），所以遭到神「永 火的刑罚，作为鉴戒」（犹 7）。英文的「同性恋行为 Sodomy」一词就源",
