      sourceTextSnippet: "187 心意。 【创十九 22】「你要速速地逃到那城；因为你还没有到那里，我不能 做什么。』因此那城名叫琐珥（就是小的意思）。」 因为神怜恤我们，所以祂在我们身上的计划常常受我们的限制：我们 若不肯与神配合，神往往就「不能作什么」。 【创十九 23】「罗得到了琐珥，日头已经出来了。」 「日头已经出来了」，表明这是能看清楚人脸的时候。古人若黑夜捉 贼而打死贼人，不算有罪，但「若太阳已经出来，就为他有流血的罪」（出 二十二 2-3）。神的审判是在光明中，要认清楚谁当毁灭，谁不当毁灭，因 为「审判全地的主」不但要行公义，也要分别善恶（十八 23-25）。 【创十九 24】「当时，耶和华将硫磺与火从天上耶和华那里降与所多 玛和蛾摩拉，」 【创十九 25】「把那些城和全平原，并城里所有的居民，连地上生长 的，都毁灭了。」 「那些城」包括「所多玛、蛾摩拉、押玛、洗扁」四座城（申二十九 3），",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：所多玛和蛾摩拉毁灭的示意图。考古发现，「所多玛和蛾摩拉」可能 毁于含沥青的土壤发生爆炸。在这种土壤中形成了石油与天然气的储存槽，后因 油气压力过大或地震而引起爆炸，把石油抛向空中，然后石油一面燃烧一面落下， 使二城遭受烈焰焚毁。直到现代，死海一带仍然弥漫着硫磺的味道。",
      sourceEvidencePage: 196,
      sourceEvidenceOrigin: "next-page",
