      sourceTextSnippet: "188 现在已经陷入海底。死海南部的平原地区只有「琐珥」（22 节，即比拉） 幸存。目前考古学家在死海南部平原发现了五处古城遗迹（Bab edh-Dhra， Numeira，Safi，Feifa，Khanazir），但还不能确定它们分别对应于哪个古城。 「所多玛和蛾摩拉」可能毁于含沥青的土壤发生爆炸，直到现代，这里还 弥漫着硫磺的味道。 上图：所多玛和蛾摩拉毁灭的示意图。考古发现，「所多玛和蛾摩拉」可能 毁于含沥青的土壤发生爆炸。在这种土壤中形成了石油与天然气的储存槽，后因 油气压力过大或地震而引起爆炸，把石油抛向空中，然后石油一面燃烧一面落下， 使二城遭受烈焰焚毁。直到现代，死海一带仍然弥漫着硫磺的味道。 【创十九 26】「罗得的妻子在后边回头一看，就变成了一根盐柱。」 主耶稣要我们「回想罗得的妻子」（路十七 32）：「凡想要保全生命 的，必丧掉生命；凡丧掉生命的，必救活生命」（路十七 33）。死海中有 大量盐块，罗得的妻子可能是被爆炸抛向空中又落下来的大量盐块给覆盖 了。 上图：死海南部各种奇形怪状的盐柱很常见。 【创十九 27】「亚伯拉罕清早起来，到了他从前站在耶和华面前的地 方，」 【创十九 28】「向所多玛和蛾摩拉与平原的全地观看，不料，那地方 烟气上腾，如同烧窑一般。」 亚伯拉罕站在他代祷的地方（27 节），默默地见证这个大毁灭。「不",
