      sourceTextSource: "pdftotext",
      sourceTextSnippet: "190 【创十九 34】「第二天，大女儿对小女儿说：『我昨夜与父亲同寝。 今夜我们再叫他喝酒，你可以进去与他同寝。这样，我们好从父亲存留后 裔。』」 【创十九 35】「于是，那夜她们又叫父亲喝酒，小女儿起来与她父亲 同寝；她几时躺下，几时起来，父亲都不知道。」 【创十九 36】「这样，罗得的两个女儿都从她父亲怀了孕。」 罗得的女儿道德水平低下，罗得有不可推卸的责任。他不但没有教导 她们与世俗分别，反而带她们搬进淫乱的所多玛城，以致耳濡目染、近墨 者黑。 上图：主前 2300-2000 年迦南地精致的高脚银杯，上面画着各种神话故事，可 能是从亚兰带到迦南地的传家宝。现藏于耶路撒冷的以色列博物馆（The Israel Mu seum, Jerusalem）。 【创十九 37】「大女儿生了儿子，给他起名叫摩押，就是现今摩押人 的始祖。」",
