      sourceTextSource: "pdftotext",
      sourceTextSnippet: "192 上十一 7；耶三十二 35）。神允许这一切发生，让我们从中看到，属灵的 淫乱必然会产生异端、异教，给神的子民带来极大的难处。 上图：罗得及其后裔摩押和亚们：1、罗得离开亚伯兰，往东迁移，直 到所多玛，被北方四王所掳，但被亚伯兰救回（创十三 4-13，创十四 12-16）； 2、天使自希伯仑到所多玛，罗得接待天使（创十九 1-14）;3、天使救罗得 等出城后，神毁所多玛等城，罗得和两个女儿逃到小城琐珥（创十九 15-22）； 4、罗得与两个女儿乱伦生了摩押和便亚米（创十八 30-十九 38），成为摩 押和亚扪两国的祖先。 第 20 章 【创二十 1】「亚伯拉罕从那里向南地迁去，寄居在加低斯和书珥中间 的基拉耳。」 自从亚伯拉罕 75 岁离开哈兰（十二 4），已经走了将近 25 年的信心之 路，现在即将来到恩典的最高峰，经历复活生命的大能。神不久前两次宣 告「到明年这时节，撒拉必给你生以撒，我要与他坚定所立的约」（十七 21；十八 10），应许之子以撒的出生，将成为神所应许的「国度、君王」 （十七 6）的开始，成为「地上的万族都要因你得福」（十二 3）的根据。 不料，此时亚伯拉罕却「神差鬼使」地离开了居住了 20 多年的希伯仑（十 三 18），「从 那里向南地 迁去」，来到 了「基拉耳」， 以致妻子撒 拉差点在「基 拉耳」被人抢 去，以撒的出 生也差点落 空。「希伯仑",
