      sourceTextSnippet: "193 」的字义是「联合」；「加低斯 」的字义是「神圣的」；「书珥 」 的字义是「墙」，位于埃及的边界；「基拉耳 」的字义是「寄宿处」。 圣经特地点出这几个地名，让我们看见，亚伯拉罕实际上是离开了与神「联 合」的位置，来到「圣」和「俗」之间「寄宿」。这背后固然有人的愚昧， 很可能还有撒但的作为，但最重要的是，这一切都是在神的允许和管理之 下发生的（18 节），目的是要在以撒出生之前，兴起环境，在「基拉耳」 彻底显明、对付亚伯拉罕生命中深藏的那些残缺。 上图：所多玛城被 神毁灭之后，亚伯拉罕 从希伯仑向南地迁去， 寄居在加低斯和书珥 中间，有段时间停留在 基拉耳，结果在基拉耳 遇到了极大的试探。基 拉耳就是希伯仑的西 南方的 Tel Haror，靠近 南地的边缘。 基拉耳遗址 Tel 左图： Haror。基拉耳是靠近南地 西北边缘最大的古代城 市之一，位于别是巴西北 Nahal Gerar 河谷附近。从 Tel Haror 的基拉耳遗址寺 庙里挖掘出了青铜时代 中期（主前 1800-1550 年） 被献祭的动物骸骨，这正 是亚伯拉罕、以撒、雅各 的时代。上图中间的 A 是",
