      sourceTextSnippet: "199 亚伯拉罕的软弱，他不再看环境、不再看自己，而是单单看神，一天比一 天更信靠神。 上图：亚伯拉罕生平行踪：1、从吾珥经哈兰到迦南（创十二 5）；2、 先到了示剑，再到伯特利和艾的中间，又渐迁往南地去（创十二 6-9）；3、 因饥荒就去埃及，不久再回南地（创十二 10-十三 1）；4、又渐迁往伯特利， 在伯特利时罗得离去（创十三 3-13）；5、回希伯仑居住（创十三 18）。6、 迁往基拉耳（创二十）。 第 21 章",
