      sourceTextSnippet: "202 【创廿一 11】「亚伯拉罕因他儿子的缘故很忧愁。」 亚伯拉罕已经为以实玛利起名（十六 15），表明他已经接纳以实玛利 为自己的儿子，有继承产业的权利。父子俩一起生活了十多年，有深厚的 感情，所以「很忧愁」。 【创廿一 12】「神对亚伯拉罕说：『你不必为这童子和你的使女忧愁。 凡撒拉对你说的话，你都该听从；因为从以撒生的，才要称为你的后裔。」 虽然撒拉逼迫夏甲并非出于善意，但却恰好与神的计划符合，因为只 有「从以撒生的」，才是神所应许的后裔（罗九 7；来十一 18）。同样， （罗九 8）。 「肉身所生的儿女不是神的儿女；惟独那应许的儿女才算是后裔」 【创廿一 13】「至于使女的儿子，我也必使他的后裔成立一国，因为 他是你所生的。』」 「使女的儿子」预表「按着血气生的」（加四 23），但神在他身上也 有特别的计划。信徒虽然已经重生，有了属灵的生命，但我们原有属血气 的生命并没有立刻消失，仍将一直存留，与属灵的生命争战，直到身体得",
