      sourceTextSource: "pdftotext",
      sourceTextSnippet: "206 【创廿一 25】「从前，亚比米勒的仆人霸占了一口水井，亚伯拉罕为 这事指责亚比米勒。」 【创廿一 26】「亚比米勒说：『谁做这事，我不知道，你也没有告诉 我，今日我才听见了。』」 【创廿一 27】「亚伯拉罕把羊和牛给了亚比米勒，二人就彼此立约。」 「羊和牛」原文都是单数，指「一只牛和一只羊」，用作立约的仪式。 【创廿一 28】「亚伯拉罕把七只母羊羔另放在一处。」 【创廿一 29】「亚比米勒问亚伯拉罕说：『你把这七只母羊羔另放在 一处，是什么意思呢？』」 【创廿一 30】「他说：『你要从我手里受这七只母羊羔，作我挖这口 井的证据。』」 「七 Sheba 」和「起誓 Shaba 」原文辅音相同（23、24 节）， 发音相似。「七只母羊羔」是双关语，亚比米勒接受这「七只母羊羔」， 表示起誓同意亚伯拉罕对井的合法权利。在古代中东，国家或个人收纳礼 物表示讲和，拒绝礼物表示不和（王上十五 19)。 【创廿一 31】 「所以他给那地方起名叫别是巴（就是盟誓的井的意思）， 因为他们二人在那里起了誓。」 「别是巴 」位于基拉耳东南四十公里，字义是「七倍誓约的井」。 「别 Beer」原文意思是「井」，「是巴 Sheba 」原文意思是「七」， 与「起誓 Shaba 」原文辅音相同，发音相似（23、24 节）。迦南地的 牧人主要依靠井 水饲养牲畜，这 井的权益得到条 约的保障，代表 亚伯拉罕在迦南 地获得了第一个 立足点。此后， 亚伯拉罕和以撒 大部分时间都居 住在别是巴。别",
