      sourceTextSource: "pdftotext",
      sourceTextSnippet: "207 是巴后来成为以色列最南端的城市，「从但到别是巴」这句话被用来代表 应许之地的全境（士二十 1；撒下十七 11；王上四 25）。 上图：20 世纪中期亚伯拉罕井的照片，现在位于别是巴遗址的庭院内。亚伯 拉罕井直径 3 米，深 26 米，井口的石头可能是拜占庭时代的，已经被井绳磨出了 许多很深的痕迹。 【创廿一 32】「他们在别是巴立了约，亚比米勒就同他军长非各起身 回非利士地去了。」 「非利士人的地」靠近地中海。「非利士人」在主前 1200 年才从迦斐 托（克里特岛）大举侵入迦南地（摩九 7；耶四十七 4），亚比米勒可能是 早期定居迦南地和平贸易的非利士人。 【创廿一 33】「亚伯拉罕在别是巴栽上一棵垂丝柳树，又在那里求告 耶和华——永生神的名。」 亚伯拉罕「栽上一棵垂丝柳树」，是为了用这种坚硬、长寿的树来纪念 此约，并且敬拜神、感谢神。亚伯拉罕对神的称呼从「至高的神」（十四 22）到「全能的神」（十七 1），现在更深入到「永生神」，这次经历已经 使他认识到，神是永恒的神，祂的信实和保守永不改变，祂的应许永不落",
