      storedAbsolutePath: "/Users/simon/OHB/Resources/01_创世记/文档图片内容提取_20260515_121143/CMC-01_副本/p220_img124_720x405.png",
      sourceTextSource: "pdftotext",
      sourceTextSnippet: "212 以撒此时已经是个有力气背柴上山的年轻人（6 节），而亚伯拉罕已经 是一百二十多岁的老人。以撒虽然也有疑问（7 节），但却没有挣扎反抗， 而是甘愿被老父「捆绑」，正如主耶稣「存心顺服，以至于死，且死在十 字架上」（腓二 8），「不要成就我的意思，只要成就祢的意思」（路二十 二 42）。这样的顺服是完美的，就像「没有残疾」的祭牲（利一 3）一样 蒙神悦纳。以撒的一生并没有以重大的成就出名，却以默默的顺服预表了 神所预备的代罪羔羊：「祂像羊羔被牵到宰杀之地，又像羊在剪毛的人手 下无声，祂也是这样不开口」（赛五十三 7；徒八 32）。犹太史学家约瑟 夫记载，这父子俩此时有一番对话，都做出了顺服的决定（《犹太古史记》 卷 1 第 13 章 228-232 节）。 【创廿二 10】「亚伯拉罕就伸手拿刀，要杀他的儿子。」 9-10 节是最关键的一刻，每个动作都被神所记念。「伸手拿刀，要杀」 这样的细节，表明亚伯拉罕绝不是装装样子，而是毫无保留地交出了以撒， 用行为印证了他的信心（雅二 21）。在亚伯拉罕一生的信心道路上，神让 他学习了四次舍弃，学习爱神超过爱神所赐的恩典（约二十一 15）： 1. 舍弃本地、本族、父家（十二 1）； 2. 舍弃他心目中的继承人侄儿罗得（十三 8-12）； 3. 舍弃肉体的努力、夏甲所生的儿子以实玛利（二十二 14）； 4. 舍弃神的恩典、等了 25 年的应许之子以撒（本节）。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：耶路撒冷 附近出土的主前 1500 年 的 牛 腿 刀 （Khopesh），长 58 厘 米 ， 主 前 2500-1300 年在埃及 和迦南地流行，早期 用青铜制作，后期用 铁制作。牛腿刀的形状像牛腿，适合劈砍，是中王国和新王国时期埃及军队的标",
