      sourceTextSource: "pdftotext",
      sourceTextSnippet: "214 （约一 29）来代替承受应许的人而死，让承受应许的人可以活在神的面前。 上图：以色列最常见的肥尾羊 Awassi sheep，角很容易被树枝卡住。 【创廿二 14】「亚伯拉罕给那地方起名叫『耶和华以勒』（就是耶和 华必预备的意思），直到今日人还说：『在耶和华的山上必有预备。』」 「耶和华以勒 」由「耶和华 」和「看见 」两个词合 成，意思是「耶和华必看顾、必预备」，与「摩利亚 」的字根相同。 亚伯拉罕在实际奉献的过程中，才看见了「耶和华的山上必有预备」；我 们也只有来到「耶和华的山上」，站在神要我们站的地位上顺服神、献上 自己，才能真正在灵里看见「耶和华以勒」，享用神在恩典里作我们的供 应。旧约中有七个用来称呼神的复合名： 1、「耶和华以勒 」——耶和华必预备（创二十二 14）； 2、「耶和华拉法 」——耶和华是医治你的（出十五 26）； 3、「耶和华尼西 」——耶和华是我的旌旗（出十七 15）； 4、「耶和华沙龙 」——耶和华是平安（士六 24）； 5、「耶和华路以 」——耶和华是我的牧者（诗二十三 1）； 6、「耶和华齐根努 」——耶和华是我们的义（耶二十三 6）； 7、「耶和华沙玛 」——耶和华所在（结四十八 35）。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：以色列最常见的肥尾羊 Awassi sheep，角很容易被树枝卡住。",
      sourceEvidencePage: 222,
