      sourceTextSource: "pdftotext",
      sourceTextSnippet: "219 间还算什么呢？只管埋葬你的死人吧！』」 主前 18 世纪的汉谟拉比法典记载，当时一个男奴隶的价格是三十舍客 勒银子，女奴隶是二十舍客勒银子。因此，「四百舍客勒银子」大约有 4.56 公斤，是一笔巨款。由于我们并不了解这块田有多大，所以不能确定这价 格是否公道。大卫只用五十舍客勒银子买下禾场和牛（撒下二十四 24）， 耶利米仅用十七舍客勒银子就购地一块（耶三十二 9）；但大卫也付了六百 舍客勒买下整个圣殿的地址（代上二十一 25），暗利也用二他连得银子（六 千舍客勒）买下整个撒玛利亚山丘（王上十六 24）。 上图：以色列出土的第一圣殿时期的砝码石（Weight stones），上面刻有重量。 从左上角开始，按顺时针方向依次是：比加（beka，半舍客勒；出三十八 26）、 并（pim，三分之二舍客勒；撒上十三 21）、2 舍客勒（shekel，11.4 克）和 Nezeph （六分之五舍客勒）。 【创廿三 16】「亚伯拉罕听从了以弗仑，照着他在赫人面前所说的话， 把买卖通用的银子平了四百舍客勒给以弗仑。」 虽然是一笔巨款，但亚伯拉罕并没有与以弗仑讨价还价，使人得荣耀。 他与赫人相处的原则正如当初对待所多玛王一样（十四 22-23）。「买卖通 用的银子」指用于商业交易的标准成色的银子，上面可能刻有重量。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：以色列出土的第一圣殿时期的砝码石（Weight stones），上面刻有重量。 从左上角开始，按顺时针方向依次是：比加（beka，半舍客勒；出三十八 26）、 并（pim，三分之二舍客勒；撒上十三 21）、2 舍客勒（shekel，11.4 克）和 Nezeph （六分之五舍客勒）。",
