      sourceTextSource: "pdftotext",
      sourceTextSnippet: "220 【创廿三 17】「于是，麦比拉、幔利前、以弗仑的那块田和其中的洞， 并田间四围的树木，」 【创廿三 18】「都定准归与亚伯拉罕，乃是他在赫人面前并城门出入 的人面前买妥的。」 「前」（17 节）通常指东面（十三 9）。这份买卖是在赫人长老和见 证人面前，按照正规手续办妥的。虽然亚伯拉罕寄居在赫人中间，他的生 活与赫人有非常彻底的分别，决不欠他们的情。 【创廿三 19】「此后，亚伯拉罕把他妻子撒拉埋葬在迦南地幔利前的 麦比拉田间的洞里。（幔利就是希伯仑）。」 【创廿三 20】「从此，那块田和田间的洞就借着赫人定准归与亚伯拉 罕作坟地。」 虽然神已经应许将「迦南全地」赐给亚伯拉罕和他的后裔永远为业（十 七 8），但亚伯拉罕生前所获得的唯一一块迦南地业，却是买来的「坟地」。 亚伯拉罕不惜代价地买下这坟地，因为他一定要让自己的尸骨留在迦南地， 作神应许的见证，等候四百年后神应许的成就（十五 13-16）。这块坟地成 为神应许的标志，亚伯拉罕、撒拉、以撒、利百加、雅各和利亚都葬在这",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：麦比拉洞（Cave of Machpelah），又名列祖之洞（Cave of the Patriarchs），位于希律王时代的犹太建筑改建而成的易卜拉欣清真寺下方， 在希伯仑旧城中心。圣经和古兰经都提到，该洞及周围是亚伯拉罕所购买 的一块家族坟地（创二十三 17-19）。",
