      sourceTextSource: "pdftotext",
      sourceTextSnippet: "223 （十一 31）。主前 18 世纪的马里文献（Mari Letters）证实了「拿鹤的城」 和哈兰城（创十一 31）的存在。 上图：约旦贝都因人的单峰骆驼，亚伯拉罕的骆驼就是这种样子。全 世界 94%的骆驼的单峰骆驼（Dromedaries），6%的骆驼是双峰骆驼（Bactrian camels）。骆驼于主前 1200 年左右开始在大规模的游牧或军队中使用，因 此曾有人质疑亚伯拉罕时代的骆驼是后来编的故事。但考古证据表明，索 马里和南部阿拉伯的人类早在主前 3000 年就开始驯养单峰骆驼作为家畜， 埃及出土了许多主前 2500-1400 年的骆驼文物。 【创廿四 11】「天将晚，众女子出来打水的时候，他便叫骆驼跪在城 外的水井那里。」 古代中东乡村的公共水井通常在村外，以方便饮牛羊。妇女通常在早 晨和傍晚比较凉爽的时候出来打水，井旁就成了她们的社交场所。 【创廿四 12】「他说：『耶和华——我主人亚伯拉罕的神啊，求祢施 恩给我主人亚伯拉罕，使我今日遇见好机会。」 【创廿四 13】「我现今站在井旁，城内居民的女子们正出来打水。」",
      sourceEvidenceType: "figure_caption",
