      sourceTextSnippet: "225 人的」。 【创廿四 16】「那女子容貌极其俊美，还是处女，也未曾有人亲近她。 她下到井旁，打满了瓶，又上来。」 【创廿四 17】「仆人跑上前去迎着她，说：『求你将瓶里的水给我一 点喝。』」 【创廿四 18】「女子说：『我主请喝！』就急忙拿下瓶来，托在手上 给他喝。」 【创廿四 19】「女子给他喝了，就说：『我再为你的骆驼打水，叫骆 驼也喝足。』」 【创廿四 20】「她就急忙把瓶里的水倒在槽里，又跑到井旁打水，就 为所有的骆驼打上水来。」 【创廿四 21】「那人定睛看她，一句话也不说，要晓得耶和华赐他通 达的道路没有。」 要让这十匹骆驼「喝足了」（22 节），利百加至少要打 100 多瓶水， 没有足够的爱心和体力是做不到的。所以老仆人「定睛看她，一句话也不 说，要晓得耶和华赐他通达的道路没有」。 上图：一群中东的单峰骆驼（Dromedary）在水槽饮水。骆驼的水存储 在血液中，喝足水后可以坚持三周。哺乳动物的血红细胞通常是圆形的， 而骆驼的血红细胞是椭圆形的，在脱水（Dehydration）状态下仍可以流动，",
