      sourceTextSnippet: "226 在饮用大量水时也不会因渗透性的巨变（High osmotic variation）而破裂。 一头成年的单峰骆驼一次可以喝下 100-150 公升水，甚至可以 3 分钟喝 200 公升水。因此，「十匹骆驼」（创二十四 10）需要 1-2 吨水才能「喝足」 （创二十四 19），利百加至少要为陌生人打 100 多瓶水！ 【创廿四 22】「骆 驼喝足了，那人就拿一 个金环，重半舍客勒， 两个金镯，重十舍客勒， 给了那女子，」 一「舍客勒」大约 是 11.4 克，「半舍客勒」 的金鼻环重 5.7 克，「十 舍客勒」的金手镯大约 每个重 57 克。这些礼物 的价值超过当时一个雇 工一年的工资。 上图：主前 13 世纪的以色列金首饰。现藏于耶路撒冷以色列博物馆（Israel Museum）。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：主前 13 世纪的以色列金首饰。现藏于耶路撒冷以色列博物馆（Israel Museum）。",
