      sourceTextSnippet: "231 （62 节）回来，「在田间默想，举目一看」，就看见了神的预备、神的恩 典。 • 圣经并没有记载以撒一生太多的事迹，却记载了他的「默想」。神选 召亚伯拉罕，是要做恢复计划的起头，所以他必须凭信心完全地顺服神、 跟随神。神选召以撒，是要显明被召的人应该学会享用恩典、享用神。人 所做的太多，就不是恩典、不是享用。所以以撒的一生不必做轰轰烈烈的 大事，他所带出 的见证，就是显 明一个会享用恩 典的人、会享用 父的预备的人。 【 创 廿 四 64】「利百加举 目看见以撒，就 急忙下了骆驼，」 【 创 廿 四 65】「问那仆人 说：『这田间走 来迎接我们的是 谁？』仆人说： 『是我的主人。』 利百加就拿帕子 蒙上脸。」 「拿帕子蒙 上脸」可能表示 她是新娘，许多 中东民族的新娘 在婚礼上都戴着 面纱。 上图：一位戴着面纱的贝都因（Bedouin）妇女。",
