      sourceTextSnippet: "236 为人安静，常住在帐棚里。」 【创廿五 28】「以撒爱以扫，因为常吃他的野味；利百加却爱雅各。」 以扫和雅各的个性完全相反，他们的后裔也是如此：以东人是比较活 跃的游牧民族，以色列人是比较稳重的半游牧民族。以撒是个平凡的人， 他也有普通人的软弱，也会偏心。而利百加偏爱雅各，可能因为神的预言 （23 节）。 【创廿五 29】「有一天，雅各熬汤，以扫从田野回来累昏了。」 【创廿五 30】「以扫对雅各说：『我累昏了，求你把这红汤给我喝。』 因此以扫又叫以东（就是红的意思）。」 上图：以色列的红豆汤，是用扁豆和大麦混煮成的稀粥。 【创廿五 31】「雅各说：『你今日把长子的名分卖给我吧。』」 【创廿五 32】「以扫说：『我将要死，这长子的名分于我有什么益处 呢？』」 【创廿五 33】「雅各说：『你今日对我起誓吧。』以扫就对他起了誓， 把长子的名分卖给雅各。」 【创廿五 34】「于是雅各将饼和红豆汤给了以扫，以扫吃了喝了，便 起来走了。这就是以扫轻看了他长子的名分。」 • 以扫「贪恋世俗」，只关心眼前短暂的需要，轻看神的应许，所以",
