      sourceTextSource: "pdftotext",
      sourceTextSnippet: "237 轻率地「因一点食物把自己长子的名分卖了」（来十二 16）。 • 雅各并不是趁人之危，因为以扫远远没有到「我将要死」（32 节） 的地步。雅各只是因为看中属灵的福分，所以抓住一切机会来「抓」，没 想到歪打正着，以扫竟然如此轻看「长子的名分」，属灵的福分在他心中 没有任何价值。 • 表面上，是以扫轻看了他「长子的名分」，实际上，他只是肉体上 的长子，一开始就没有得着属灵「长子的名分」，因为神早已预言「将来 大的要服事小的」（23 节）。 • 今天许多人也常常把生活中的一点小事夸大成「我将要死」，为眼 前的一点蝇头小利而放弃敬拜、聚会、读经、祷告。因为神「儿子的名分」 （弗一 5）在他们心中也是无足轻重，而他们恐怕也和以扫一样，一开始就 没有真正「得着儿子的名分」（加四 5）。 • 「长子的名分」指作为长子的权利和地位。后来以色列人长子的权 利包括：承受属灵的祝福，作一家之主（撒上二十 29），继承两倍的产业 （申二十一 17）。 上图：美索不达米亚古城努斯（Nuzi）出土的努斯石版，已发现 5000 多块，大都是主前 14-15 世纪的法律和商业文件，印证了创世记中许多记录 的民俗和法律背景。其中一块石版记录，一位名叫 Tupkitilla 的人把他一个 果园的继承权转让给他的兄弟 Kurpazah，交换 3 只羊。以扫为了一碗红豆 汤把长子的名分卖给雅各，也就是转让他作为长子所额外拥有的继承权。",
      sourceEvidenceType: "figure_caption",
