      sourceTextSnippet: "239 • 神兴起同样的饥荒，但对亚伯拉罕和以撒的带领却不相同，因为神 借着他们所要表达的心意不同：神当初没有阻止亚伯拉罕下埃及，只在埃 及暗暗地保守他，是为了让他学习因信进入应许（十二 10-20）；如今神阻 止以撒下埃及，又在基拉耳明明地保守他，是为了让他学习因信承受应许。 • 神并不要求以撒重复亚伯拉罕在埃及同样的失败，而是提醒他「亚 伯拉罕听从我的话」（5 节)，让以撒从亚伯拉罕的经历里学会顺从神。在 救赎的历史上，神允许祂的百姓遭遇许多事，也「作为鉴戒，并且写在经 上，正是警戒我们这末世的人」（林前十 11）。 【创廿六 6】「以撒就住在基拉耳。」 以撒的一生所显明的是一个能承受应许的人。他听了神的话「就住在 基拉耳」，表明一个懂得享用神、享用恩典的人，所该做的就是站稳该站 的地位，其它的事情由神负责，这样就可以活在神的应许里。 【创廿六 7】「那地方的人问到他的妻子，他便说：『那是我的妹子。』 原来他怕说：『是我的妻子』；他心里想：『恐怕这地方的人为利百加的 缘故杀我』，因为她容貌俊美。」 【创廿六 8】「他在那里住了许久。有一天，非利士人的王亚比米勒从 窗户里往外观看，见以撒和他的妻子利百加戏玩。」 以撒和我们一样是普通人，他虽然有神的同在（3 节），也能凭信心顺 服神（6 节），但在环境面前还是免不了惧怕。然而神却让他「在那里住了 许久」（8 节）都平安无事，用事实证明他的惧怕是多余的。以撒这样经历 了神，才能学会完全交托，安息在神的应许里。 的原文相近，是双关语。",
