      sourceTextSnippet: "244 主，随时听主命令。 上图：俄勒冈州立大学收藏的亚伯拉罕井 1910 年的照片，照片中可以 看出，井口的石头已经被井绳磨出了许多很深的痕迹。别是巴遗址附近发 现了 7 口井，2 口大的，5 口小的，历史有几千年，可能是亚伯拉罕和以撒 所挖的，所以被称为亚伯拉罕井。亚伯拉罕和以撒在挖这些井的时候，绝 不会想到这些井在将近三千年以后，在神收回耶路撒冷和应许之地的过程 中起了关键的作用。 【创廿六 25】「以撒就在那里筑了一座坛，求告耶和华的名，并且支 搭帐棚；他的仆人便在那里挖了一口井。」 • 以撒先筑坛并求告耶和华的名，后支搭帐棚和挖井，表明他看重赐 恩典的神过于恩典，这是每一个人对神的话语所当有的正确回应。 • 以撒离开了「宽阔之地」（22 节），在别是巴「支搭帐棚」并挖井， 表明他从此把别是巴当作他的安息之地。不是有恩典的「宽阔之地」才有 安息，而是有神同在的地方才有安息。 上图：在第一次世界大战的别是巴战役（Battle of Beersheba）中，德国司令 统帅的奥斯曼土耳其帝国军队在别是巴修筑战壕抵挡英军埃及远征军。别是巴是 加沙和耶路撒冷的屏障，南面和东面都是沙漠，48 小时路程之内没有水源，只有",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：俄勒冈州立大学收藏的亚伯拉罕井 1910 年的照片，照片中可以 看出，井口的石头已经被井绳磨出了许多很深的痕迹。别是巴遗址附近发 现了 7 口井，2 口大的，5 口小的，历史有几千年，可能是亚伯拉罕和以撒 所挖的，所以被称为亚伯拉罕井。亚伯拉罕和以撒在挖这些井的时候，绝 不会想到这些井在将近三千年以后，在神收回耶路撒冷和应许之地的过程 中起了关键的作用。",
