      sourceTextSource: "pdftotext",
      sourceTextSnippet: "245 别是巴有足够的水井。除非英军能迅速夺取这些水井，否则土耳其人就会毁掉它 们，迫使英军因缺水而撤退。 上图：1917 年 10 月 31 日，英军澳大利亚轻骑兵旅绕道东面，从防守松懈的 沙漠发起了史上最后一次成功的骑兵冲锋。在机关枪的时代，骑兵只是骑马的步 兵，骑马到前线、下马投入战斗。但这些远道而来的骑兵却没有停下来，而是出 人意外地直接发起冲锋，用刺刀当军刀。困惑的土耳其守军甚至都忘了重新设定 步枪标尺，以致大部分子弹都从骑兵们头顶飞过。骑兵们不到一个小时就占领了 别是巴，大部分水井都未被毁坏。虽然别是巴的水井并不足以供应数万英军及其 马匹，但神的手进行了干预，战前 6 天下了雷雨，地上留下了许多水塘，解决了 英军马匹的饮水问题。 上图：2017 年，澳大利亚和以色列联合发行邮票，纪念传奇式的别是巴骑兵 冲锋 100 周年。别是巴战役导致土德联军防线全线崩溃，迫使奥斯曼帝国于 1917 年 12 月 9 日放弃了耶路撒冷。耶路撒冷和圣地从此脱离了奥斯曼帝国 400 年的统 治，由英国托管，奠定了 1948 年以色列复国的基础。别是巴的井在这过程中起了 关键的作用。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：1917 年 10 月 31 日，英军澳大利亚轻骑兵旅绕道东面，从防守松懈的 沙漠发起了史上最后一次成功的骑兵冲锋。在机关枪的时代，骑兵只是骑马的步 兵，骑马到前线、下马投入战斗。但这些远道而来的骑兵却没有停下来，而是出 人意外地直接发起冲锋，用刺刀当军刀。困惑的土耳其守军甚至都忘了重新设定 步枪标尺，以致大部分子弹都从骑兵们头顶飞过。骑兵们不到一个小时就占领了 别是巴，大部分水井都未被毁坏。虽然别是巴的水井并不足以供应数万英军及其 马匹，但神的手进行了干预，战前 6 天下了雷雨，地上留下了许多水塘，解决了 英军马匹的饮水问题。",
