      sourceTextSource: "pdftotext",
      sourceTextSnippet: "247 【创廿六 33】「他就给那井起名叫示巴；因此那城叫做别是巴，直到 今日。」 • 以撒到了别是巴，先筑坛献祭，然后开始挖井（25 节），但到了与 亚比米勒立约的那天才挖成这口宝贵的活水井（32 节）。 字义是「誓言」。「别是巴 字 义是「七倍誓约的井」。从前亚伯拉罕所起的「别是巴」一名可能只是指 井周围的「那地方」（二十一 31），如今以撒把这个名字的范围扩大到「那 城」。从此以撒一直住在别是巴，在这安息之地真正地享用恩典、享用神， 完成了他该显出的见证。 • 亚伯拉罕的一生筑了四座坛（十二 7，8；十三 18；二十二 9），以 撒的一生挖了四口井（二十六 19-20，21，22，25），雅各的一生立了四根 柱子（二十八 18；三十一 45；三十五 14；三十五 20），神借着列祖不同 的人生道路，启示了祂在信心之路上将给我们的带领。 上图：别是巴遗址城门口的公共水井，深 70 米，是在南地已发现最深的水井。 很可能就是以撒所挖的井。古代的中东公共水井一般在村口或城门口，以方便牲",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：别是巴遗址城门口的公共水井，深 70 米，是在南地已发现最深的水井。 很可能就是以撒所挖的井。古代的中东公共水井一般在村口或城门口，以方便牲",
      sourceEvidencePage: 255,
      sourceEvidenceOrigin: "same-page",
