      sourceTextSnippet: "248 口喝水，通常带有一个饮水槽。别是巴遗址位于一条旱溪旁边，旱溪冬天被雨水 充满，夏天水存于地下，因此附近有多个水井。别是巴从主前 4000 年开始就存在 了，现有遗迹是按主前 8 世纪的样式恢复的，外围的泥砖墙是主前 10 世纪开始的， 城内可居住 400 名军人和公务员，农夫们住在城外的村庄里。 【创廿六 34】「以扫四十岁的时候，娶了赫人比利的女儿犹滴，与赫 人以伦的女儿巴实抹为妻。」 【创廿六 35】「她们常使以撒和利百加心里愁烦。」 「以扫四十岁的时候」，就是以撒一百岁的时候（二十五 26）。以扫 娶妻目的可能是为了和迦南人的首领联姻，并没有征求父亲的意见（《犹 太古史记》卷 1 第 18 章 265 节）。他不但娶了祖父和父亲所不喜悦的迦南 妻子（二十四 3；二十八 8），而且还娶了两位，因此以撒和利百加为以扫 及其后代的信仰而「心里愁烦」。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：以撒生平行踪：1、神试验亚伯拉罕，要他带以撒到摩利亚去，献以撒 为燔祭（创二十二 1-20）；2、亚伯拉罕派仆人往拿鹤的城去为他娶回利百加为妻 （创二十四）；3、以撒迁往庇耳拉海莱的附近居住（创二十五 11）；4、以撒去 基拉耳，耶和华使他昌大，与非利士人有冲突后又结盟（创二十六）。",
