      sourceTextSnippet: "254 去的。世人也总是明明自己做错事，却归咎给别人。 • 以扫所重视的不是「长子的名分」，而是「我的福分」。他不是要 属灵的福分，而是要属地的福分。 以扫卖掉了「长子的名分」，也就连带地失去了属地的「福分」。凡 不看重属灵福分的，连属地的福分最后也会落空。「长子的名分 Bekowrah 」和「福分 Berakah 」原文相似，是双关语。 【创廿七 37】「以撒回答以扫说：『我已立他为你的主，使他的弟兄 都给他作仆人，并赐他五谷新酒可以养生。我儿，现在我还能为你做什么 呢？』」 如果以撒没有私下进行祝福、没有偏心地把所有的福气都给一个儿子， 就不会有这样的结果。这正是他的脚「在自己暗设的网罗里缠住了」（诗 九 15）。 下图：美索不 达米亚古城努斯 出土的努斯石版 （Nuzi Teblets）， 已 发 现 5000 多 块，大都是主前 14-15 世纪的法律 和商业文件，印证 了创世记中许多 记录的民俗和法 律背景。其中记 载，长子继承的产 业比其他众子多 一倍。但长子不一 定按出生的先后 为序，而是由父亲 指定。父亲一经指定，就不能更改，特别是在临终床上所定的，更是如此。正式",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "下图：美索不 达米亚古城努斯 出土的努斯石版 （Nuzi Teblets）， 已 发 现 5000 多 块，大都是主前 14-15 世纪的法律 和商业文件，印证 了创世记中许多",
