      sourceTextSnippet: "255 口头遗言具有法律效力，而口授形式的开头，就是「我如今老了，不知道哪一天 死……」（创二十七 2）。 【创廿七 38】「以扫对他父亲说：『父啊，你只有一样可祝的福吗？ 我父啊，求你也为我祝福！』以扫就放声而哭。」 • 以扫两次「放声而哭」，但他既然「贪恋世俗」，「因一点食物把 自己长子的名分卖了。后来想要承受父所祝的福，竟被弃绝，虽然号哭切 求，却得不着门路使他父亲的心意回转」（来十二 16-17）。以扫代表拒绝 神恩典应许的人，雅各代表接受神恩典应许的人。人若为了在世上短暂的 舒适而拒绝福音，等于放弃了属天的长子名分，放弃了「天上诸长子之会」 （来十二 23）中的席位。 • 这里不是说已经重生得救的真信徒会失去救恩，因为以扫只是有「长 子的名分」（二十五 31），还没有真正承受祝福；而真信徒就像已经承受 祝福的雅各，是「那将要承受救恩的人」（来一 14）、「那承受应许的人」 （来六 17），我们「既得了不能震动的国」（来十二 28），就永远也不会 失去。因为基督作为「新约的中保」，负责「叫蒙召之人得着所应许永远 的产业」（来九 15）。 【创廿七 39】「他父亲以撒说：『地上的肥土必为你所住；天上的甘",
