      sourceTextSource: "pdftotext",
      sourceTextSnippet: "260 承受神给亚伯拉罕的应许。正如天然人对宗教的热忱，只是想靠外表的模 仿来讨神的喜悦，实际上毫无功效。 • 此时以实玛利已经去世 14 年，「往以实玛利那里去」就是「往以实 玛利的后代那里去」。 【创廿八 10】「雅各出了别是巴，向哈兰走去；」 【创廿八 11】「到了一个地方，因为太阳落了，就在那里住宿，便拾 起那地方的一块石头枕在头下，在那里躺卧睡了，」 • 雅各离开别是巴时 77 岁，从此开始了 20 年艰苦的寄居生活，此时大 约是主前 1930 年。过去，「雅各为人安静，常住在帐棚里」（二十五 27）， 如今却独自在野外 露宿，席地枕石、孤 寂凄凉。这就是他用 诡计骗取祝福的结 果，也是神对雅各拆 毁的开始。 • 当初亚伯拉 罕的老仆人带了十 匹骆驼、礼物和随从 前往哈兰娶亲（二十 四 10），如今雅各却 孤身一人上路，只带 了一根杖（三十二 10）。可能他担心如 果目标太大，会被以 扫派人在路上暗算 （二十七 42）。 • 别是巴与哈 兰相距 900 多公里， 是一段漫长而艰苦 的旅程。伯特利在别",
