      sourceTextSource: "pdftotext",
      sourceTextSnippet: "261 是巴北方约 120 公里，海拔将近 1000 米，比别是巴高 700 米，大约要走三 天时间。 上图：雅各所走的是南北纵贯迦南中部山地的山脊大道，由别是巴向北，经 过希伯仑、伯特利、示剑。 【创廿八 12】「梦见一个梯子立在地上，梯子的头顶着天，有神的使 者在梯子上，上去下来。」 • 主耶稣启示，这个立地顶天的「梯子」乃是预表基督，「神的使者 上去下来在人子身上」（约一 51）。基督是「到父那里去」的惟一「道路」 （约十四 6），是「神和人中间」惟一的「中保」（提前二 5）。 • 「至高者将地业赐给列邦，将世人分开，就照神的众子的数目立定 万民的疆界」（申三十二 8 七十士译本），「神的使者在梯子上，上去下 来」管理列邦，但神自己却亲自对雅各一人说话，主动来寻找雅各，用恩 典来带领雅各，因为「耶和华的分本是祂的百姓；祂的产业本是雅各」（申 三十二 9）。 • 雅各梦中所见的梯子是天地之间的通道。而古代美索不达米亚各个 城市的塔庙（Ziggurat），就是为城市的守护神提供的下降到城镇的梯子。",
