      sourceTextSource: "pdftotext",
      sourceTextSnippet: "263 我们，直到我们长成基督成熟的身量。 【创廿八 16】「雅各睡醒了，说：『耶和华真在这里，我竟不知道！』」 【创廿八 17】「就惧怕，说：『这地方何等可畏！这不是别的，乃是 神的殿，也是天的门。』」 • 「巴别」的阿卡德文字义是「神的门」（十一 9），造巴别塔的人想 用「塔顶通天」（十一 4）来当作梯子，靠自己的力量打开通向「天的门」。 但只有基督才是「头顶着天」的「梯子」（12 节；约一 51），才是「天的 门」（约十四 6）、「神的殿」（约二 19-21）。 • 雅各还没有领会到，并不是只有这里才是「神的殿」。哪里有神的 同在，哪里就是「神的殿」；哪里能让人遇见神，哪里就是「天的门」。 只有让基督在教会中掌权、在信徒身上活出来，教会才能成为「神的家」 （提前三 15），信徒才能成为「神的殿」（林前三 16），才能让世人在教 会和信徒身上遇见神，看见「神真是在你们中间了」（林前十四 25），借 此向他们开启「天的门」。 • 「惧怕」是雅各被恢复的第一步。过去他敢用诡诈骗取祝福（二十 七 19-20），就是因为「竟不知道」神「真在这里」（16 节），所以没有敬 畏之心。今天许多信徒缺乏敬畏之心，也是因为他们不知道「耶和华真在 这里」（16 节），祂随时在鉴察我们的心思意念。 【创廿八 18】「雅各清早起来，把所枕的石头立作柱子，浇油在上面。」 石柱代表见证和纪念（申二十七 2；赛十九 19），也被当作立约的证",
