      sourceTextSnippet: "265 来解决眼前需要的恩典，却忽略了得着神所应许的基督。 • 神一面给雅各应许，一面又显露雅各的愚昧，让我们看见利百加眼 中看为最好的雅各，在神眼中却是完全相反。雅各在神面前的本相也就是 我们的本相，圣灵也借着雅各把我们的无知和不配显明出来：我们只追求 神的祝福，而不是为了被恢复到神的目的里去；我们追求得神的祝福，却 忽略了得着神自己；我们乐意接受神的祝福，却拒绝接受神的权柄和管理。 • 但神怜悯雅各的无知，祂乐意借着日用的所需来让雅各来经历祂、 认识祂，最后真正能「以耶和华为我的神」（21 节；三十三 20）。神也一 样会满有忍耐、怜悯和恩典地领我们走一条有盼望的路。 • 神启示自己是「亚伯拉罕的神，以撒的神，雅各的神」（出三 6）， 表明祂在这三个人身上做工的原则，也就是在我们身上做工的原则：神要 把我们带回祂面前去作儿子，然后拆毁我们的旧人，叫我们的生命成长到 能彰显神荣耀和权柄的地步，把我们恢复到神起初创造的目的里去。 第 29 章 【创廿九 1】「雅各起行，到了东方人之地，」",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：哈兰传统的蜂巢房（Harran Beehive Houses），这种建筑样式至少有 3000 多年的历史，由粘土砖和土制成。蜂巢的形状可以抵挡炎热、保持凉爽空气，还 可以抵抗地震、暴风和季节性暴雨。",
