      sourceTextSource: "pdftotext",
      sourceTextSnippet: "269 【创廿九 22】「拉班就摆设筵席，请齐了那地方的众人。」 【创廿九 23】「到晚上，拉班将女儿利亚送来给雅各，雅各就与她同 房。」 油灯昏暗，新娘又戴着面纱，雅各可能已有醉意，所以被骗了。雅各 当初利用父亲「眼睛昏花，不能看见」骗取祝福（二十七 1），现在拉班不 但「以其人之道，还治其人之身」，并且理直气壮（26 节），技高一筹。 上图：哈兰蜂巢房的内部。雅各的新房可能就是这种房子。 【创廿九 24】「拉班又将婢女悉帕给女儿利亚作使女。」 【创廿九 25】「到了早晨，雅各一看是利亚，就对拉班说：『你向我 做的是什么事呢？我服事你，不是为拉结吗？你为什么欺哄我呢？』」 • 过去是雅各欺哄父亲和哥哥，现在轮到他被舅舅欺哄。雅各过去欺 哄别人时，并不关心「为什么」，现在却问「你为什么欺哄我呢」。这背 后正是神管教的手，让诡诈的雅各被更诡诈的拉班欺骗，体会诡诈的可憎。 • 神对我们的拆毁，常常是把我们最不喜欢的东西摆在我们周围，祂 不把我们不喜欢的东西挪去，而是让我们自己支取神的恩典去挪去那些在 我们生命中不该有的东西。 • 「雅各一看是利亚」原文是「看哪，是利亚」，表达出雅各的震惊，",
