      sourceTextSource: "pdftotext",
      sourceTextSnippet: "272 主前 14-15 世纪美索不达米亚的努斯文件（Nuzi Texts）证明，当时妻子 若不能生育，可以把婢女送给丈夫作妾，并将婢女生育的子女放在自己名 下。主前 18 世纪的汉谟拉比法典（Code of Hammurabi）也记载了类似的代 孕习俗。 【创三十 5】「辟拉就怀孕，给雅各生了一个儿子。」 【创三十 6】「拉结说：『神伸了我的冤，也听了我的声音，赐我一个 儿子』，因此给他起名叫但（就是伸冤的意思）。」 【创三十 7】「拉结的使女辟拉又怀孕，给雅各生了第二个儿子。」 【创三十 8】「拉结说：『我与我姊姊大大相争，并且得胜』，于是给 他起名叫拿弗他利（就是相争的意思）。」 拉结给辟拉所生的两个孩子取名，代表收养这两个孩子。 【创三十 9】「利亚见自己停了生育，就把使女悉帕给雅各为妾。」 【创三十 10】「利亚的使女悉帕给雅各生了一个儿子。」 【创三十 11】「利亚说：『万幸！』于是给他起名叫迦得（就是万幸 的意思）。」 【创三十 12】「利亚的使女悉帕又给雅各生了第二个儿子。」 【创三十 13】「利亚说：『我有福啊，众女子都要称我是有福的』， 于是给他起名叫亚设（就是有福的意思）。」 【创三十 14】「割麦子的时候，流便往田里去，寻见风茄，拿来给他",
