      sourceTextSource: "pdftotext",
      sourceTextSnippet: "276 上图：雅各羊（Jacob Sheep）是一种珍稀的古老品种，全身有黑白相间的斑 点，有四只角，最接近雅各当初所饲养的羊。根据基因鉴定，雅各羊的原产地是 古代叙利亚，即拉班的家乡哈兰附近。这种羊可能被雅各从哈兰带到迦南地，又 随着雅各下埃及被带到北非，然后从北非被带到西班牙，接着被带到英国，继而 被带到了加拿大，最后于 2016 年被带回以色列。 【创三十 40】「雅各把羊羔分出来，使拉班的羊与这有纹和黑色的羊 相对，把自己的羊另放一处，不叫他和拉班的羊混杂。」 「相对」意思是分开，避免条纹基因被稀释。 【创三十 41】「到羊群肥壮配合的时候，雅各就把枝子插在水沟里， 使羊对着枝子配合。」 【创三十 42】「只是到羊瘦弱配合的时候就不插枝子。这样，瘦弱的 就归拉班，肥壮的就归雅各。」 【创三十 43】「于是雅各极其发大，得了许多的羊群、仆婢、骆驼， 和驴。」 雅各花了六年积蓄了这笔财富（三十一 41），但他已经清楚地知道这 是神的恩典：「祢向仆人所施的一切慈爱和诚实，我一点也不配得」（三 十二 10）。主耶稣说：「你们用什么量器量给人，也必用什么量器量给你 们」（太七 2）。我们是什么样的人，神就用什么样的事来拆毁我们；什么 时候我们在神的面前活得对了，神就把丰富的恩典加在我们身上。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：雅各羊（Jacob Sheep）是一种珍稀的古老品种，全身有黑白相间的斑 点，有四只角，最接近雅各当初所饲养的羊。根据基因鉴定，雅各羊的原产地是 古代叙利亚，即拉班的家乡哈兰附近。这种羊可能被雅各从哈兰带到迦南地，又 随着雅各下埃及被带到北非，然后从北非被带到西班牙，接着被带到英国，继而 被带到了加拿大，最后于 2016 年被带回以色列。",
