      sourceTextSource: "pdftotext",
      sourceTextSnippet: "279 【创卅一 15】「我们不是被他当作外人吗？因为他卖了我们，吞了我 们的价值。」 【创卅一 16】「神从我们父亲所夺出来的一切财物，那就是我们和我 们孩子们的。现今凡神所吩咐你的，你只管去行吧！』」 当时父母要把所收聘礼的一部分作为女儿的嫁妆，作为女儿将来的经 济保障。雅各用 14 年的劳动支付了聘礼，但拉班却没有把 14 年的薪酬拿 出一部分作为女儿的嫁妆，这就相当于把女儿「当作外人」、「卖了」她 们（15 节）。 【创卅一 17】「雅各起来，使他的儿子和妻子都骑上骆驼，」 【创卅一 18】「又带着他在巴旦·亚兰所得的一切牲畜和财物，往迦 南地、他父亲以撒那里去了。」 【创卅一 19】「当时拉班剪羊毛去了，拉结偷了她父亲家中的神像。」 • 「剪羊毛」通常在三月初、母羊生小羊之前一个月进行，这样可以 刺激母羊多吃草，羊毛也可以在夏季重新长出来，好在冬季御寒。牧人将 羊群集中在一个地点剪羊毛，羊毛也在此处加工、染色，并织成布料，剪 完羊毛后会有庆祝的筵席（撒上二十五 4、11、36；撒下十三 23-25）。 • 当时美索不达米亚和迦南人都有许多「家中的神像」（Teraphim）， 代表祖先或家族的守护神，可以用来占卜，也可以作为遗产继承权的凭证。 「拉结偷了她父亲家 中的神像」，很可能 是为了给雅各保留将 来分配拉班遗产的权 利，她认为这是自己 当得的分（14-16 节）， 是爱雅各的表示。 「家 中的神像」是复数， 拉结可能把所有的神 像都偷走了。 上图：一只剪了一 半羊毛的羊。通常在春季羊羔出生之前一个月剪羊毛，这样有助于母羊吃得更多，",
