      sourceTextSource: "pdftotext",
      sourceTextSnippet: "280 并避免在室外生产小羊。 上图：以色列出土的家神（Teraphim），现藏于耶路撒冷圣经之地博物馆（Bible Lands Museum）。 【创卅一 20】「雅各背着亚兰人拉班偷走了，并不告诉他，」 【创卅一 21】「就带着所有的逃跑。他起身过大河，面向基列山行去。」 • 雅各离开别是巴时 77 岁，在拉班家工作了 20 年（38 节），现在已 经 97 岁，此时大约是主前 1910 年。 • 「大河」指幼发拉底河，「基列山」是约旦河东面的一片山脉。雅 各渡过幼发拉底河，向西南逃往应许之地，方向是对的，方法却是错的。 • 在人看来，雅各的不辞而别是可以理解的，否则很可能走不了，但 实际上这是对神的「同在」缺乏信心（3 节）。雅各虽然经历了神 20 年的 「同在」（二十八 15），并且愿意顺服神回去（3 节），但到了关键时刻 还是忍不住动了自己的心计，很不荣耀神地「逃跑」了。他带着诡诈来到 巴旦·亚兰，也带着诡诈离开巴旦·亚兰，但神绝不允许他带着诡诈偷偷 进入应许之地（三十二 3）。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：以色列出土的家神（Teraphim），现藏于耶路撒冷圣经之地博物馆（Bible Lands Museum）。",
