      sourceTextSnippet: "281 上图：从应许之地远眺约旦河谷东面的基列山脉。 【创卅一 22】「到第三日，有人告诉拉班，雅各逃跑了。」 【创卅一 23】「拉班带领他的众弟兄去追赶，追了七日，在基列山就 追上了。」 「基列山」距离巴旦·亚兰大约 600 公里，轻装的骆驼每天可以走 80-100 公里，7 天就可以追上。拉班知道雅各带着牲畜和家眷，羊羔也即将出生， 十天不可能到达基列山，他很可能没有立即出发追赶，而是从容地用了几 天召集「众弟兄」，也就是与拉班结盟的人。 【创卅一 24】「夜间，神到亚兰人拉班那里，在梦中对他说：『你要 小心，不可与雅各说好说歹。』」 神在最后一刻警告拉班，却没有事先阻拦拉班追赶，也没有让拉班找 不到雅各，因为神要借着「拉班追上雅各」（25 节），来对付雅各里面的 诡诈。「说好说歹」原文是「无论是善或恶都不准说」，也就是不可向雅 各说威胁的话（29 节）。 【创卅一 25】「拉班追上雅各。雅各在山上支搭帐棚；拉班和他的众 弟兄也在基列山上支搭帐棚。」 【创卅一 26】「拉班对雅各说：『你做的是什么事呢？你背着我偷走",
