      sourceTextSnippet: "283 上图：贝都因人的「骆驼的驮篓」是安放在骆驼背上的坐鞍，两端有口袋。 【创卅一 35】「拉结对她父亲说：『现在我身上不便，不能在你面前 起来，求我主不要生气。』这样，拉班搜寻神像，竟没有搜出来。」 拉班并没有检查拉结，可能因为没想到女儿竟敢在「身上不便」的时 候把守护神坐在身下，对神像如此不恭敬。神没有让拉班搜出神像，是要 保全拉结的性命（32 节），继续神的计划（三十五 24）。但神绝不放过这 个破口，最后亲自对付他们，要求他们「除掉你们中间的外邦神，也要自 洁」（三十五 2）。 【创卅一 36】「雅各就发怒斥责拉班说：『我有什么过犯，有什么罪 恶，你竟这样火速地追我？」 【创卅一 37】「你摸遍了我一切的家具，你搜出什么来呢？可以放在 你我弟兄面前，叫他们在你我中间辨别辨别。」",
