      sourceTextSource: "pdftotext",
      sourceTextSnippet: "290 所以古希腊人为了表达两个人之间的友谊，常常各自佩戴两个亲和数中的 一个（220 或 284 ）。 雅各在主前 1910 年 就用两份「亲和数」 的礼物送给以扫，难 道是巧合吗？ 上图：220 和 284 是 第 一 对 亲 和 数 （Amicable Pair）。毕 达哥拉斯曾说：「朋友 是你灵魂的倩影，要像 220 与 284 一样亲密」 ， 所以古希腊人为了表 达两个人之间的友谊， 常常各自佩戴两个亲 和数中的一个（220 或 284 ）。 【创卅二 15】「奶崽子的骆驼三十只——各带着崽子，母牛四十只， 公牛十只，母驴二十匹，驴驹十匹；」 雅各一共送出 140 只其它的牲口。140 在数学上称为「婚约数 Betrothed numbers」或「准亲和数 Quasi-amicable Numbers」。「准亲和数」与「亲 和数 」的差别在于，累加所有真因子时不包括 1。140 不包括 1 的真因子 是：2 、4 、5 、7 、10 、14 、20 、28 、35 、70，2 + 4 + 5 + 7 + 10 + 14 + 20 + 28 + 35 + 70 = 195；而 195 不包括 1 的真因子是：3 、5 、13 、15 、 39 、65，3 + 5 + 13 + 15 + 39 + 65 = 140。20 世纪数学家才发现「准亲和数」 的特性，雅各在主前 1910 年就用一份「准亲和数」的礼物送给以扫，难道 又是巧合吗？ 【创卅二 16】「每样各分一群，交在仆人手下，就对仆人说：『你们 要在我前头过去，使群群相离，有空闲的地方』；",
