      sourceTextSource: "pdftotext",
      sourceTextSnippet: "291 你说：“你是哪家的人？要往哪里去？你前头这些是谁的？”」 【创卅二 18】「你就说：“是你仆人雅各的，是送给我主以扫的礼物； 他自己也在我们后边。”』」 【创卅二 19】「又吩咐第二、第三，和一切赶群畜的人说：『你们遇 见以扫的时候也要这样对他说；」 【创卅二 20】「并且你们要说：“你仆人雅各在我们后边。”』因雅 各心里说：『我借着在我前头去的礼物解他的恨，然后再见他的面，或者 他容纳我。』」 雅各在祷告之后，送了如此贵重礼物给他哥哥以扫，并且「使群群相 离，有空闲的地方」（16 节），用一波又一波的礼物去感动哥哥。这表面 上还是雅各在谋算，但实际上他已经把结果交给神了。因为此时如果雅各 对神不放心，完全可以走回头路，藏匿在基列山中，基列地本来就是一个 好牧场（民三十二 1）。这 580 只牲畜 的礼物，比主前 9 世 纪一个城市献给亚述 王的贡物数量还大， 而且以雌性为主，适 合继续繁殖，显出了 很大诚意。若不是雅 各真心认为这些牲畜 是自己「不配得」的 恩典（10 节），「抓」 （二十五 26）了一生 的雅各绝不肯松手送 出这么大方的礼物。 上图：亚述王图库 尔蒂-尼努尔塔二世 （Tukulti-Ninurta II，主",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：亚述王图库 尔蒂-尼努尔塔二世 （Tukulti-Ninurta II，主",
