      sourceTextSource: "pdftotext",
      sourceTextSnippet: "292 前 891-883 年在位）的年鉴石碑，现藏于卢浮宫博物馆。根据记载，美索不达米亚 城市因达努（Hindanu）献给图库尔蒂-尼努尔塔二世的贡物是骆驼 30 只、牛 50 只、驴 30 匹、羊 200 只，以及一他连得没药。相比之下，雅各送给以扫的礼物有 骆驼 60 只、牛 50 只、驴 30 匹，山羊 220 只、绵羊 220 只，数量更大。 【创卅二 21】「于是礼物先过去了；那夜，雅各在队中住宿。」 【创卅二 22】「他夜间起来，带着两个妻子，两个使女，并十一个儿 子，都过了雅博渡口，」 雅各「夜间起来」，表明他无法安睡。他一面相信神的应许（12 节）， 一面对现实中的难处实在是没有把握（6-7 节），辗转难眠，这是每一个信 徒都可能经历的真正内心争战。「雅博」原文意思是「倒空」，雅博河就 是现代的哲卡河（Zarqa River），从约旦高原向西流经基列地，在死海和加 利利湖的中间汇入约旦河。 上图：雅博河就是现代的哲卡河（Zarqa River），从约旦高原向西流经基列地， 在死海和加利利湖的中间汇入约旦河。 【创卅二 23】「先打发他们过河，又打发所有的都过去，」 雅各先打发家人先过河，并不是为了保全自己，因为当他见了以扫时， 是「他自己在他们前头过去」（三十三 3）。他可能是需要一段独处的时间。 【创卅二 24】「只剩下雅各一人。有一个人来和他摔跤，直到黎明。」",
