      sourceTextSource: "pdftotext",
      sourceTextSnippet: "293 这个人是天使（何十二 4），代表神自己（28 节；何十二 3）。这次摔 跤不是雅各找神，而是神主动来找雅各，要除掉他生命成长中的障碍，带 领他认识自己，看见自己的可怜、软弱，彻底向神降服。人不可能靠自己 的努力变得合神心意，只有接受神在我们身上的拆毁，才能「心意更新而 变化」（罗十二 2）。「雅博 Yabboq 原文 的发音都很相似。 上图：雅博河的一个渡口。雅各当年可能就在这种地方与天使摔跤。 【创卅二 25】「那人见自己胜不过他，就将他的大腿窝摸了一把，雅 各的大腿窝正在摔跤的时候就扭了。」 • 神并不是真的「胜不过他」，而是要让雅各认识自己肉体里「大腿 窝」的强大。雅各「与神较力」（何十二 3），「直到黎明」（24 节）都 不倒下，就像他经过神 20 年的对付，经历了那么多的恩典和保守，肉体在 神面前还是不肯完全倒下，心中的诡诈一有机会还是会冒出来。 • 「大腿窝」是一个人力量的所在，每个信徒都有自己特别强的一处 「大腿窝」。当我们对自己的「大腿窝」还觉得满意的时候，就总想依靠",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：雅博河的一个渡口。雅各当年可能就在这种地方与天使摔跤。",
