      sourceTextSource: "pdftotext",
      sourceTextSnippet: "295 他也发现自己过去 20 年所「较力」的对象不是以扫或拉班，而是神自己（何 十二 3）。 • 「毗努伊勒」原文意思是「面对神」。古人认为谁见到了神的面， 谁就不能存活（出三十三 20）。 【创卅二 31】「日头刚出来的时候，雅各经过毗努伊勒，他的大腿就 瘸了。」 • 「雅各经过毗努伊勒，他的大腿就瘸了」，因此「毗努伊勒」成为 雅各生命中的转折点，也是我们每个人属灵生命成长道路上的转折点。 • 「瘸」是人的天然生命被神对付的记号。经过神对付的人，虽然还 可能会靠肉体做事，但一切都是瘸着腿做的。人天然生命中最强的「大腿 窝的筋」（32 节）若被神对付过，一逞强就会感觉到疼，只有疼痛才会使 我们不敢再靠肉体，而是单单倚靠神。 • 雅各的瘸腿成为此次摔跤永远的证据，就像保罗身上的刺，一面证 明那绝非是一场梦，一面永远在提醒他，让他每走一步都知道自己的不行 （林后十二 7-10）。 • 雅各虽然瘸了，但他却成了荣耀的「以色列」（28 节）。神在亚伯 拉罕的身上显明恢复他的地位，在以撒的身上显明恢复他的丰富，在雅各 身上则显明恢复他生命中的荣耀。这样的恢复以后将借着基督在十字架上",
      sourceEvidenceType: "verse_context",
      sourceEvidenceSnippet: "【创卅二 31】「日头刚出来的时候，雅各经过毗努伊勒，他的大腿就 瘸了。」 • 「雅各经过毗努伊勒，他的大腿就瘸了」，因此「毗努伊勒」成为 雅各生命中的转折点，也是我们每个人属灵生命成长道路上的转折点。 • 「瘸」是人的天然生命被神对付的记号。经过神对付的人，虽然还 可能会靠肉体做事，但一切都是瘸着腿做的。人天然生命中最强的「大腿 窝的筋」（32 节）若被神对付过，一逞强就会感觉到疼，只有疼痛才会使 我们不敢再靠肉体，而是单单倚靠神。",
