      sourceTextSource: "pdftotext",
      sourceTextSnippet: "296 的救恩完全成就，把凡是接受基督的人都恢复到神起初的定意里，有神荣 耀的形象。 【创卅二 32】「故此，以色列人不吃大腿窝的筋，直到今日，因为那 人摸了雅各大腿窝的筋。」 「不吃大腿窝的筋」不是摩西律法的规定，但犹太教有此习俗，宰杀 牛羊时要先挑除脚筋。北宋时有犹太人到开封定居至今，自称信奉「一赐 乐业教」，当地居民称之为「挑筋教」。开封犹太会堂的后街在清朝时叫 「挑筋胡同」，现称为「教经胡同」。 上图：开封南教经胡同。开封犹太会堂的后街绕寺而建，清代称挑筋胡同。 冯玉祥主政开封时认为这个名字不雅，改称教经胡同。1937 年将两条东西走向平 行的胡同分称南教经胡同和北教经胡同，现在仍有犹太人后裔在此居住。 上图：开封市区东部的犹太会堂旧址。 第 33 章 【创卅三 1】「雅各举目观看，见以扫来了，后头跟着四百人，他就把 孩子们分开交给利亚、拉结，和两个使女，」 【创卅三 2】「并且叫两个使女和她们的孩子在前头，利亚和她的孩子 在后头，拉结和约瑟在尽后头。」",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：开封南教经胡同。开封犹太会堂的后街绕寺而建，清代称挑筋胡同。 冯玉祥主政开封时认为这个名字不雅，改称教经胡同。1937 年将两条东西走向平 行的胡同分称南教经胡同和北教经胡同，现在仍有犹太人后裔在此居住。",
