      sourceTextSource: "pdftotext",
      sourceTextSnippet: "297 【创卅三 3】「他自己在他们前头过去，一连七次俯伏在地才就近他哥 哥。」 • 以扫带领「四百人」（1 节）远道前来，很可能来者不善。雅各做了 最坏的打算，他勇敢地走在前头，首先承受危险，而安排他最爱的「拉结 和约瑟在尽后头」（2 节），让他们在紧急关头可以逃走。 • 雅各「在他们前头过去」，表明他被神对付到一个地步，已经可以 撇下自己。但在神眼里却还不够，因为一个能撇下自己的人，未必能撇下 自己在地上所爱慕的，雅各还是安排他最爱的「拉结和约瑟在尽后头」。 人若不能撇下，就不能得着：「人为神的国撇下房屋，或是妻子、弟兄、 父母、儿女，没有在今世不得百倍，在来世不得永生的」（路十八 29-30）。 因此，神还要继续拆毁他，继续拿走他最爱的「拉结」（三十五 19-20）和 「约瑟」（三十七 33-34），以致被倒空到一个地步，明白「除祢以外，在 地上我也没有所爱慕的」（诗七十三 25）。 • 根据主前 15 世纪的阿马尔奈文书（Amarna Letters）的记载 ，「一 连七次俯伏在地」是当时的诸侯朝见法老的大礼。雅各这种谦卑恭敬的态 度与 20 年前以撒的 祝福完全相反（二十 七 29）。 下图：埃及阿马尔 奈 文 书 （ Amarna letters）是一批刻在泥 板上的书信，以楔形文 字写成，大部分是主前 16-11 世纪古埃及新王 国时期的外交书信。其 中 一 些信 中 多 次 提 到 诸侯「七次又七次地用 背和胃向法老俯伏」。 【创卅三 4】「以扫跑来迎接他，将他抱住，又搂着他的颈项，与他亲",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "下图：埃及阿马尔 奈 文 书 （ Amarna letters）是一批刻在泥 板上的书信，以楔形文 字写成，大部分是主前 16-11 世纪古埃及新王 国时期的外交书信。其 中 一 些信 中 多 次 提 到 诸侯「七次又七次地用",
