      storedAbsolutePath: "/Users/simon/OHB/Resources/01_创世记/文档图片内容提取_20260515_121143/CMC-01_副本/p307_img166_720x464.png",
      sourceTextSource: "pdftotext",
      sourceTextSnippet: "299 【创卅三 13】「雅各对他说：『我主知道孩子们年幼娇嫩，牛羊也正 在乳养的时候，若是催赶一天，群畜都必死了。」 当时雅各的大儿子流便大约 13 岁，小儿子约瑟 6 岁。此时刚过了剪羊 毛的季节（三十一 19），春天的牛犊、羊羔刚出生不久，不能「催赶」。 同样，我们也应当顾念、体谅肢体的软弱，在一切属灵的追求上，都不能 以自己作标准来要求别人，而应当量着各人生命的程度「慢慢地前行」（14 节）。「我们到了什么地步，就当照着什么地步行」（腓三 16），若是生 命的程度还没有到、神工作的时间还没有到，人为的「催赶」只会欲速而 不达。 【创卅三 14】「求我主在仆人前头走，我要量着在我面前群畜和孩子 的力量慢慢地前行，直走到西珥我主那里。』」 雅各并没有直接去西珥，而是前往「疏割」休整（17 节）。「直走到 西珥我主那里」，并不是说直接把群畜和孩子一直带到西珥，而是中东人 的客气话，表示将来把一切都安顿好了以后，再去拜会以扫。后来以扫和 雅各一起埋葬了父亲以撒（三十五 29），表明他们确实再次见面并和好了， 并非雅各的诡诈。 上图：一位贝都因牧羊人在以色列南地放羊。 【创卅三 15】「以扫说：『容我把跟随我的人留几个在你这里。』雅 各说：『何必呢？只要在我主眼前蒙恩就是了。』」",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：一位贝都因牧羊人在以色列南地放羊。",
