      storedAbsolutePath: "/Users/simon/OHB/Resources/01_创世记/文档图片内容提取_20260515_121143/CMC-01_副本/p308_img167_499x395.png",
      sourceTextSource: "pdftotext",
      sourceTextSnippet: "300 旷野并不安全，雅各婉拒以扫的保护，可能因为他完全相信「神的军 兵」（三十二 2）会保护他们，而不是害怕被监视。「只要在我主眼前蒙恩」 意思是雅各希望哥哥以扫再次施恩，谅解自己的拒绝理由。 【创卅三 16】「于是，以扫当日起行，回往西珥去了。」 【创卅三 17】「雅各就往疏割去，在那里为自己盖造房屋，又为牲畜 搭棚；因此那地方名叫疏割（就是棚的意思）。」 • 「疏割」就在毗努伊勒附近，是约旦河东靠近雅博河汇入约旦河的 地方，有许多草场。「疏割」原文的意思是「棚」，表明他们在此停留的 重点是「为牲畜搭棚」，这个季节有许多刚出生不久的牛羊，「正在乳养 的时候」（13 节），因此需要在水草丰富的地方休整几个月。「盖造房屋」 可能只是简易房。 • 神早已应许「我必与你同在」（三十一 3），雅各本可以放心跟随， 「因为祂说有，就有，命立，就立」（诗三十三 9），但因着亚当后裔的本 性，一路才出现那么多的人的打岔和挣扎，直到现在才能放松。神是用话 语做工的神，虽然我们不知道神在细节上会怎么带领我们，但「众位可以 放心，我信神祂怎样对我说，事情也要怎样成就」（徒二十七 25）。 • 感谢神！祂「怜恤敬畏祂的人」（诗一百零三 13），「因为祂知道 我们的本体，思念我们不过是尘土」（诗一百零三 14），所以神一面用话 语做工，一面也会用「玛哈 念」（三十二 2）和「毗努伊 勒」（三十二 30）的经历来 安慰我们、坚固我们的信心。 上图：雅各在约旦河附近 的疏割休整一段时间以后，就 渡过约旦河进入迦南，来到迦 南地中央的示剑。",
