      sourceTextSource: "pdftotext",
      sourceTextSnippet: "302 【创卅三 20】「在那里筑了一座坛，起名叫伊利·伊罗伊·以色列（就 是神、以色列神的意思）。」 「伊利·伊罗伊·以色列 」原文意思是「以色列全能的 神」。雅各「平平安安地到了迦南地」（18 节），所以他实践自己所承诺 的「我必以耶和华为我的神」（二十八 21），正式承认「以撒所敬畏的神、 亚伯拉罕的神」（三十一 42）就是「以色列全能的神」。 • 经过了神 20 年的对付，雅各的灵性已经有了很大的长进，也像亚伯 拉罕在示剑「筑了一座坛」（十二 7），并且公开宣告神是「以色列的神」。 但在里面，雅各还没有完全接受神做他的神。他没有继续照着神的心意前 往伯特利（三十五 1），而是在示剑城买地定居（19 节），表明他还是活 在自己里面，「因为你的财宝在哪里，你的心也在那里」（太六 19）。所 以神就任凭他停留在示剑城，更深地被拆毁。 第 34 章 【创卅四 1】「利亚给雅各所生的女儿底拿出去，要见那地的女子们。」 • 「出去」暗示底拿离开父母的保护和管教。「要见那地的女子们」 可能是想看看当地女子的装扮（《犹太古史记》卷 1 第 21 章 337 节），见 识一下世界。 • 底拿离开巴旦·亚兰时可能只有六、七岁（三十 21），现在可能已",
