      sourceEvidenceSnippet: "【创卅三 20】「在那里筑了一座坛，起名叫伊利·伊罗伊·以色列（就 是神、以色列神的意思）。」 「伊利·伊罗伊·以色列 」原文意思是「以色列全能的 神」。雅各「平平安安地到了迦南地」（18 节），所以他实践自己所承诺 的「我必以耶和华为我的神」（二十八 21），正式承认「以撒所敬畏的神、 亚伯拉罕的神」（三十一 42）就是「以色列全能的神」。",
