      sourceTextSource: "pdftotext",
      sourceTextSnippet: "303 经十四、五岁，因此本章的悲剧可能是雅各在示剑停留了几年之后发生的。 雅各进入应许之地后 没有直接去伯特利， 而是停留在示剑城买 地定居（三十三 19）， 现在即将为这个停留 付出惨痛的代价。 上 图 ： 主 前 1400-1200 年 迦 南 女 子 的项链，中间的金坠上 刻的神像是埃及爱神哈 索尔（Hathor）。现藏 与耶路撒冷的以色列博 物馆（ Israel Museum）。 【创卅四 2】「那 地的主——希未人、 哈抹的儿子示剑看见她，就拉住她，与她行淫，玷辱她。」 底拿想出去「见」世面（1 节），不料却被世界「看见」了。信徒固然 不能把儿女养在温室里，但如果不能帮助儿女与神建立正常的关系，让儿 女「出去」（1 节）的结果必然是被世界「拉住」。「那地的主」指酋长之 类的领袖人物。「希未人」是迦南的后代（十 17），散住在迦南地（出三 8）。 【创卅四 3】「示剑的心系恋雅各的女儿底拿，喜爱这女子，甜言蜜语 地安慰她。」 【创卅四 4】「示剑对他父亲哈抹说：『求你为我聘这女子为妻。』」 本节原文是「给我聘这女子为妻」，并没有「求」字，表明示剑已经 被父亲宠坏了。 【创卅四 5】「雅各听见示剑玷污了他的女儿底拿。那时他的儿子们正 和群畜在田野，雅各就闭口不言，等他们回来。」",
      sourceEvidenceType: "verse_context",
      sourceEvidenceSnippet: "【创卅四 2】「那 地的主——希未人、 哈抹的儿子示剑看见她，就拉住她，与她行淫，玷辱她。」 底拿想出去「见」世面（1 节），不料却被世界「看见」了。信徒固然 不能把儿女养在温室里，但如果不能帮助儿女与神建立正常的关系，让儿 女「出去」（1 节）的结果必然是被世界「拉住」。「那地的主」指酋长之 类的领袖人物。「希未人」是迦南的后代（十 17），散住在迦南地（出三 8）。",
