      sourceTextSource: "pdftotext",
      sourceTextSnippet: "306 上图：示剑城遗址 Tell Balata，已有 5000 多年历史。 【创卅四 21】「『这些人与我们和睦，不如许他们在这地居住，做买 卖；这地也宽阔，足可容下他们。我们可以娶他们的女儿为妻，也可以把 我们的女儿嫁给他们。」 【创卅四 22】「惟有一件事我们必须做，他们才肯应允和我们同住， 成为一样的人民：就是我们中间所有的男丁都要受割礼，和他们一样。」 【创卅四 23】「他们的群畜、货财，和一切的牲口岂不都归我们吗？ 只要依从他们，他们就与我们同住。』」 示剑城居民的真实目的，是要同化「以色列家」（7 节），把他们连人 带财一起夺去。在历史上，世界有时掺杂一大堆形式上「受割礼」的假信 徒进入教会，有时则打着博爱包容的旗号邀请教会与他们「同住」，目的 都是为了同化教会、掳掠教会，夺走我们「更美长存的家业」（来十 34）。 【创卅四 24】「凡从城门出入的人就都听从哈抹和他儿子示剑的话； 于是凡从城门出入的男丁都受了割礼。」 迦南地有许多民族都行割礼，用于成人仪式、丰饶崇拜、结婚仪式等， 所以示剑居民对割礼并不觉得奇怪。雅各的财富是吸引示剑居民受割礼的 主要原因。",
