      sourceTextSnippet: "310 四周的人。 • 「外邦 人的神像」可 能包括拉结偷 窃的拉班家的 神像（三十一 19）和雅各众 子在示剑城掳 掠的神像（三 十四 29）。我 们若在「示剑 城」停留久了， 许多人、事、 物就会不知不 觉在我们心中 成为取代真神 的偶像，这时 神就会兴起环 境来显明我们里面隐藏的偶像。 • 「耳朵上的环子」可能刻着偶像或与偶像有关的图案，甚至就是护 身符（何二 13）， 连耳环都除掉， 是对偶像彻底的 对付。今天许多 信徒佩戴的首饰 和家中装饰品上 面的艺术形象， 也都是来自异教 的神话传说。 上图：主前",
