      sourceTextSource: "pdftotext",
      sourceTextSnippet: "311 7-6 世纪的腓尼基耳环。上面的双头鹰形象是模仿古埃及爱神哈索尔（Hathor）的 宽领子。 上图：示剑东面 Mount Kabir 山上的橡树。橡树茂密（结六 13）、坚固（摩二 9），常被作为当地的地标（创十二 6；十三 18；三十五 8；书十九 33；撒上十 3） 。 迦南人常在橡树下敬拜偶像（赛五十七 5；何四 13）。 【创卅五 5】「他们便起行前往。神使那周围城邑的人都甚惊惧，就不 追赶雅各的众子了。」 人若拣选神的道路，除掉一切偶像（4 节），神就负人一切的责任，「使 （三十一 3）。 那周围城邑的人都甚惊惧」，因为神自己应许「我必与你同在」 人若选自己的道路，靠自己的血气和「刀剑」（三十四 25），只能等着「我 和全家的人都必灭绝」（三十四 30）。 【创卅五 6】「于是雅各和一切与他同在的人到了迦南地的路斯，就是 伯特利。」 【创卅五 7】「他在那里筑了一座坛，就给那地方起名叫伊勒·伯特利 （就是伯特利之神的意思）；因为他逃避他哥哥的时候，神在那里向他显 现。」 「伯特利」原文字义是「神的家」。雅各在示剑称神是「以色列的神」 （三十三 20），现在称神是「伯特利之神」，表明现在神不只是他个人的 神，更是这个属灵团体的神，是「神的家的神」。 上图：19 世纪的伯特利遗址（现名 Beitin）照片。",
