      sourceTextSnippet: "314 上图：伯利恒（以法他），位于耶路撒冷南方约 8 公里，希伯伦东北约 22 公 里，海拔 880 米。城郊的土壤肥沃，出产丰富，是主耶稣出生的地方。主后 388 年，早期教父耶柔米定居于伯利恒，在这里完成了著名的武加大（Vulgate）拉丁 文圣经译本。 【创卅五 20】「雅各在她的坟上立了一统碑，就是拉结的墓碑，到今 日还在。」 「一统碑」意思是一块记念的石柱。「今日」就是摩西写摩西五经的 时候。雅各的一生立了四根柱子： 1. 第一根：见证神的应许（二十八 18）。 2. 第二根：脱离巴旦·亚兰（三十一 45）。 3. 第三根：真正接受神为自己的神（三十五 14）。 4. 第四根：告别自己在地上的最爱（三十五 20）。 下图：拉结墓（Rachel’s Tomb），位于在伯利恆以北约两公里处公路的右侧， 从主后 4 世纪开始用来纪念拉结，但不一定是真实地点。目前的建筑始于奥斯曼 帝国时期，1841 年重修。",
