      sourceTextSnippet: "315 【创卅五 21】「以色列起行前往，在以得台那边支搭帐棚。」 「以得台」字义是「羊群之塔」，可能在伯利恒南方，地点不详。 【创卅五 22】「以色列住在那地的时候，流便去与他父亲的妾辟拉同 寝，以色列也听见了。雅各共有十二个儿子。」 • 流便与「拉结的使女辟拉」（三十 7）同寝，可能是为了阻止她取代 拉结，也可能是为了夺取家中的领导地位，结果失去了长子的名分（代上 五 1）。古时外邦人承受父亲产业的长子也可拥有父亲的妾（撒下十六 22； 王上二 22），这种乱伦行为被摩西律法所禁止（利十八 8-9；申二十二 30）。 • 这事是雅各从前在家中忽略属灵见证的后果。借着这事，雅各「力 量强壮的时候生的，本当大有尊荣，权力超众」（四十九 3）的长子也被神 取走了。 【创卅五 23】「利亚所生的是雅各的长子流便，还有西缅、利未、犹 大、以萨迦、西布伦。」 【创卅五 24】「拉结所生的是约瑟、便雅悯。」 【创卅五 25】「拉结的使女辟拉所生的是但、拿弗他利。」 【创卅五 26】「利亚的使女悉帕所生的是迦得、亚设。这是雅各在巴",
