      sourceTextSource: "pdftotext",
      sourceTextSnippet: "316 旦·亚兰所生的儿子。」 • 虽然神取走了拉结，但应允了她「愿耶和华再增添我一个儿子」（三 十 24）的祷告，完整的以色列十二支派在神的拆毁中被建立了。 • 在圣经中，「十二」成为代表神的百姓以色列整体的象征数目，旧 约有十二支派，新约有十二使徒（启二十一 12、14）。 • 「在巴旦·亚兰所生的儿子」是概说，因为便雅悯是在迦南地出生 的（18 节）。 【创卅五 27】「雅各来到他父亲以撒那里，到了基列·亚巴的幔利， 乃是亚伯拉罕和以撒寄居的地方；基列·亚巴就是希伯仑。」 • 「希伯仑」是亚伯拉罕、以撒晚年居住的地方，是大卫作王之地， 是神显明祂的荣耀和权柄的地方，也是雅各应当承受父亲产业的地方。 • 神的拆毁是为了充满，祂拿掉我们里面不该有的东西，把地位腾出来， 是要用祂自己来充满。从巴旦·亚兰到希伯仑的一路上，神拿掉了雅各的 力量（三十二 31），拿掉了他的自爱（三十三 3），拿掉了他的安居生活 （ 三 十 三 19 ） ， 拿 掉 了他在迦南 人中的好名 声（三十四 30 ） ， 拿 掉 了他全家的 偶像（三十五 2），拿掉了 最安慰他的 奶母（8 节）， 拿掉了他最 心爱的妻子 （19 节）， 拿掉了他最 倚重的长子",
