      sourceTextSnippet: "321 【创卅六 25】「亚拿的儿子是底顺；亚拿的女儿是阿何利巴玛。」 这位何利人祭便的儿子亚拿的女儿叫「阿何利巴玛」，希末人祭便的 儿子亚拿的女儿也叫「阿何利巴玛」（2 节）。当时的人祖孙三代同名同姓 很普遍，所以需要记录地名、事迹作为区别，可能因此插叙了亚拿的事迹 （24 节）。 【创卅六 26】「底顺的儿子是欣但、伊是班、益兰、基兰。」 【创卅六 27】「以察的儿子是辟罕、撒番、亚干。」",
