      sourceTextSource: "pdftotext",
      sourceTextSnippet: "322 【创卅六 28】「底珊的儿子是乌斯、亚兰。」 【创卅六 29】「从何利人所出的族长记在下面：就是罗坍族长、朔巴 族长、祭便族长、亚拿族长、」 【创卅六 30】「底顺族长、以察族长、底珊族长。这是从何利人所出 的族长，都在西珥地，按着宗族作族长。」 何利人的 7 族可能后来被以扫的子孙征服，并借着通婚被以扫的后代 同化了（申二 12）。 【创卅六 31】「以色列人未有君王治理以先，在以东地作王的记在下 面。」 • 神早已应许雅各「将来有一族和多国的民从你而生，又有君王从你 而出」（三十五 11），但在「以色列人未有君王治理以先」，以东人却先 作王了。 • 31-39 节列举了 8 位以东王，但并未提到任何一位的儿子，而其中三 位还提到他们不同的京城，可见他们的王位不是世袭的，而是强者为王。 上图：以东地在南国犹大和死海的南部。 【创卅六 32】「比珥的儿子比拉在以东作王，他的京城名叫亭哈巴。」 【创卅六 33】「比拉死了，波斯拉人谢拉的儿子约巴接续他作王。」 上图：波斯拉（Bozrah）三面悬崖，地势险要，防守坚固，控制从以旬迦别来",
