      sourceTextSource: "pdftotext",
      sourceTextSnippet: "328 在示剑附近会遭到报复（三十四 30）。示剑在希伯仑以北约 117 公里，要 走 3 天的路程。 【创卅七 15】 「有人遇见他在田野走迷了路，就问他说： 『你找什么？』」 【创卅七 16】「他说：『我找我的哥哥们，求你告诉我，他们在何处 放羊。』」 【创卅七 17】「那人说：『他们已经走了，我听见他们说要往多坍去。』 约瑟就去追赶他哥哥们，遇见他们在多坍。」 当时迦南地人口并不稠密，所以游牧者可以自由放牧，过了几个世纪 就行不通了。「多坍」字义是「双井」，位于示剑以北约 22 公里，需要再 走一天，当地水草茂盛，至今仍是好牧场。 上图：多坍谷的牧羊人。摄于 1979 年。 【创卅七 18】「他们远远地看见他，趁他还没有走到跟前，大家就同 谋要害死他。」 约瑟被父亲差去看望哥哥们，不料他们竟要「同谋要害死他」。这正 像主耶稣基督被父神差到祂的弟兄中间（来二 17），结果也是被人所害（太 二十一 38）。 【创卅七 19】「彼此说：『你看，那做梦的来了。」",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：多坍谷的牧羊人。摄于 1979 年。",
