      sourceTextSource: "pdftotext",
      sourceTextSnippet: "330 约瑟被「犹大」提议出卖，后来主耶稣也被另一位「犹大」出卖了（太 二十六 14-16）。 【创卅七 28】「有些米甸的商人，从那里经过，哥哥们就把约瑟从坑 里拉上来，讲定二十舍客勒银子，把约瑟卖给以实玛利人；他们就把约瑟 带到埃及去了。」 • 约瑟在多坍「哀求」哥哥们，被冷酷拒绝（四十二 21）；以利沙的 仆人却在多坍「看见满山有火车火马围绕以利沙」（王下六 17）。无论是 顺境里的「多坍」还是逆境里的「多坍」，神始终在那里掌权，在祂的隐 密处眷顾保守祂所拣选的人。 • 主前 18 世纪的汉谟拉比法典记载，当时一个男奴隶的价格是三十舍 客勒银子，女奴隶是二十舍客勒银子。「二十舍客勒银子」也是牧羊人工 作三年的工资，是律法规定五岁到二十岁男子的价银（利二十七 5）。主耶 稣被祂的门徒出卖，价银是三十块钱（太二十六 14-16）。 上图：多坍谷位于示剑以北约 22 公里，希伯仑以北约 140 公里，位于迦密山 和基利心山之间的平原，水草茂盛，至今仍是良好的牧场。多坍遗址（Tell Dothan） 始建于主前 3000 年，是基列经伯善前往埃及的商道上的一个重要站点，所以米甸 商队会经过这里。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：多坍谷位于示剑以北约 22 公里，希伯仑以北约 140 公里，位于迦密山 和基利心山之间的平原，水草茂盛，至今仍是良好的牧场。多坍遗址（Tell Dothan） 始建于主前 3000 年，是基列经伯善前往埃及的商道上的一个重要站点，所以米甸 商队会经过这里。",
