      sourceTextSource: "pdftotext",
      sourceTextSnippet: "331 【创卅七 29】「流便回到坑边，见约瑟不在坑里，就撕裂衣服。」 出卖约瑟时流便不在场，可能负责轮班照看羊群。 上图：从北面看约瑟坑（Joseph’s pit or Joseph’s well）。 【创卅七 30】「回到兄弟们那里，说：『童子没有了，我往那里去才 好呢？』」 【创卅七 31】「他们宰了一只公山羊，把约瑟的那件彩衣染了血，」 【创卅七 32】「打发人送到他们的父亲那里说：『我们捡了这个；请 认一认，是你儿子的外衣不是？』」 • 雅各过去用山羊羔的肉和皮欺骗他的父亲（二十七 9、16），如今被 儿子们用山羊的血所欺骗；雅各「打发」约瑟去看望儿子们（13 节），而 他的儿子们却「打发」人送血衣给他看。依靠属世的智慧行诡诈的人，必 然会面临生活无情的讽刺。 • 「你儿子」是冷酷的表达方式，连提名字都不屑（路十五 30）。 【创卅七 33】「他认得，就说：『这是我儿子的外衣，有恶兽把他吃 了，约瑟被撕碎了！撕碎了！』」 表面上是雅各以为约瑟「被撕碎了」，实际上是雅各的心「被撕碎了」， 他这个人被神破碎了。 【创卅七 34】「雅各便撕裂衣服，腰间围上麻布，为他儿子悲哀了多 日。」 「麻布」是一种用黑山羊毛织成的粗布，被用做丧服。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：从北面看约瑟坑（Joseph’s pit or Joseph’s well）。",
      sourceEvidencePage: 339,
      sourceEvidenceOrigin: "same-page",
