      sourceTextSource: "pdftotext",
      sourceTextSnippet: "332 【创卅七 35】「他的儿女都起来安慰他，他却不肯受安慰，说：『我 必悲哀着下阴间，到我儿子那里。』约瑟的父亲就为他哀哭。」 「阴间」是人死后灵魂暂时停留，等候末日受神审判的地方（徒二 27， 31）。它分成两部分，一部分收留义人的灵魂，又称乐园（路二十三 43）； 另部分收留罪人的灵魂（伯二十四 19），中间有深渊相隔，可望而不可及 （路十六 19-31）。「女儿」是复数，可能包括媳妇。 【创卅七 36】「米甸人带约瑟到埃及，把他卖给法老的内臣——护卫 长波提乏。」 神早已向亚 伯拉罕宣告要把 他的后裔带到外 邦之地，直到亚 摩利人罪恶满盈 之 时 （ 十 五 13-16），现在从 约瑟开始应验 了。「护卫长」 意思是「禁卫军 统领」。「波提 乏」是在主前 2100-1600 年典型 的埃及名字。此 时大约是主前 1899 年，埃及正 处于第十二王朝 期 间 （ 主 前 1991-1802 年）， 阿蒙涅姆赫特二 世 法 老 （Amenemhat II，",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：古埃及第十二王朝法老阿蒙涅姆赫特二世（Amenemhat II）坐像，现藏 于柏林 Pergamon 博物馆。主前 1899 年，约瑟被卖到埃及，埃及正处于第十二王 朝期间（主前 1991-1802 年），阿蒙涅姆赫特二世于主前 1929-1895 年在位当政。",
      sourceEvidencePage: 341,
      sourceEvidenceOrigin: "next-page",
      captionRiskFlags: ["caption-boundary-truncated","caption-from-next-page"],
