      sourceTextSource: "pdftotext",
      sourceTextSnippet: "335 上图：犹大离开希伯仑后， 在亚杜兰、基悉、亭拿一带生活。 【创卅八 13】「有人告诉 她玛说：『你的公公上亭拿剪 羊毛去了。』」 【创卅八 14】「她玛见示 拉已经长大，还没有娶她为 妻，就脱了她作寡妇的衣裳， 用帕子蒙着脸，又遮住身体， 坐在亭拿路上的伊拿印城门 口。」 【创卅八 15】「犹大看见 她，以为是妓女，因为她蒙着 脸。」 • 她玛显然了解犹大不是一个敬畏神的人。如果犹大像约瑟那样害怕 「得罪神」（三十九 9），她玛的计谋就不能成功。但犹大并不敬畏神，他 连弟弟都能卖掉，在道德上更是毫无底线。 • 「作寡妇的衣裳」古代的寡妇有特别的装饰表明身份。当时的寡妇 和已婚妇女都不蒙脸，而妓女会像新娘一样「用帕子蒙着脸」。 【创卅八 16】「犹大就转到她那里去说：『来吧！让我与你同寝。』 他原不知道是他的儿妇。她玛说：『你要与我同寝，把什么给我呢？』」 【创卅八 17】「犹大说：『我从羊群里取一只山羊羔打发人送来给你。』 她玛说：『在未送以先，你愿意给我一个当头吗？』」 「当头」就是「抵押品」。 【创卅八 18】「他说：『我给你什么当头呢？』她玛说：『你的印、 你的带子，和你手里的杖。』犹大就给了她，与她同寝，她就从犹大怀了 孕。」 「印」是个人的图章，「带子」用于把印挂在脖子，「杖」是牧羊人 的工具，有身分的人杖上刻着独特的花纹，可以作为信物。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：犹大离开希伯仑后， 在亚杜兰、基悉、亭拿一带生活。",
