      sourceTextSource: "pdftotext",
      sourceTextSnippet: "336 上图：主前 8-6 世纪的印， 可以用带子穿起来。现藏于以 色列博物馆。 【创卅八 19】「她玛起 来走了，除去帕子，仍旧穿 上作寡妇的衣裳。」 【创卅八 20】「犹大托 他朋友亚杜兰人送一只山 羊羔去，要从那女人手里取 回当头来，却找不着她，」 【创卅八 21】「就问那地方的人说：『伊拿印路旁的妓女在那里？』 他们说：『这里并没有妓女。』」 【创卅八 22】「他回去见犹大说：『我没有找着他，并且那地方的人 说：“这里没有妓女。”』」 15 节的「妓女 zanah」原文有「行淫 」的意思，指普通的妓女。光顾 普通的妓女，即使在迦南人中间也是不光彩的行为。而 21-22 节的「妓女 qĕdeshah」原文是「庙妓」，迦南人在敬拜偶像的仪式上与「庙妓」行淫， 不但不以为耻，反而认为是虔诚的宗教行为。犹大让他的朋友去找「庙妓」 而不是「妓女」，目的是为了掩饰自己的不光彩行为，其实他的道德水平 连迦南人都不如了。 【创卅八 23】「犹大说：『我把这山羊羔送去了，你竟找不着她，任 凭她拿去吧，免得我们被羞辱。』」 「免得我们被羞辱」，是因为担心四处寻找妓女的过程中，会使犹大 的名誉受损。凡是不敬畏神的人，也都是只看重在人面前的名声，却不顾 自己在神面前的良心。 【创卅八 24】「约过了三个月，有人告诉犹大说：『你的儿妇她玛作 了妓女，且因行淫有了身孕。』犹大说：『拉出她来，把她烧了。』」 • 才「过了三个月」，犹大不但忘了自己曾经「行淫」，还自以为义",
