      sourceTextSnippet: "337 地要惩罚儿媳妇的「行淫」。世人不是不知道罪和公义，而是采取双重标 准：以公义挑剔别人，以慈爱宽容自己。但神的标准却是：「你们用什么 量器量给人，也必用什么量器量给你们」（太七 2），「你在什么事上论断 人，就在什么事上定自己的罪」（罗二 1）。 • 犹大灵性的下坡路从「离开他弟兄下去」开始，到本节已经下到最 低点。一旦他到迦南人中生活（1 节），很快就与迦南人通婚（2 节），接 着下一代就开始作恶（7、10 节），自己也变得口是心非（11 节），失去 了道德底线（16 节）；但另一面， 他又竭力地掩饰自己的罪 （20-21 节），维持自己在人面 前的名誉（23 节），还假冒为善 地伸张正义（24 节）。 【创卅八 25】「她玛被拉出 来的时候便打发人去见她公公， 对他说：『这些东西是谁的，我 就是从谁怀的孕。请你认一认， 这印和带子并杖，都是谁的？』」 上图：英国犹太教大拉比 Solomon Hirschell（1802-1842 年任 职）的印。 【创卅八 26】「犹大承认说：『她比我更有义，因为我没有将她给我 的儿子示拉。』从此犹大不再与她同寝了。」 • 「她比我更有义」并不是说她玛没有罪，而是说相比之下，比犹大 好得多。神借着这样难堪的事实，逼着自以为义、好面子的犹大不得不公 开认罪，承认自己的不义，这就成了犹大灵性的转机。「不再与她同寝」 表明犹大真心悔恨，痛改前非，结果就在众兄弟之中承当起了长子的责任 （四十四 33）。 • 我们在亚当的天性里，也总是和犹大一样站在自以为义的地位上， 用真理去审判自己以外的人、事、物。直到圣灵借着十字架来对付我们、",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：英国犹太教大拉比 Solomon Hirschell（1802-1842 年任 职）的印。",
