      sourceTextSource: "pdftotext",
      sourceTextSnippet: "339 第 39 章 【创卅九 1】「约瑟被带下埃及去。有一个埃及人，是法老的内臣—— 护卫长波提乏，从那些带下他来的以实玛利人手下买了他去。」 埃及买奴隶的人那么多，偏偏就是「法老的内臣——护卫长波提乏」 把约瑟买去，这完全是神的安排。「约瑟被带下埃及去」的「下」，与「犹 大离开他弟兄下去」（三十八 1）的「下」原文是同一个字。这两个对比鲜 明的「下」的背后，都是神的手在管理。神在任凭犹大主动地「下」到迦 南人中间，经过堕落而悔改的同时，又安排约瑟被动地「下」到埃及，经 过降卑而高升，目的都是要把神百姓的历史领向祂所定意的方向。 （The Via Maris） 上图：古代大马士革和与埃及之间的商道，紫色是「沿海的路」 ， 红色是「王道」（The King’s Highway）。约瑟被卖到埃及走的是「沿海的路」（赛 九 1），以色列人出埃及进迦南最后一段走的是「王道」（民二十 17；二十一 22） 。 贸易是古代中东各大文化的重要部分，商旅根据各地的地形、政治状况和潜在市 场长期走出的路线称为贸易商道（Trade Routes），商道沿线的城市为商人们提供",
