      sourceTextSnippet: "342 上图：古埃及下层男人的服装，上身赤裸，下身只有一件白色亚麻的 缠腰布（Loincloth）。由于气候炎热潮湿，古代埃及人穿得很少，主要服装 材料是亚麻布，原料并不充足，所以古埃及人的服装属于贵重物品，只有 上层人士才能穿凉鞋。古王国时期的缠腰布长度一般在膝盖以上，中王国 时期缠腰布变长。 【创卅九 13】「妇人看见约瑟把衣裳丢在她手里跑出去了，」 【创卅九 14】「就叫了家里的人来，对他们说：『你们看！他带了一 个希伯来人进入我们家里，要戏弄我们。他到我这里来，要与我同寝，我 就大声喊叫。」 「希伯来人」这个称呼既是表示轻蔑（四十三 32），又是为了激起那 些嫉妒约瑟被重用的仆人的仇恨。「家里的人」指家中其他的仆人。 【创卅九 15】「他听见我放声喊起来，就把衣裳丢在我这里，跑到外 边去了。』」 【创卅九 16】「妇人把约瑟的衣裳放在自己那里，等着他主人回家，」 【创卅九 17】「就对他如此如此说：『你所带到我们这里的那希伯来 仆人进来要戏弄我，」 【创卅九 18】「我放声喊起来，他就把衣裳丢在我这里，跑出去了。』」 衣服是当时人的主要财产，但却总是给约瑟带来麻烦。约瑟第一次丢 失衣服，被哥哥们用来欺骗父亲（三十七 31-32），而他自己则被卖；如今 第二次丢失衣裳，被主母用来欺骗主人（17-18 节），而他自己则坐监（20",
