      sourceTextSnippet: "344 亲信。 【创四十 2】「法老就恼怒酒政和膳长这二臣，」 【创四十 3】「把他们下在护卫长府内的监里，就是约瑟被囚的地方。」 【创四十 4】「护卫长把他们交给约瑟，约瑟便伺候他们；他们有些日 子在监里。」 约瑟在监狱里伺候酒政和膳长「有些日子」，正是神给他机会了解法 老的性情和宫内的事务，预备他以后高升。「护卫长」可能还是波提乏， 所以还记得约瑟的忠心可靠。 【创四十 5】「被囚在监之埃及王的酒政和膳长，二人同夜各作一梦， 各梦都有讲解。」 【创四十 6】「到了早晨，约瑟进到他们那里，见他们有愁闷的样子。」 【创四十 7】「他便问法老的二臣，就是与他同囚在他主人府里的，说： 『你们今日为什么面带愁容呢？』」 约瑟虽然身处监狱，却没有让监狱捆住他的心，无论在什么环境中都 殷勤事奉。他放下自己的愁苦，主动关心别人的愁苦，这就成了他的转机。 【创四十 8】「他们对他说：『我们各人做了一梦，没有人能解。』约 瑟说：『解梦不是出于神吗？请你们将梦告诉我。』」 「 解 梦不是出 于神吗」， 意思是只 有神才能 解梦，不要 到监狱之 外找解梦 的术士（四 十一 8）。 【 创 四十 9】 「酒 政便将他",
