      sourceTextSnippet: "346 上图：主前 1981-1975 年古埃及墓葬里一队头顶食物的仆人木偶。现藏于纽约 大都会艺术博物馆。 【创四十 17】「极上的筐子里有为法老烤的各样食物，有飞鸟来吃我 头上筐子里的食物。』」 【创四十 18】「约瑟说：『你的梦是这样解：三个筐子就是三天；」 【创四十 19】「三天之内，法老必斩断你的头，把你挂在木头上，必 有飞鸟来吃你身上的肉。』」 「法老斩断你的头」原文是「法老必从你身上抬起你的头」，和对酒 政说的话差不多，但多了「从你身上」，意思就变成了「身首分离」。 【创四十 20】「到了第三天，是法老的生日，他为众臣仆设摆筵席， 把酒政和膳长提出监来，」 【创四十 21】「使酒政官复原职，他仍旧递杯在法老手中；」 【创四十 22】「但把膳长挂起来，正如约瑟向他们所解的话。」 【创四十 23】「酒政却不记念约瑟，竟忘了他。」 • 约瑟此时经历了 11 年为奴、被囚生活的煎熬（四十一 1），极度渴",
