      sourceTextSource: "pdftotext",
      sourceTextSnippet: "347 望能够恢复自由（15 节）。他既然知道酒政很快会得释放，盼望酒政能救 他出狱的心情自然就更加迫切（14 节）。但人的希望越大，失望也越大， 官复原职的酒政「竟忘了他」，约瑟是多么失望，对神的旨意又是多么茫 然！然而约瑟始终记得那荣耀的结局（三十七 7、9），这个盼望就维持着 他在极度的失望中继续仰望神，接受「耶和华的话试炼他，直等到他所说 的应验了」（诗一百零五 19）。 • 我们如果把盼望寄托在人身上，必然会失望。但在神的掌管之下， 人的「不记念」却成了神的「记念」，因为此时若酒政没有「忘了他」， 而是照着约瑟的请求放他回家（15 节），约瑟就没有机会为法老解梦了（四 十一 14）。因此，人的「记念」或「不记念」都在神的管理之下，顺服神 的人应当安心接受神所允许的环境，在任何环境下都单单仰望神、依靠神。 第 41 章 【创四十一 1】「过了两年，法老做梦，梦见自己站在河边，」 「过了两年」，神的时间到了，祂就让法老也「做梦」。酒政忘记约 瑟的这「两年」，正是神所安排的时间，使约瑟可以学习单单依靠神，而 不再求人（四十 14）；也使约瑟有可能从那些「王的囚犯」（三十九 20） 学习治国之道。「河」原文通常用来指尼罗河。尼罗河是埃及的命脉，每 年定期泛滥，给两岸带来肥沃的淤泥和充裕的水源。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：尼罗河畔的吉萨金字塔群（Giza pyramid complex），摄于 1900 年。",
