      sourceTextSource: "pdftotext",
      sourceTextSnippet: "348 上图：尼罗河畔的吉萨金字塔群（Giza pyramid complex），摄于 1900 年。 【创四十一 2】「有七只母牛从河里上来，又美好又肥壮，在芦荻中吃 草。」 「牛」是古埃及的代表动物，常在尼罗河放牧。「芦荻」原文是从埃 及借用来的字。 上图：主前 1350 年埃及壁画上的牛，现藏于大英博物馆。古埃及的牛没有隆 起的背，有两只伸展的大角。古埃及人通常把牛放在不适合耕种的草场牧养，这 些草场位于远离尼罗河或灌溉系统的地方，或者是潮湿的尼罗河三角洲。古埃及 人用牛来耕种、献祭，并获取肉、奶和皮。许多埃及神祗都以牛的形象出现，如 Hathor、Ptah、Menthu、Atum-Ra。 【创四十一 3】「随后又有七只母牛从河里上来，又丑陋又干瘦，与那 七只母牛一同站在河边。」 【创四十一 4】「这又丑陋又干瘦的七只母牛吃尽了那又美好又肥壮的 七只母牛。法老就醒了。」 【创四十一 5】「他又睡着，第二回做梦，梦见一棵麦子长了七个穗子， 又肥大又佳美，」 【创四十一 6】「随后又长了七个穗子，又细弱又被东风吹焦了。」 春末夏初，从埃及东边沙漠吹来的灼热大风常常会毁坏农作物。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：尼罗河畔的吉萨金字塔群（Giza pyramid complex），摄于 1900 年。",
