      sourceTextSnippet: "349 【创四十一 7】「这细弱的穗子吞了那七个又肥大又饱满的穗子。法老 醒了，不料是个梦。」 上图：主前 1422-1411 年的古埃及壁画，埃及人在打谷。 【创四十一 8】「到了早晨，法老心里不安，就差人召了埃及所有的术 士和博士来；法老就把所做的梦告诉他们，却没有人能给法老圆解。」 古埃及的法老自称是众神在地上的代理人和化身，死后将成为神，不 但拥有最高的行政权力，还是最高祭司和被崇拜的对象。因此，法老还要 找别人解梦，这是一件很不寻常的事情。「术士」指那些专门研究有关秘 术、祭祀礼仪的人，「博士」指星象学家（太二 1）。 【创四十一 9】「那时酒政对法老说：『我今日想起我的罪来。」 神能让酒政「忘了」约瑟（四十 23），也能让酒政「想起」约瑟。人 会忘记约瑟，但神却不会忘记祂所拣选的人：「妇人焉能忘记她吃奶的婴 孩，不怜恤她所生的儿子？即或有忘记的，我却不忘记你」（赛四十九 15）。 但无论是「忘了」还是「想起」，按着神的时间才是最美的。 【创四十一 10】「从前法老恼怒臣仆，把我和膳长下在护卫长府内的 监里。」 【创四十一 11】「我们二人同夜各做一梦，各梦都有讲解。」 【创四十一 12】「在那里同着我们有一个希伯来的少年人，是护卫长 的仆人，我们告诉他，他就把我们的梦圆解，是按着各人的梦圆解的。」 【创四十一 13】「后来正如他给我们圆解的成就了：我官复原职，膳",
