      sourceTextSource: "pdftotext",
      sourceTextSnippet: "351 朝思梦想的机会，约瑟已经等了整整 13 年，但他在这激动人心的时刻却不 是急着表现自己，而是首先承认自己一无所有，将荣耀归于神。因为这 13 年，也是约瑟被神「试炼」（诗一百零五 19）的 13 年，他已经被神炼到一 个完全顺服、谦卑的程度，无论是在囚犯面前，还是在法老面前，他首先 想到的是神。 【创四十一 17】「法老对约瑟说：『我梦见我站在河边，」 【创四十一 18】「有七只母牛从河里上来，又肥壮又美好，在芦荻中 吃草。」 上图：在尼罗河放牧的牛。 【创四十一 19】「随后又有七只母牛上来，又软弱又丑陋又干瘦，在 埃及遍地，我没有见过这样不好的。」 【创四十一 20】 「这又干瘦又丑陋的母牛吃尽了那以先的七只肥母牛，」 【创四十一 21】「吃了以后却看不出是吃了，那丑陋的样子仍旧和先 前一样。我就醒了。」 19 节和 21 节与 3-4 节相比，都有额外的说明。 【创四十一 22】「我又梦见一棵麦子，长了七个穗子，又饱满又佳美，」 【创四十一 23】「随后又长了七个穗子，枯槁细弱，被东风吹焦了。」 【创四十一 24】「这些细弱的穗子吞了那七个佳美的穗子。我将这梦 告诉了术士，却没有人能给我解说。』」",
      sourceEvidenceType: "figure_caption",
