      sourceTextSource: "pdftotext",
      sourceTextSnippet: "353 3. 征收丰年收成的「五分之一」（34 节）。 4. 「聚敛」丰年的余粮（35 节）。 5. 兴建粮仓「积蓄五谷」（35 节）。 【创四十一 37】「法老和他一切臣仆都以这事为妙。」 法老与他的臣仆都没有怀疑约瑟的解梦，也都赞同约瑟的建议，这是 因为「王的心在耶和华手中，好像陇沟的水随意流转」（箴二十一 1）。 【创四十一 38】「法老对臣仆说：『像这样的人，有神的灵在他里头， 我们岂能找得着呢？』」 法老所说的「神」，并不一定指独一真神。 【创四十一 39】「法老对约瑟说：『神既将这事都指示你，可见没有 人像你这样有聪明有智慧。」 【创四十一 40】「你可以掌管我的家；我的民都必听从你的话。惟独 在宝座上我比你大。』」 【创四十一 41】「法老又对约瑟说：『我派你治理埃及全地。』」 【创四十一 42】「法老就摘下手上打印 的戒指，戴在约瑟的手上，给他穿上细麻衣， 把金链戴在他的颈项上，」 上图： 古埃及第 十八王朝 的 末 代 法 老 霍 朗 赫 布 （ Horemheb ， 主 前 1306-1292 年在位）的「打印的戒指」。 上图：古埃及第十八王朝阿蒙霍特普二 世（Amenhotep II，主前 1439-1413 年）的贵 族 Sennefer 穿戴的西麻衣和金链。 【创四十一 43】「又叫约瑟坐他的 副车，喝道的在前呼叫说：『跪下。』 这样，法老派他治理埃及全地。」",
