      sourceTextSource: "pdftotext",
      sourceTextSnippet: "354 • 「家」（40 节）原文是「房子」，指皇宫。「掌管我的家」（40 节） 代表掌管全埃及，职位类似于宰相。约瑟在这 13 年里，从管理波提乏的家 到管理监狱，如今开始管理全埃及。 • 「打印的戒指」 （42 节）就是法老的图章，表示约瑟可以代表法老 在 文件上盖章、发号施令。 • 古代一般的埃及男人上身赤裸，尊贵人才穿「细麻衣」（42 节）。 • 「把金链戴在他的颈项上」（42 节）代表宠信。 • 「副车」紧随于法老的车后，表示约瑟在朝中的地位仅次于法老。 • 「跪下」是由埃及文转来的词，含有让开、回避、屈膝、欢呼等意 思，是埃及壁画中常描绘的礼节。 上图：古埃及第十八王朝法老图坦卡蒙（Tutankhamun，主前 1332–1323 年） 驾战车的壁画。 【创四十一 44】「法老对约瑟说：『我是法老，在埃及全地，若没有 你的命令，不许人擅自办事（原文是动手动脚）。』」 「我是法老」意思是「我以法老这头衔所拥有的权力，在此对你颁布 谕令」，正式表示授权。 【创四十一 45】「法老赐名给约瑟，叫撒发那忒·巴内亚，又将安城 的祭司波提非拉的女儿亚西纳给他为妻。约瑟就出去巡行埃及地。」",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：古埃及第十八王朝法老图坦卡蒙（Tutankhamun，主前 1332–1323 年） 驾战车的壁画。",
