      sourceTextSource: "pdftotext",
      sourceTextSnippet: "355 法老给约瑟起埃及名字，并与埃及贵族联姻，是为了巩固约瑟在埃及 的身份及地位，防止有人对他有偏见或藐视，也是为了把他完全变为埃及 人。但约瑟并没有忘记自己是希伯来人，所以他给两个儿子起的都是希伯 来名字（51-52 节）。「撒发那忒·巴内亚」的字义有多种说法，不能确定。 「波提非拉」的字义是「他是太阳神雷（Re）所赐予的」，「安城」是崇 拜太阳神的中心，后来希腊人称此地为太阳城（Heliopolis）。「安城的祭 司」是当时最重要的祭司之一。「亚西纳」的字义是「属于战争女神（Neith） 的」。 【创四十一 46】「约瑟见埃及王法老的时候年三十岁。他从法老面前 出去，遍行埃及全地。」 • 利未人从「三十岁」开始在会幕任职（民四 3），主耶稣开始传道时 「年纪约有三十岁」（路三 23），约瑟开始治理埃及时「年三十岁」，这 再一次证明酒政把他忘了「两年」（1 节），乃是出于神的安排，神的时间 永远是最好的。 • 十字架的恢复原则就是把人带到 最低，然后将人升到至高，并且得荣耀， 在主耶稣的身上是这样，在约瑟身上也是 这样。主耶稣之所以被神「升为至高」， 是因为祂「自己卑微，存心顺服」（腓二 8）。约瑟之所以能升高，是因为他肯接 受神的手，神把他带到低处，他就顺服神 站在低处，神让他升高，他就顺服神站在 高处，无论是低处还是高处，都让神的旨 意在他身上畅通无阻，显明神的同在（16 节），成就神拯救的计划。 • 神在约瑟身上所成就的十字架的 道路，也是我们被神恢复的道路，也是神 让我们得荣耀的道路。 上图：古埃及第十二王朝法老辛努塞尔",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：古埃及第十二王朝法老辛努塞尔",
