      sourceTextSource: "pdftotext",
      sourceTextSnippet: "356 特二世（Senusret II ，希腊人称之位 Sesostris II）坐像。辛努塞尔特二世于主前 1897-1878 年在位）。据历史记载，他在埃及大规模修建水利工程。根据圣经，主 前 1886 年，约瑟 30 岁出任法老宰相，在七个丰年里兴修粮仓，与辛努塞尔特二 世的历史正好符合。 【创四十一 47】「七个丰年之内，地的出产极丰极盛（原文是一把一 把的），」 【创四十一 48】「约瑟聚敛埃及地七个丰年一切的粮食，把粮食积存 在各城里；各城周围田地的粮食都积存在本城里。」 上图：主前 13 世纪古埃及拉美西姆（Ramesseum）遗址的粮仓。 【创四十一 49】「约瑟积蓄五谷甚多，如同海边的沙，无法计算，因 为谷不可胜数。」 约瑟「积蓄五谷甚多」，实际上是神在通过约瑟预备一切，要把雅各 全家带到埃及，等待迦南人的罪恶满盈（十五 16）。 【创四十一 50】「荒年未到以前，安城的祭司波提非拉的女儿亚西纳 给约瑟生了两个儿子。」 「荒年未到以前」，表明这两个儿子都是在头七年内出生的。 【创四十一 51】「约瑟给长子起名叫玛拿西（就是使之忘了的意思）， 因为他说：『神使我忘了一切的困苦和我父的全家。』」 【创四十一 52】「他给次子起名叫以法莲（就是使之昌盛的意思）， 因为他说：『神使我在受苦的地方昌盛。』」",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：主前 13 世纪古埃及拉美西姆（Ramesseum）遗址的粮仓。",
