      sourceTextSource: "pdftotext",
      sourceTextSnippet: "358 埃及」、「约瑟被带下埃及去」（三十九 1），「犹大离开他弟兄下去」（三 十八 1），这三个「下」原文都是同一个字，背后都是神的手在管理。神任 凭犹大主动地「下」到迦南人中间，经过堕落而悔改；又安排约瑟被动地 「下」到埃及，经过降卑而高升；再兴起饥荒逼着以色列全家「下」埃及， 在与世界隔离的环境里「生养众多」（出一 7），经历「四百年」的苦待以 后（十五 13），将来再从那里回到应许之地。 【创四十二 4】 「但约瑟的兄弟便雅悯，雅各没有打发他和哥哥们同去， 因为雅各说：『恐怕他遭害。』」 「约瑟的十个哥哥」（3 节）和约瑟同父异母，而「便雅悯」与约瑟同 父同母。他此时已经 20 多岁，且已生了许多个儿子（四十六 21）。雅各最 爱的妻子拉结只生两子，他以为约瑟已经丧生（三十七 33），所以怕再失 去仅存的便雅悯（38 节）。从雅各第一次遇到拉结，已经过了将近 53 年， 在这 53 年里，雅各的心里不是用拉结，就是用拉结的儿子代替了神，神若 不把他里面的这个代替拿掉，雅各就不能在神面前成为完全。 【创四十二 5】「来籴粮的人中有以色列的儿子们，因为迦南地也有饥 荒。」 【创四十二 6】 「当时治理埃及地的是约瑟；粜粮给那地众民的就是他。 约瑟的哥哥们来了，脸伏于地，向他下拜。」 「下拜」应验了约瑟从前所做的梦（三十七 7、9)。约瑟的哥哥们认为 卖掉约瑟就可以破碎他的梦（三十七 20），没想到神却偏偏借着卖约瑟来 成就他的梦，没有什么势力可以阻挡神旨意的成就。 上图：卡纳克神庙（Karnak）砂岩上的画，一群外国人正向古埃及第十八王朝",
