      sourceTextSource: "pdftotext",
      sourceTextSnippet: "361 他所做的一切不是为了报复，而是为了试验哥哥们，恢复与弟兄的交通。 【创四十二 25】「约瑟吩咐人把粮食装满他们的器具，把各人的银子 归还在各人的口袋里，又给 他们路上用的食物，人就照 他的话办了。」 约瑟所做的既是恩典， 又是试验哥哥们是否诚实。 上图：主前 13 世纪古埃及 的银瓶，出土于 Tell Basta。钱 币要到主前六世纪才发明，古 代的贸易是用贵金属、宝石、 香料、香以及其他奢侈品按重 量以货易货。银子在古代世界 每 个地 方 都 是很 普 遍的 贸 易 品，埃及没有天然银矿，所以 银子很受欢迎。 【创四十二 26】「他们就把粮食驮在驴上，离开那里去了。」 【创四十二 27】「到了住宿的地方，他们中间有一个人打开口袋，要 拿料喂驴，才看见自己的银子仍在口袋里，」 【创四十二 28】「就对弟兄们说：『我的银子归还了，看哪，仍在我 口袋里！』他们就提心吊胆，战战兢兢地彼此说：『这是神向我们做什么 呢？』」 他们以前在卖约瑟的时候，并没有想到神会鉴察他们。现在看到白来 的银子，却「提心吊胆」，说「这是神向我们做什么呢」。这表明经过了 22 年，神就像改变犹大一样（三十八章），已经在这十位哥哥身上动了工， 使他们逐渐变得敬畏神。 【创四十二 29】「他们来到迦南地、他们的父亲雅各那里，将所遭遇 的事都告诉他，说：」 【创四十二 30】「『那地的主对我们说严厉的话，把我们当作窥探那",
