      sourceTextSource: "pdftotext",
      sourceTextSnippet: "363 第 43 章 【创四十三 1】「那地的饥荒甚大。」 【创四十三 2】「他们从埃及带来的粮食吃尽了，他们的父亲就对他们 说：『你们再去给我籴些粮来。』」 上图:主前 24 世纪古埃及 Seshemnefer IV 墓葬浮雕上的驴，现藏于柏林埃及博 物馆。驴生活在沙漠和半沙漠地带，可以三天不喝水，古代埃及和迦南人都用驴 子驮货物。古代迦南地的驴可能是从埃及进口的。一匹驴驮重 100 公斤左右，十 匹驴能驮一吨粮食，只够雅各全家 70 人能吃一个月（还不算仆人）。 【创四十三 3】「犹大对他说：『那人谆谆地诰诫我们说：“你们的兄 弟若不与你们同来，你们就不得见我的面。”」 【创四十三 4】「你若打发我们的兄弟与我们同去，我们就下去给你籴 粮；」 【创四十三 5】「你若不打发他去，我们就不下去，因为那人对我们说： “你们的兄弟若不与你们同来，你们就不得见我的面。”』」 【创四十三 6】「以色列说：『你们为什么这样害我，告诉那人你们还 有兄弟呢？』」",
