      sourceEvidenceSnippet: "上图:主前 24 世纪古埃及 Seshemnefer IV 墓葬浮雕上的驴，现藏于柏林埃及博 物馆。驴生活在沙漠和半沙漠地带，可以三天不喝水，古代埃及和迦南人都用驴 子驮货物。古代迦南地的驴可能是从埃及进口的。一匹驴驮重 100 公斤左右，十 匹驴能驮一吨粮食，只够雅各全家 70 人能吃一个月（还不算仆人）。",
