      sourceTextSnippet: "366 【创四十三 25】「他们就预备那礼物，等候约瑟晌午来，因为他们听 见要在那里吃饭。」 【创四十三 26】「约瑟来到家里，他们就把手中的礼物拿进屋去给他， 又俯伏在地，向他下拜。」 「下拜」是第二次应验了约瑟从前所做的梦（三十七 7、9；四十二 6）。 【创四十三 27】「约瑟问他们好，又问：『你们的父亲——就是你们 所说的那老人家平安吗？他还在吗？』」 【创四十三 28】「他们回答说：『你仆人——我们的父亲平安；他还 在。』于是他们低头下拜。」 【创四十三 29】「约瑟举目看见他同母的兄弟便雅悯，就说：『你们 向我所说那顶小的兄弟就是这位吗？』又说：『小儿啊，愿神赐恩给你！』」 【 创四十 三 30 】 「约瑟 爱弟之 情发动， 就急忙 寻找可 哭之地， 进入自 己的屋 里，哭了 一场。」 这 是约瑟 与兄弟 们重逢 后第二 次的哭",
