      sourceTextSource: "pdftotext",
      sourceTextSnippet: "368 左图：古埃及第十八王朝时期（主前 1479-1425 年）的饮酒杯，现藏于纽约大都会博物馆。 【创四十四 3】「天一亮就打发那些人带着 驴走了。」 【创四十四 4】「他们出城走了不远，约瑟 对家宰说：『起来，追那些人去，追上了就对他 们说：“你们为什么以恶报善呢？」 【创四十四 5】「这不是我主人饮酒的杯吗？岂不是他占卜用的吗？你 们这样行是作恶了。”』」 古埃及人将酒杯倒满水，然后观察水的波纹进行占卜。约瑟并不占卜， 他说「占卜用的」杯，可能是为了凸显罪行的严重。 【创四十四 6】家宰追上他们，将这些话对他们说了。7 他们回答说： 『我主为什么说这样的话呢？你仆人断不能做这样的事。8 你看，我们从前 在口袋里所见的银子，尚且从迦南地带来还你，我们怎能从你主人家里偷 窃金银呢？9 你仆人中无论在谁那里搜出来，就叫他死，我们也作我主的奴 仆。』」10 家宰说：『现在就照你们的话行吧！在谁那里搜出来，谁就作 我的奴仆；其余的都没有罪。』 家宰说「其余的都没有罪」，是故意要给他们提供一个开脱自己的机 会，试验他们是否会撇下便雅悯不管。 【创四十四 11】 「于是他们各人急忙把口袋卸在地上，各人打开口袋。」 【创四十四 12】「家宰就搜查，从年长的起到年幼的为止，那杯竟在 便雅悯的口袋里搜出来。」 【创四十四 13】「他们就撕裂衣服，各人把驮子抬在驴上，回城去了。」 哥哥们从前一起「同谋要害死」（三十七 18）约瑟，平分卖约瑟的「二 十舍客勒银子」（三十七 28）。现在他们更有理由把便雅悯撇下，因为家 宰建议「在谁那里搜出来，谁就作我的奴仆；",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "左图：古埃及第十八王朝时期（主前 1479-1425 年）的饮酒杯，现藏于纽约大都会博物馆。",
