      storedAbsolutePath: "/Users/simon/OHB/Resources/01_创世记/文档图片内容提取_20260515_121143/CMC-01_副本/p377_img207_300x257.png",
      sourceTextSource: "pdftotext",
      sourceTextSnippet: "369 显露无遗。 【创四十四 14】「犹大和他弟兄们来到约瑟的屋中，约瑟还在那里， 他们就在他面前俯伏于地。」 「俯伏于地」是第三次应验了约瑟从前所做的梦（三十七 7、9；四十 二 6；四十三 26-28）。 【创四十四 15】「约瑟对他们说：『你们做的是什么事呢？你们岂不 知像我这样的人必能占卜吗？』」 约瑟并不占卜，他只是故摆姿态，装作会占卜的埃及人来试验他的哥 哥们。 【创四十四 16】「犹大说：『我们对我主说什么呢？还有什么话可说 呢？我们怎能自己表白出来呢？神已经查出仆人的罪孽了。我们与那在他 手中搜出杯来的都是我主的奴仆。』」 「仆人」原文是复数词，「神已经查出仆人的罪孽了」，是犹大代表 众弟兄向神认罪，因为他们先前出卖了约瑟（四十二 21-22）。因此犹大没 有辩白自己，也没有顺着家宰（10 节）和约瑟故意给的台阶（17 节）开脱 自己，而是坚持「我们与那在他手中搜出杯来的都是我主的奴仆」，要与 弟弟同生死。 【创四十四 17】「约瑟说：『我断不能这样行！在谁的手中搜出杯来， 谁就作我的奴仆；至于你们，可以平平安安地上你们父亲那里去。』」 约瑟再次提出诱人的条件，是要再次试验哥哥们是否真心。 【创四十四 18】「犹大挨近他，说：『我主啊，求你容仆人说一句话 给我主听，不要向仆人发烈怒，因为你如同法老一样。」 左图：古埃及第十二王朝法老辛努塞尔特 三世（Senusret III，希腊人称之为 Sesostris III） 的圣甲虫形戒指，现藏于纽约大都会艺术博物 馆。辛努塞尔特三世于荒年的第二年即位，加 强了中央政权，削弱了贵族的权势和影响。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "左图：古埃及第十二王朝法老辛努塞尔特 三世（Senusret III，希腊人称之为 Sesostris III） 的圣甲虫形戒指，现藏于纽约大都会艺术博物 馆。辛努塞尔特三世于荒年的第二年即位，加 强了中央政权，削弱了贵族的权势和影响。",
