      sourceTextSource: "pdftotext",
      sourceTextSnippet: "373 八 28），使神美善荣耀的旨意得以成就。 • 此时大约是主 前 1877 年，辛努塞尔 特三世法老（Senusret III）于主前 1878 年刚 刚继位。「法老的父」 这个称号可能表明新 法老对约瑟的信赖，也 可能是法老顾问的头 衔。 【创四十五 9】「你们要赶紧上到我父亲那里，对他说：“你儿子约瑟 这样说：神使我作全埃及的主，请你下到我这里来，不要耽延。」 经过了 22 年，约瑟对他父亲的第一句话就是「神」。 【创四十五 10】「你和你的儿子孙子，连牛群羊群，并一切所有的， 都可以住在歌珊地，与我相近。」 「 歌 珊 地」在兰塞境 内（四十七 11），可能位 于埃及尼罗河 三角洲东边， 肥沃富庶，是 全埃及最适合 放牧的地方， 又靠近埃及的 东北边界，将 来回迦南也比 较方便。 上图：今日 尼罗河三角洲",
