      sourceTextSource: "pdftotext",
      sourceTextSnippet: "375 【创四十五 17】「法老对约瑟说：『你吩咐你的弟兄们说：“你们要 这样行：把驮子抬在牲口上，起身往迦南地去。」 【创四十五 18】「将你们的父亲和你们的眷属都搬到我这里来，我要 把埃及地的美物赐给你们，你们也要吃这地肥美的出产。」 【创四十五 19】「现在我吩咐你们要这样行：从埃及地带着车辆去， 把你们的孩子和妻子，并你们的父亲都搬来。」 「车辆」指牛拉动的双轮或四轮运输车。当时车辆的使用还不普遍， 一般人没有车，因此这些车辆将成为约瑟还活着、并大有权柄的证据（27 节）。 【创四十五 20】「你们眼中不要爱惜你们的家具，因为埃及全地的美 物都是你们的。”』」 【创四十五 21】「以色列的儿子们就如此行。约瑟照着法老的吩咐给 他们车辆和路上用的食物，」 【创四十五 22】「又给他们各人一套衣服，惟独给便雅悯三百银子， 五套衣服；」 【创四十五 23】「送给他父亲公驴十匹，驮着埃及的美物，母驴十匹， 驮着粮食与饼和菜，为他父亲路上用。」 左图：主前 11 世纪古埃及壁画 上的食物。现藏于 大英博物馆。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "左图：主前 11 世纪古埃及壁画 上的食物。现藏于 大英博物馆。",
