      sourceTextSnippet: "380 上图：古埃及第十八王朝图坦卡蒙法老（Tutankhamen，主前 1332–1323 年） 的金马车。 【创四十六 30】「以色列对约瑟说：『我既得见你的面，知道你还在， 就是死我也甘心。』」 • 从约瑟被卖到父子重逢，圣经中每次记载雅各说话都会提到「死」 （三十七 5；四十二 2、38；四十三 14；四十五 28）。而重逢之后，雅各 每次所说的话也都与「死」有关（四十六 30；四十七 9、29；四十八 7；四 十九 29）。雅各在重逢之前所说的「死」，带着对世界的消极绝望；而重 逢之后所说的「死」，则带着对神应许的积极盼望。 • 神对每一个信徒的拆毁，也是让我们彻底认识这个世界「死」的结 局，因此愿意「向罪死」（罗六 10）；神对每一个信徒的建立，也是让我 们看到「向罪死」乃是要带出「向神活」（罗六 10）的积极果效，因此我 们「无论是生是死，总叫基督在我身上照常显大」（腓一 10）。 【创四十六 31】「约瑟对他的弟兄和他父的全家说：『我要上去告诉 法老，对他说：“我的弟兄和我父的全家从前在迦南地，现今都到我这里 来了。」 【创四十六 32】「他们本是牧羊的人，以养牲畜为业；他们把羊群牛",
