      sourceTextSnippet: "382 第 47 章 【创四十七 1】「约瑟进去告诉法老说：『我的父亲和我的弟兄带着羊 群牛群，并一切所有的，从迦南地来了，如今在歌珊地。』」 【创四十七 2】「约瑟从他弟兄中挑出五个人来，引他们去见法老。」 「五」这个数字在许多古埃及神话中出现，五角星被当作一种神秘符 号，因此「五」可能被埃及人当作吉祥数目（四十三 34；四十五 22；赛十 九 18）。 【创四十七 3】「法老问约瑟的弟兄说：『你们以何事为业？』他们对 法老说：『你仆人是牧羊的，连我们的祖宗也是牧羊的。』」 约瑟的弟兄们照着约瑟的嘱咐，强调自己是埃及人所厌恶的牧羊人， 目的是与埃及人有明确的分别，将来不被埃及所捆绑。 【创四十七 4】「他们又对法老说：『迦南地的饥荒甚大，仆人的羊群 没有草吃，所以我们来到这地寄居。现在求你容仆人住在歌珊地。』」 【创四十七 5】「法老对约瑟说：『你父亲和你弟兄到你这里来了，」 【创四十七 6】「埃及地都在你面前，只管叫你父亲和你弟兄住在国中",
