      sourceTextSource: "pdftotext",
      sourceTextSnippet: "385 上图：尼罗河上游的埃塞俄比亚高原的季节性暴雨带来下游每年 6-10 月定期 泛滥，洪水溢出河床，淹没两岸农田，洪水退后会留下一层厚厚的河泥，形成肥 沃的土壤。 【创四十七 20】「于是约瑟为法老买了埃及所有的地，埃及人因被饥 荒所迫，各都卖了自己的田地；那地就都归了法老。」 约瑟的政策，使埃及的土地都成为法老的产业，居民成为法老的租户。 下图：辛努塞尔特三世像，现藏于布鲁克林博物馆。辛努塞尔特三世（Senusret III，希腊人称之为 Sesostris III）于主前 1878-1839 年在位。根据历史记载，辛努塞 尔特三世巩固埃及统治，积极促进改革，加强中央政权，削弱贵族的权势和影响。 根据圣经，他于荒年的第二年即位，约瑟很可能是在最后一个荒年用粮食换取了 全埃及的土地，增强了中央政权，与历史记载相符。荒年的第三年，即主前 1877 年，以色列全家下埃及。主前 1860 年，雅各在埃及去世，也在辛努塞尔特三世统 治期间。",
