      sourceTextSnippet: "393 上图：撒马利亚大祭司和他的摩西五经，摄于 1920 年。大约主前 722 年，亚 述攻取撒马利亚，将北国以色列十个支派掳到亚述，又「从巴比伦、古他、亚瓦、 哈马，和西法瓦音迁移人来，安置在撒马利亚的城邑，代替以色列人」（王下十 七 24），这些人与北国剩下的「以法莲和玛拿西人」（代下三十 1）通婚，后裔 被称为撒马利亚人，自称是以法莲和玛拿西的后代。另外，印度东南部安得拉邦 的 Telugu 犹太人、一些波斯犹太人也自称是以法莲的后代。 【创四十八 14】「以色列伸出右手来，按在以法莲的头上（以法莲乃 是次子），又剪搭过左手来，按在玛拿西的头上（玛拿西原是长子）。」 雅各的「右手」本来应该按在长子玛拿西的头上，现在却故意按在次",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：撒马利亚大祭司和他的摩西五经，摄于 1920 年。大约主前 722 年，亚 述攻取撒马利亚，将北国以色列十个支派掳到亚述，又「从巴比伦、古他、亚瓦、 哈马，和西法瓦音迁移人来，安置在撒马利亚的城邑，代替以色列人」（王下十 七 24），这些人与北国剩下的「以法莲和玛拿西人」（代下三十 1）通婚，后裔 被称为撒马利亚人，自称是以法莲和玛拿西的后代。另外，印度东南部安得拉邦 的 Telugu 犹太人、一些波斯犹太人也自称是以法莲的后代。",
