      sourceTextSource: "pdftotext",
      sourceTextSnippet: "394 子以法莲的头上。 上图：两名 Bnei Menashe 玛拿西支派后裔以色列士兵。大约主前 722 年，亚 述攻取撒马利亚，将北国以色列十个支派掳到亚述，「把他们安置在哈腊与歌散 的哈博河边，并玛代人的城邑」（王下十七 6）。亚历山大大帝征服波斯帝国以后， 玛拿西支派可能沿着丝绸之路向东逃亡，部分在印度东北的 Mizoram 以及 Manipur 省落脚，从 20 世纪开始自称是玛拿西的后裔。2005 年，DNA 测试显示一些 Bnei Menashe 人的女性的 MtDNA 有中东血统，尽管存在争议，但仍被犹太大拉比正式 承认属于失踪的支派，符合以色列回归法。至今已有 3000 多 Bnei Menashe 人移民 以色列。 【创四十八 15】「他就给约瑟祝福说：『愿我祖亚伯拉罕和我父以撒 所事奉的神，就是一生牧养我直到今日的神，」 【创四十八 16】「救赎我脱离一切患难的那使者，赐福与这两个童子。 愿他们归在我的名下，和我祖亚伯拉罕、我父以撒的名下，又愿他们在世 界中生养众多。』」 • 「我祖亚伯拉罕和我父以撒所事奉的神」（15 节），表明雅各承受 神对亚伯拉罕和以撒的应许（三十五 12），也代表雅各对神客观的认识。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：两名 Bnei Menashe 玛拿西支派后裔以色列士兵。大约主前 722 年，亚 述攻取撒马利亚，将北国以色列十个支派掳到亚述，「把他们安置在哈腊与歌散 的哈博河边，并玛代人的城邑」（王下十七 6）。亚历山大大帝征服波斯帝国以后， 玛拿西支派可能沿着丝绸之路向东逃亡，部分在印度东北的 Mizoram 以及 Manipur 省落脚，从 20 世纪开始自称是玛拿西的后裔。2005 年，DNA 测试显示一些 Bnei Menashe 人的女性的 MtDNA 有中东血统，尽管存在争议，但仍被犹太大拉比正式 承认属于失踪的支派，符合以色列回归法。至今已有 3000 多 Bnei Menashe 人移民 以色列。",
