      storedRelativePath: "CMC-01_副本/p405_img221_720x599.png",
      storedAbsolutePath: "/Users/simon/OHB/Resources/01_创世记/文档图片内容提取_20260515_121143/CMC-01_副本/p405_img221_720x599.png",
      sourceTextSource: "pdftotext",
      sourceTextSnippet: "397 （28 节）。虽然此时雅各的外体已经衰残到油尽灯枯的地步，里面却满了 神启示的光，神宝座上所有的意念，他都能完全地接受下来。 【创四十九 2】「雅各的儿子们，你们要聚集而听，要听你们父亲以色 列的话。」 「雅各 」的字义是「抓住脚后跟的人」或 「取代者」，是雅各出 生时的名字。「以色列 」的字义是「神胜过」，也可以表示「愿神（为 他）较力」，是神给雅各起的名字（三十二 28）。圣经有时以平行诗句的 方式交替使用这两个名字（创四十九 7、24；出一 1；十九 3；赛四十 27）， 并不一定都有特殊的属灵含义。2-27 节原文的形式是诗歌。 以色列十二支派标志的现代设计之一。从左上到右下依次是：亚设（棕榈树） 、 便雅悯（狼）、但（蛇）、迦得（军营）、以萨迦（驴）、约瑟（麦穗）、犹大 （狮子）、利未（以弗得）、拿弗他利（母鹿）、流便（波浪）、西缅（城堡）、 西布伦（船）。",
      sourceEvidenceType: "verse_context",
      sourceEvidenceSnippet: "【创四十九 2】「雅各的儿子们，你们要聚集而听，要听你们父亲以色 列的话。」 「雅各 」的字义是「抓住脚后跟的人」或 「取代者」，是雅各出 生时的名字。「以色列 」的字义是「神胜过」，也可以表示「愿神（为 他）较力」，是神给雅各起的名字（三十二 28）。圣经有时以平行诗句的 方式交替使用这两个名字（创四十九 7、24；出一 1；十九 3；赛四十 27）， 并不一定都有特殊的属灵含义。2-27 节原文的形式是诗歌。",
      sourceEvidencePage: 405,
      sourceEvidenceOrigin: "same-page",
