      sourceTextSnippet: "400 【创四十九 10】「圭必不离犹大，杖必不离他两脚之间，直等细罗（就 是赐平安者）来到，万民都必归顺。」 • 这是预言犹大的后裔必要在国度中长久掌握王权。犹大支派的大卫 是以色列史上最伟大的王（撒下五 4-5），弥赛亚将坐在大卫的宝座上「直 到永远」（撒下七 16）。「圭」原文是「权杖」，「杖」原文是「立法者」， 都象征王权，「他两脚之间」指他的后裔。国度的君王要出自犹大的后裔。 • 「细罗」意思是「赐平安者」，预言弥赛亚。当弥赛亚的国度降临 时（结二十一 27），「万民都必归顺」祂，全地都要满了平安（赛二 2-4）。 上图：古埃及第十八王朝图坦卡蒙法老（主前 1332–1323 年，Tutankhamun） 手持的「圭」，就是象征王权的权杖（Scepter）。 【创四十九 11】「犹大把小驴拴在葡萄树上，把驴驹拴在美好的葡萄 树上。他在葡萄酒中洗了衣服，在葡萄汁中洗了袍褂。」 【创四十九 12】「他的眼睛必因酒红润；他的牙齿必因奶白亮。」 • 驴不是安份的动物，把驴拴在葡萄树上，会使葡萄树被连根拔起或 叶子被吃掉，只有葡萄太多才会不在乎这样做。「在葡萄酒中洗了衣服， 在葡萄汁中洗了袍褂」（11 节），也都是预言国度的丰富。 • 主耶稣所行的第一个神迹，就是在加利利的迦拿用水变酒，显出祂 丰富的荣耀（约二 11）。",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图：古埃及第十八王朝图坦卡蒙法老（主前 1332–1323 年，Tutankhamun） 手持的「圭」，就是象征王权的权杖（Scepter）。",
