      sourceTextSnippet: "402 上图：虺，就是角蝰（Cerastes）。主要分布于北非、阿拉伯、西奈半岛和南 地的沙漠地带，双眼眶上有一对竖立的刺状角鳞，毒性很强。 【创四十九 18】「耶和华啊，我向来等候祢的救恩。」 可能雅各宣告了但支派后裔的末后的情形之后（17 节），自己也非常 震惊，所以用祷告把这忧虑卸给神。 【创四十九 19】「迦得必被敌军追逼，他却要追逼他们的脚跟。」 迦得支派将来分得的土地在约旦河东边（书十三 24-28），经常受到沙 漠民族的侵袭（士十 8），但他们还是有能力得胜（代上五 18-22）。「敌 军 」和「追逼 」原文都包括「迦得 」的辅音，是双关语。 【创四十九 20】「亚设之地必出肥美的粮食，且出君王的美味。」 亚设支派将来分得的土地靠近地中海（书十九 24-31），拥有肥沃的平 原和通到海口的贸易路线，物产丰盛，就像「把脚蘸在油中」（申三十三 24）。「亚设」名字的意思是「快乐的」，「美味」原文是「精致的、愉 悦」，是双关语。 【创四十九 21】「拿弗他利是被释放的母鹿，他出嘉美的言语。」 拿弗他利支派将来分得的土地在山地，「被释放的母鹿」形容灵活矫 捷（诗十八 33），后来拿弗他利支派曾在争战中有出色的表现（士四 6、",
