      sourceTextSnippet: "403 16）。主耶稣传福音的基地迦百农「在西布伦和拿弗他利的边界上」（太 四 13），主耶稣的门徒除了卖主的犹大，全部都来自拿弗他利地。因此「他 出嘉美的言语」，可能预言福音将由拿弗他利传开。 【创四十九 22】「约瑟是多结果子的树枝，是泉旁多结果的枝子；他 的枝条探出墙外。」 「多结果子的树枝」，预言摩西时代属约瑟的以法莲和玛拿西两个支 派合计人数比以色列任何一个支派都多（民廿六 28-34）。「他的枝条探出 墙外」，预言玛拿西的半个支派在约旦河东占有大幅土地（书十三 29-31； 十六 1-十七 11）。 【创四十九 23】「弓箭手将他苦害，向他射箭，逼迫他。」 【创四十九 24】「但他的弓仍旧坚硬；他的手健壮敏捷。这是因以色",
      sourceEvidenceType: "figure_caption",
      sourceEvidenceSnippet: "上图:美国国徽是美国国玺（Great Seal of the United States）的正面图案，1782 年开始采用。图案中象征美国最初 13 个州的 13 颗五角星排列成大卫星的形状， 而白头海雕左右爪分别抓着有 13 棵橄榄的树枝和 13 支箭，使人联想起雅各的预 言：「约瑟是多结果子的树枝，是泉旁多结果的枝子；他的枝条探出墙外。弓箭 手将他苦害，向他射箭，逼迫他。但他的弓仍旧坚硬；他的手健壮敏捷。这是因 以色列的牧者，以色列的磐石——就是雅各的大能者」（创四十九 22-24）。而玛 拿西实际上是第 13 个支派，因此 19 世纪末作家 C. A. L. Totten 称之为「玛拿西之 玺 Great Seal of Manasseh」。",
