      sourceTextSource: "pdftotext",
      sourceTextSnippet: "406 上图：古埃及壁画中，胡狼头人身的死神阿努比斯（Anubis）正在制作木乃伊。 在古埃及神话中，是阿努比斯发明了木乃伊的制作方法，将被谋害的奥西里斯 （Osiris）制作成木乃伊，并协助他复活成为冥王。因此，古埃及人制作木乃伊的 目的也是为了复活永生，法老的熏尸过程都有祭司念咒祈祷，并放进圣甲虫或荷 鲁斯之眼（The Eye of Horus）的护身符。约瑟请医生熏尸，就避免了这些异教仪式。 【创五十 3】「熏尸的常例是四十天；那四十天满了，埃及人为他哀哭 了七十天。」 「七十天」包括熏尸的「四十天」。为雅各哀哭的日子只比为法老王 所定的七十二天少了两天，表明他享受了极大的哀荣。 【创五十 4】「为他哀哭的日子过了，约瑟对法老家中的人说：『我若 在你们眼前蒙恩，请你们报告法老说：」 可能约瑟正在守丧期间，所以不能亲自面见法老（四十一 14），必须 托人转告。 【创五十 5】「“我父亲要死的时候叫我起誓说：你要将我葬在迦南地， 在我为自己所掘的坟墓里。”现在求你让我上去葬我父亲，以后我必回来。』」 【创五十 6】「法老说：『你可以上去，照着你父亲叫你起的誓，将他 葬埋。』」 约瑟身为一国的宰相，除非获得法老的批准，是不能随便离开的。法 老信任约瑟，表明约瑟多年来言行合一，很有信用。 【创五十 7】「于是约瑟上去葬他父亲。与他一同上去的，有法老的臣",
